INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 6, E'Then answered the LORD unto Job out of the whirlwind, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 7, E'Gird up thy loins now like a man: I will demand of thee, and declare thou unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 8, E'Wilt thou also disannul my judgment? wilt thou condemn me, that thou mayest be righteous?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 9, E'Hast thou an arm like God? or canst thou thunder with a voice like him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 10, E'Deck thyself now with majesty and excellency; and array thyself with glory and beauty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 11, E'Cast abroad the rage of thy wrath: and behold every one that is proud, and abase him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 12, E'Look on every one that is proud, and bring him low; and tread down the wicked in their place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 13, E'Hide them in the dust together; and bind their faces in secret.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 14, E'Then will I also confess unto thee that thine own right hand can save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 15, E'Behold now behemoth, which I made with thee; he eateth grass as an ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 16, E'Lo now, his strength is in his loins, and his force is in the navel of his belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 17, E'He moveth his tail like a cedar: the sinews of his stones are wrapped together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 18, E'His bones are as strong pieces of brass; his bones are like bars of iron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 19, E'He is the chief of the ways of God: he that made him can make his sword to approach unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 20, E'Surely the mountains bring him forth food, where all the beasts of the field play.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 21, E'He lieth under the shady trees, in the covert of the reed, and fens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 22, E'The shady trees cover him with their shadow; the willows of the brook compass him about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 23, E'Behold, he drinketh up a river, and hasteth not: he trusteth that he can draw up Jordan into his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 40, 24, E'He taketh it with his eyes: his nose pierceth through snares.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 1, E'Canst thou draw out leviathan with an hook? or his tongue with a cord which thou lettest down?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 2, E'Canst thou put an hook into his nose? or bore his jaw through with a thorn?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 3, E'Will he make many supplications unto thee? will he speak soft words unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 4, E'Will he make a covenant with thee? wilt thou take him for a servant for ever?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 5, E'Wilt thou play with him as with a bird? or wilt thou bind him for thy maidens?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 6, E'Shall the companions make a banquet of him? shall they part him among the merchants?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 7, E'Canst thou fill his skin with barbed irons? or his head with fish spears?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 8, E'Lay thine hand upon him, remember the battle, do no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 9, E'Behold, the hope of him is in vain: shall not one be cast down even at the sight of him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 10, E'None is so fierce that dare stir him up: who then is able to stand before me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 11, E'Who hath prevented me, that I should repay him? whatsoever is under the whole heaven is mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 12, E'I will not conceal his parts, nor his power, nor his comely proportion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 13, E'Who can discover the face of his garment? or who can come to him with his double bridle?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 14, E'Who can open the doors of his face? his teeth are terrible round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 15, E'His scales are his pride, shut up together as with a close seal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 16, E'One is so near to another, that no air can come between them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 17, E'They are joined one to another, they stick together, that they cannot be sundered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 18, E'By his neesings a light doth shine, and his eyes are like the eyelids of the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 19, E'Out of his mouth go burning lamps, and sparks of fire leap out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 20, E'Out of his nostrils goeth smoke, as out of a seething pot or caldron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 21, E'His breath kindleth coals, and a flame goeth out of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 22, E'In his neck remaineth strength, and sorrow is turned into joy before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 23, E'The flakes of his flesh are joined together: they are firm in themselves; they cannot be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 24, E'His heart is as firm as a stone; yea, as hard as a piece of the nether millstone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 25, E'When he raiseth up himself, the mighty are afraid: by reason of breakings they purify themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 26, E'The sword of him that layeth at him cannot hold: the spear, the dart, nor the habergeon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 27, E'He esteemeth iron as straw, and brass as rotten wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 28, E'The arrow cannot make him flee: slingstones are turned with him into stubble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 29, E'Darts are counted as stubble: he laugheth at the shaking of a spear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 30, E'Sharp stones are under him: he spreadeth sharp pointed things upon the mire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 31, E'He maketh the deep to boil like a pot: he maketh the sea like a pot of ointment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 32, E'He maketh a path to shine after him; one would think the deep to be hoary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 33, E'Upon earth there is not his like, who is made without fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 41, 34, E'He beholdeth all high things: he is a king over all the children of pride.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 1, E'Then Job answered the LORD, and said,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 2, E'I know that thou canst do every thing, and that no thought can be withholden from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 3, E'Who is he that hideth counsel without knowledge? therefore have I uttered that I understood not; things too wonderful for me, which I knew not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 4, E'Hear, I beseech thee, and I will speak: I will demand of thee, and declare thou unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 5, E'I have heard of thee by the hearing of the ear: but now mine eye seeth thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 6, E'Wherefore I abhor myself, and repent in dust and ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 7, E'And it was so, that after the LORD had spoken these words unto Job, the LORD said to Eliphaz the Temanite, My wrath is kindled against thee, and against thy two friends: for ye have not spoken of me the thing that is right, as my servant Job hath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 8, E'Therefore take unto you now seven bullocks and seven rams, and go to my servant Job, and offer up for yourselves a burnt offering; and my servant Job shall pray for you: for him will I accept: lest I deal with you after your folly, in that ye have not spoken of me the thing which is right, like my servant Job.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 9, E'So Eliphaz the Temanite and Bildad the Shuhite and Zophar the Naamathite went, and did according as the LORD commanded them: the LORD also accepted Job.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 10, E'And the LORD turned the captivity of Job, when he prayed for his friends: also the LORD gave Job twice as much as he had before.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 11, E'Then came there unto him all his brethren, and all his sisters, and all they that had been of his acquaintance before, and did eat bread with him in his house: and they bemoaned him, and comforted him over all the evil that the LORD had brought upon him: every man also gave him a piece of money, and every one an earring of gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 12, E'So the LORD blessed the latter end of Job more than his beginning: for he had fourteen thousand sheep, and six thousand camels, and a thousand yoke of oxen, and a thousand she asses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 13, E'He had also seven sons and three daughters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 14, E'And he called the name of the first, Jemima; and the name of the second, Kezia; and the name of the third, Kerenhappuch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 15, E'And in all the land were no women found so fair as the daughters of Job: and their father gave them inheritance among their brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 16, E'After this lived Job an hundred and forty years, and saw his sons, and his sonsâ€™ sons, even four generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'ce6ce818-46b8-4c2c-a508-1fe7fbeeae9f', 42, 17, E'So Job died, being old and full of days.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Job') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 1, E'Blessed is the man that walketh not in the counsel of the ungodly, nor standeth in the way of sinners, nor sitteth in the seat of the scornful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 2, E'But his delight is in the law of the LORD; and in his law doth he meditate day and night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 3, E'And he shall be like a tree planted by the rivers of water, that bringeth forth his fruit in his season; his leaf also shall not wither; and whatsoever he doeth shall prosper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 4, E'The ungodly are not so: but are like the chaff which the wind driveth away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 5, E'Therefore the ungodly shall not stand in the judgment, nor sinners in the congregation of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 1, 6, E'For the LORD knoweth the way of the righteous: but the way of the ungodly shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 1, E'Why do the heathen rage, and the people imagine a vain thing?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 2, E'The kings of the earth set themselves, and the rulers take counsel together, against the LORD, and against his anointed, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 3, E'Let us break their bands asunder, and cast away their cords from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 4, E'He that sitteth in the heavens shall laugh: the LORD shall have them in derision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 5, E'Then shall he speak unto them in his wrath, and vex them in his sore displeasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 6, E'Yet have I set my king upon my holy hill of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 7, E'I will declare the decree: the LORD hath said unto me, Thou art my Son; this day have I begotten thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 8, E'Ask of me, and I shall give thee the heathen for thine inheritance, and the uttermost parts of the earth for thy possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 9, E'Thou shalt break them with a rod of iron; thou shalt dash them in pieces like a potterâ€™s vessel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 10, E'Be wise now therefore, O ye kings: be instructed, ye judges of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 11, E'Serve the LORD with fear, and rejoice with trembling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 2, 12, E'Kiss the Son, lest he be angry, and ye perish from the way, when his wrath is kindled but a little. Blessed are all they that put their trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 1, E'Lord, how are they increased that trouble me! many are they that rise up against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 2, E'Many there be which say of my soul, There is no help for him in God. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 3, E'But thou, O LORD, art a shield for me; my glory, and the lifter up of mine head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 4, E'I cried unto the LORD with my voice, and he heard me out of his holy hill. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 5, E'I laid me down and slept; I awaked; for the LORD sustained me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 6, E'I will not be afraid of ten thousands of people, that have set themselves against me round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 7, E'Arise, O LORD; save me, O my God: for thou hast smitten all mine enemies upon the cheek bone; thou hast broken the teeth of the ungodly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 3, 8, E'Salvation belongeth unto the LORD: thy blessing is upon thy people. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 1, E'Hear me when I call, O God of my righteousness: thou hast enlarged me when I was in distress; have mercy upon me, and hear my prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 2, E'O ye sons of men, how long will ye turn my glory into shame? how long will ye love vanity, and seek after leasing? Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 3, E'But know that the LORD hath set apart him that is godly for himself: the LORD will hear when I call unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 4, E'Stand in awe, and sin not: commune with your own heart upon your bed, and be still. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 5, E'Offer the sacrifices of righteousness, and put your trust in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 6, E'There be many that say, Who will shew us any good? LORD, lift thou up the light of thy countenance upon us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 7, E'Thou hast put gladness in my heart, more than in the time that their corn and their wine increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 4, 8, E'I will both lay me down in peace, and sleep: for thou, LORD, only makest me dwell in safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 1, E'Give ear to my words, O LORD, consider my meditation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 2, E'Hearken unto the voice of my cry, my King, and my God: for unto thee will I pray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 3, E'My voice shalt thou hear in the morning, O LORD; in the morning will I direct my prayer unto thee, and will look up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 4, E'For thou art not a God that hath pleasure in wickedness: neither shall evil dwell with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 5, E'The foolish shall not stand in thy sight: thou hatest all workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 6, E'Thou shalt destroy them that speak leasing: the LORD will abhor the bloody and deceitful man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 7, E'But as for me, I will come into thy house in the multitude of thy mercy: and in thy fear will I worship toward thy holy temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 8, E'Lead me, O LORD, in thy righteousness because of mine enemies; make thy way straight before my face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 9, E'For there is no faithfulness in their mouth; their inward part is very wickedness; their throat is an open sepulchre; they flatter with their tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 10, E'Destroy thou them, O God; let them fall by their own counsels; cast them out in the multitude of their transgressions; for they have rebelled against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 11, E'But let all those that put their trust in thee rejoice: let them ever shout for joy, because thou defendest them: let them also that love thy name be joyful in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 5, 12, E'For thou, LORD, wilt bless the righteous; with favour wilt thou compass him as with a shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 1, E'O LORD, rebuke me not in thine anger, neither chasten me in thy hot displeasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 2, E'Have mercy upon me, O LORD; for I am weak: O LORD, heal me; for my bones are vexed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 3, E'My soul is also sore vexed: but thou, O LORD, how long?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 4, E'Return, O LORD, deliver my soul: oh save me for thy merciesâ€™ sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 5, E'For in death there is no remembrance of thee: in the grave who shall give thee thanks?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 6, E'I am weary with my groaning; all the night make I my bed to swim; I water my couch with my tears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 7, E'Mine eye is consumed because of grief; it waxeth old because of all mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 8, E'Depart from me, all ye workers of iniquity; for the LORD hath heard the voice of my weeping.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 9, E'The LORD hath heard my supplication; the LORD will receive my prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 6, 10, E'Let all mine enemies be ashamed and sore vexed: let them return and be ashamed suddenly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 1, E'O LORD my God, in thee do I put my trust: save me from all them that persecute me, and deliver me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 2, E'Lest he tear my soul like a lion, rending it in pieces, while there is none to deliver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 3, E'O LORD my God, if I have done this; if there be iniquity in my hands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 4, E'If I have rewarded evil unto him that was at peace with me; (yea, I have delivered him that without cause is mine enemy:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 5, E'Let the enemy persecute my soul, and take it; yea, let him tread down my life upon the earth, and lay mine honour in the dust. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 6, E'Arise, O LORD, in thine anger, lift up thyself because of the rage of mine enemies: and awake for me to the judgment that thou hast commanded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 7, E'So shall the congregation of the people compass thee about: for their sakes therefore return thou on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 8, E'The LORD shall judge the people: judge me, O LORD, according to my righteousness, and according to mine integrity that is in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 9, E'Oh let the wickedness of the wicked come to an end; but establish the just: for the righteous God trieth the hearts and reins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 10, E'My defence is of God, which saveth the upright in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 11, E'God judgeth the righteous, and God is angry with the wicked every day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 12, E'If he turn not, he will whet his sword; he hath bent his bow, and made it ready.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 13, E'He hath also prepared for him the instruments of death; he ordaineth his arrows against the persecutors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 14, E'Behold, he travaileth with iniquity, and hath conceived mischief, and brought forth falsehood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 15, E'He made a pit, and digged it, and is fallen into the ditch which he made.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 16, E'His mischief shall return upon his own head, and his violent dealing shall come down upon his own pate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 7, 17, E'I will praise the LORD according to his righteousness: and will sing praise to the name of the LORD most high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 1, E'O LORD, our Lord, how excellent is thy name in all the earth! who hast set thy glory above the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 2, E'Out of the mouth of babes and sucklings hast thou ordained strength because of thine enemies, that thou mightest still the enemy and the avenger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 3, E'When I consider thy heavens, the work of thy fingers, the moon and the stars, which thou hast ordained;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 4, E'What is man, that thou art mindful of him? and the son of man, that thou visitest him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 5, E'For thou hast made him a little lower than the angels, and hast crowned him with glory and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 6, E'Thou madest him to have dominion over the works of thy hands; thou hast put all things under his feet:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 7, E'All sheep and oxen, yea, and the beasts of the field;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 8, E'The fowl of the air, and the fish of the sea, and whatsoever passeth through the paths of the seas.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 8, 9, E'O LORD our Lord, how excellent is thy name in all the earth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 1, E'I will praise thee, O LORD, with my whole heart; I will shew forth all thy marvellous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 2, E'I will be glad and rejoice in thee: I will sing praise to thy name, O thou most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 3, E'When mine enemies are turned back, they shall fall and perish at thy presence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 4, E'For thou hast maintained my right and my cause; thou satest in the throne judging right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 5, E'Thou hast rebuked the heathen, thou hast destroyed the wicked, thou hast put out their name for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 6, E'O thou enemy, destructions are come to a perpetual end: and thou hast destroyed cities; their memorial is perished with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 7, E'But the LORD shall endure for ever: he hath prepared his throne for judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 8, E'And he shall judge the world in righteousness, he shall minister judgment to the people in uprightness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 9, E'The LORD also will be a refuge for the oppressed, a refuge in times of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 10, E'And they that know thy name will put their trust in thee: for thou, LORD, hast not forsaken them that seek thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 11, E'Sing praises to the LORD, which dwelleth in Zion: declare among the people his doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 12, E'When he maketh inquisition for blood, he remembereth them: he forgetteth not the cry of the humble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 13, E'Have mercy upon me, O LORD; consider my trouble which I suffer of them that hate me, thou that liftest me up from the gates of death:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 14, E'That I may shew forth all thy praise in the gates of the daughter of Zion: I will rejoice in thy salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 15, E'The heathen are sunk down in the pit that they made: in the net which they hid is their own foot taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 16, E'The LORD is known by the judgment which he executeth: the wicked is snared in the work of his own hands. Higgaion. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 17, E'The wicked shall be turned into hell, and all the nations that forget God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 18, E'For the needy shall not alway be forgotten: the expectation of the poor shall not perish for ever.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 19, E'Arise, O LORD; let not man prevail: let the heathen be judged in thy sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 9, 20, E'Put them in fear, O LORD: that the nations may know themselves to be but men. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 1, E'Why standest thou afar off, O LORD? why hidest thou thyself in times of trouble?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 2, E'The wicked in his pride doth persecute the poor: let them be taken in the devices that they have imagined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 3, E'For the wicked boasteth of his heartâ€™s desire, and blesseth the covetous, whom the LORD abhorreth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 4, E'The wicked, through the pride of his countenance, will not seek after God: God is not in all his thoughts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 5, E'His ways are always grievous; thy judgments are far above out of his sight: as for all his enemies, he puffeth at them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 6, E'He hath said in his heart, I shall not be moved: for I shall never be in adversity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 7, E'His mouth is full of cursing and deceit and fraud: under his tongue is mischief and vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 8, E'He sitteth in the lurking places of the villages: in the secret places doth he murder the innocent: his eyes are privily set against the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 9, E'He lieth in wait secretly as a lion in his den: he lieth in wait to catch the poor: he doth catch the poor, when he draweth him into his net.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 10, E'He croucheth, and humbleth himself, that the poor may fall by his strong ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 11, E'He hath said in his heart, God hath forgotten: he hideth his face; he will never see it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 12, E'Arise, O LORD; O God, lift up thine hand: forget not the humble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 13, E'Wherefore doth the wicked contemn God? he hath said in his heart, Thou wilt not require it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 14, E'Thou hast seen it; for thou beholdest mischief and spite, to requite it with thy hand: the poor committeth himself unto thee; thou art the helper of the fatherless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 15, E'Break thou the arm of the wicked and the evil man: seek out his wickedness till thou find none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 16, E'The LORD is King for ever and ever: the heathen are perished out of his land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 17, E'LORD, thou hast heard the desire of the humble: thou wilt prepare their heart, thou wilt cause thine ear to hear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 10, 18, E'To judge the fatherless and the oppressed, that the man of the earth may no more oppress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 1, E'In the LORD put I my trust: how say ye to my soul, Flee as a bird to your mountain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 2, E'For, lo, the wicked bend their bow, they make ready their arrow upon the string, that they may privily shoot at the upright in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 3, E'If the foundations be destroyed, what can the righteous do?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 4, E'The LORD is in his holy temple, the LORDâ€™s throne is in heaven: his eyes behold, his eyelids try, the children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 5, E'The LORD trieth the righteous: but the wicked and him that loveth violence his soul hateth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 6, E'Upon the wicked he shall rain snares, fire and brimstone, and an horrible tempest: this shall be the portion of their cup.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 11, 7, E'For the righteous LORD loveth righteousness; his countenance doth behold the upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 1, E'Help, LORD; for the godly man ceaseth; for the faithful fail from among the children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 2, E'They speak vanity every one with his neighbour: with flattering lips and with a double heart do they speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 3, E'The LORD shall cut off all flattering lips, and the tongue that speaketh proud things:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 4, E'Who have said, With our tongue will we prevail; our lips are our own: who is lord over us?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 5, E'For the oppression of the poor, for the sighing of the needy, now will I arise, saith the LORD; I will set him in safety from him that puffeth at him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 6, E'The words of the LORD are pure words: as silver tried in a furnace of earth, purified seven times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 7, E'Thou shalt keep them, O LORD, thou shalt preserve them from this generation for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 12, 8, E'The wicked walk on every side, when the vilest men are exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 1, E'How long wilt thou forget me, O LORD? for ever? how long wilt thou hide thy face from me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 2, E'How long shall I take counsel in my soul, having sorrow in my heart daily? how long shall mine enemy be exalted over me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 3, E'Consider and hear me, O LORD my God: lighten mine eyes, lest I sleep the sleep of death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 4, E'Lest mine enemy say, I have prevailed against him; and those that trouble me rejoice when I am moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 5, E'But I have trusted in thy mercy; my heart shall rejoice in thy salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 13, 6, E'I will sing unto the LORD, because he hath dealt bountifully with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 1, E'The fool hath said in his heart, There is no God. They are corrupt, they have done abominable works, there is none that doeth good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 2, E'The LORD looked down from heaven upon the children of men, to see if there were any that did understand, and seek God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 3, E'They are all gone aside, they are all together become filthy: there is none that doeth good, no, not one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 4, E'Have all the workers of iniquity no knowledge? who eat up my people as they eat bread, and call not upon the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 5, E'There were they in great fear: for God is in the generation of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 6, E'Ye have shamed the counsel of the poor, because the LORD is his refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 14, 7, E'Oh that the salvation of Israel were come out of Zion! when the LORD bringeth back the captivity of his people, Jacob shall rejoice, and Israel shall be glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 15, 1, E'Lord, who shall abide in thy tabernacle? who shall dwell in thy holy hill?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 15, 2, E'He that walketh uprightly, and worketh righteousness, and speaketh the truth in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 15, 3, E'He that backbiteth not with his tongue, nor doeth evil to his neighbour, nor taketh up a reproach against his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 15, 4, E'In whose eyes a vile person is contemned; but he honoureth them that fear the LORD. He that sweareth to his own hurt, and changeth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 15, 5, E'He that putteth not out his money to usury, nor taketh reward against the innocent. He that doeth these things shall never be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 1, E'Preserve me, O God: for in thee do I put my trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 2, E'O my soul, thou hast said unto the LORD, Thou art my Lord: my goodness extendeth not to thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 3, E'But to the saints that are in the earth, and to the excellent, in whom is all my delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 4, E'Their sorrows shall be multiplied that hasten after another god: their drink offerings of blood will I not offer, nor take up their names into my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 5, E'The LORD is the portion of mine inheritance and of my cup: thou maintainest my lot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 6, E'The lines are fallen unto me in pleasant places; yea, I have a goodly heritage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 7, E'I will bless the LORD, who hath given me counsel: my reins also instruct me in the night seasons.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 8, E'I have set the LORD always before me: because he is at my right hand, I shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 9, E'Therefore my heart is glad, and my glory rejoiceth: my flesh also shall rest in hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 10, E'For thou wilt not leave my soul in hell; neither wilt thou suffer thine Holy One to see corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 16, 11, E'Thou wilt shew me the path of life: in thy presence is fulness of joy; at thy right hand there are pleasures for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 1, E'Hear the right, O LORD, attend unto my cry, give ear unto my prayer, that goeth not out of feigned lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 2, E'Let my sentence come forth from thy presence; let thine eyes behold the things that are equal.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 3, E'Thou hast proved mine heart; thou hast visited me in the night; thou hast tried me, and shalt find nothing; I am purposed that my mouth shall not transgress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 4, E'Concerning the works of men, by the word of thy lips I have kept me from the paths of the destroyer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 5, E'Hold up my goings in thy paths, that my footsteps slip not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 6, E'I have called upon thee, for thou wilt hear me, O God: incline thine ear unto me, and hear my speech.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 7, E'Shew thy marvellous lovingkindness, O thou that savest by thy right hand them which put their trust in thee from those that rise up against them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 8, E'Keep me as the apple of the eye, hide me under the shadow of thy wings,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 9, E'From the wicked that oppress me, from my deadly enemies, who compass me about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 10, E'They are inclosed in their own fat: with their mouth they speak proudly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 11, E'They have now compassed us in our steps: they have set their eyes bowing down to the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 12, E'Like as a lion that is greedy of his prey, and as it were a young lion lurking in secret places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 13, E'Arise, O LORD, disappoint him, cast him down: deliver my soul from the wicked, which is thy sword:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 14, E'From men which are thy hand, O LORD, from men of the world, which have their portion in this life, and whose belly thou fillest with thy hid treasure: they are full of children, and leave the rest of their substance to their babes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 17, 15, E'As for me, I will behold thy face in righteousness: I shall be satisfied, when I awake, with thy likeness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 1, E'I will love thee, O LORD, my strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 2, E'The LORD is my rock, and my fortress, and my deliverer; my God, my strength, in whom I will trust; my buckler, and the horn of my salvation, and my high tower.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 3, E'I will call upon the LORD, who is worthy to be praised: so shall I be saved from mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 4, E'The sorrows of death compassed me, and the floods of ungodly men made me afraid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 5, E'The sorrows of hell compassed me about: the snares of death prevented me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 6, E'In my distress I called upon the LORD, and cried unto my God: he heard my voice out of his temple, and my cry came before him, even into his ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 7, E'Then the earth shook and trembled; the foundations also of the hills moved and were shaken, because he was wroth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 8, E'There went up a smoke out of his nostrils, and fire out of his mouth devoured: coals were kindled by it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 9, E'He bowed the heavens also, and came down: and darkness was under his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 10, E'And he rode upon a cherub, and did fly: yea, he did fly upon the wings of the wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 11, E'He made darkness his secret place; his pavilion round about him were dark waters and thick clouds of the skies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 12, E'At the brightness that was before him his thick clouds passed, hail stones and coals of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 13, E'The LORD also thundered in the heavens, and the Highest gave his voice; hail stones and coals of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 14, E'Yea, he sent out his arrows, and scattered them; and he shot out lightnings, and discomfited them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 15, E'Then the channels of waters were seen, and the foundations of the world were discovered at thy rebuke, O LORD, at the blast of the breath of thy nostrils.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 16, E'He sent from above, he took me, he drew me out of many waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 17, E'He delivered me from my strong enemy, and from them which hated me: for they were too strong for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 18, E'They prevented me in the day of my calamity: but the LORD was my stay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 19, E'He brought me forth also into a large place; he delivered me, because he delighted in me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 20, E'The LORD rewarded me according to my righteousness; according to the cleanness of my hands hath he recompensed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 21, E'For I have kept the ways of the LORD, and have not wickedly departed from my God.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 22, E'For all his judgments were before me, and I did not put away his statutes from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 23, E'I was also upright before him, and I kept myself from mine iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 24, E'Therefore hath the LORD recompensed me according to my righteousness, according to the cleanness of my hands in his eyesight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 25, E'With the merciful thou wilt shew thyself merciful; with an upright man thou wilt shew thyself upright;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 26, E'With the pure thou wilt shew thyself pure; and with the froward thou wilt shew thyself froward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 27, E'For thou wilt save the afflicted people; but wilt bring down high looks.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 28, E'For thou wilt light my candle: the LORD my God will enlighten my darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 29, E'For by thee I have run through a troop; and by my God have I leaped over a wall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 30, E'As for God, his way is perfect: the word of the LORD is tried: he is a buckler to all those that trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 31, E'For who is God save the LORD? or who is a rock save our God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 32, E'It is God that girdeth me with strength, and maketh my way perfect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 33, E'He maketh my feet like hindsâ€™ feet, and setteth me upon my high places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 34, E'He teacheth my hands to war, so that a bow of steel is broken by mine arms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 35, E'Thou hast also given me the shield of thy salvation: and thy right hand hath holden me up, and thy gentleness hath made me great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 36, E'Thou hast enlarged my steps under me, that my feet did not slip.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 37, E'I have pursued mine enemies, and overtaken them: neither did I turn again till they were consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 38, E'I have wounded them that they were not able to rise: they are fallen under my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 39, E'For thou hast girded me with strength unto the battle: thou hast subdued under me those that rose up against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 40, E'Thou hast also given me the necks of mine enemies; that I might destroy them that hate me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 41, E'They cried, but there was none to save them: even unto the LORD, but he answered them not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 42, E'Then did I beat them small as the dust before the wind: I did cast them out as the dirt in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 43, E'Thou hast delivered me from the strivings of the people; and thou hast made me the head of the heathen: a people whom I have not known shall serve me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 44, E'As soon as they hear of me, they shall obey me: the strangers shall submit themselves unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 45, E'The strangers shall fade away, and be afraid out of their close places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 46, E'The LORD liveth; and blessed be my rock; and let the God of my salvation be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 47, E'It is God that avengeth me, and subdueth the people under me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 48, E'He delivereth me from mine enemies: yea, thou liftest me up above those that rise up against me: thou hast delivered me from the violent man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 49, E'Therefore will I give thanks unto thee, O LORD, among the heathen, and sing praises unto thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 18, 50, E'Great deliverance giveth he to his king; and sheweth mercy to his anointed, to David, and to his seed for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 1, E'The heavens declare the glory of God; and the firmament sheweth his handywork.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 2, E'Day unto day uttereth speech, and night unto night sheweth knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 3, E'There is no speech nor language, where their voice is not heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 4, E'Their line is gone out through all the earth, and their words to the end of the world. In them hath he set a tabernacle for the sun,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 5, E'Which is as a bridegroom coming out of his chamber, and rejoiceth as a strong man to run a race.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 6, E'His going forth is from the end of the heaven, and his circuit unto the ends of it: and there is nothing hid from the heat thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 7, E'The law of the LORD is perfect, converting the soul: the testimony of the LORD is sure, making wise the simple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 8, E'The statutes of the LORD are right, rejoicing the heart: the commandment of the LORD is pure, enlightening the eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 9, E'The fear of the LORD is clean, enduring for ever: the judgments of the LORD are true and righteous altogether.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 10, E'More to be desired are they than gold, yea, than much fine gold: sweeter also than honey and the honeycomb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 11, E'Moreover by them is thy servant warned: and in keeping of them there is great reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 12, E'Who can understand his errors? cleanse thou me from secret faults.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 13, E'Keep back thy servant also from presumptuous sins; let them not have dominion over me: then shall I be upright, and I shall be innocent from the great transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 19, 14, E'Let the words of my mouth, and the meditation of my heart, be acceptable in thy sight, O LORD, my strength, and my redeemer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 1, E'The LORD hear thee in the day of trouble; the name of the God of Jacob defend thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 2, E'Send thee help from the sanctuary, and strengthen thee out of Zion;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 3, E'Remember all thy offerings, and accept thy burnt sacrifice; Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 4, E'Grant thee according to thine own heart, and fulfil all thy counsel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 5, E'We will rejoice in thy salvation, and in the name of our God we will set up our banners: the LORD fulfil all thy petitions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 6, E'Now know I that the LORD saveth his anointed; he will hear him from his holy heaven with the saving strength of his right hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 7, E'Some trust in chariots, and some in horses: but we will remember the name of the LORD our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 8, E'They are brought down and fallen: but we are risen, and stand upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 20, 9, E'Save, LORD: let the king hear us when we call.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 1, E'The king shall joy in thy strength, O LORD; and in thy salvation how greatly shall he rejoice!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 2, E'Thou hast given him his heartâ€™s desire, and hast not withholden the request of his lips. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 3, E'For thou preventest him with the blessings of goodness: thou settest a crown of pure gold on his head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 4, E'He asked life of thee, and thou gavest it him, even length of days for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 5, E'His glory is great in thy salvation: honour and majesty hast thou laid upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 6, E'For thou hast made him most blessed for ever: thou hast made him exceeding glad with thy countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 7, E'For the king trusteth in the LORD, and through the mercy of the most High he shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 8, E'Thine hand shall find out all thine enemies: thy right hand shall find out those that hate thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 9, E'Thou shalt make them as a fiery oven in the time of thine anger: the LORD shall swallow them up in his wrath, and the fire shall devour them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 10, E'Their fruit shalt thou destroy from the earth, and their seed from among the children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 11, E'For they intended evil against thee: they imagined a mischievous device, which they are not able to perform.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 12, E'Therefore shalt thou make them turn their back, when thou shalt make ready thine arrows upon thy strings against the face of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 21, 13, E'Be thou exalted, LORD, in thine own strength: so will we sing and praise thy power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 1, E'My God, my God, why hast thou forsaken me? why art thou so far from helping me, and from the words of my roaring?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 2, E'O my God, I cry in the day time, but thou hearest not; and in the night season, and am not silent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 3, E'But thou art holy, O thou that inhabitest the praises of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 4, E'Our fathers trusted in thee: they trusted, and thou didst deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 5, E'They cried unto thee, and were delivered: they trusted in thee, and were not confounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 6, E'But I am a worm, and no man; a reproach of men, and despised of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 7, E'All they that see me laugh me to scorn: they shoot out the lip, they shake the head, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 8, E'He trusted on the LORD that he would deliver him: let him deliver him, seeing he delighted in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 9, E'But thou art he that took me out of the womb: thou didst make me hope when I was upon my motherâ€™s breasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 10, E'I was cast upon thee from the womb: thou art my God from my motherâ€™s belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 11, E'Be not far from me; for trouble is near; for there is none to help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 12, E'Many bulls have compassed me: strong bulls of Bashan have beset me round.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 13, E'They gaped upon me with their mouths, as a ravening and a roaring lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 14, E'I am poured out like water, and all my bones are out of joint: my heart is like wax; it is melted in the midst of my bowels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 15, E'My strength is dried up like a potsherd; and my tongue cleaveth to my jaws; and thou hast brought me into the dust of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 16, E'For dogs have compassed me: the assembly of the wicked have inclosed me: they pierced my hands and my feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 17, E'I may tell all my bones: they look and stare upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 18, E'They part my garments among them, and cast lots upon my vesture.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 19, E'But be not thou far from me, O LORD: O my strength, haste thee to help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 20, E'Deliver my soul from the sword; my darling from the power of the dog.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 21, E'Save me from the lionâ€™s mouth: for thou hast heard me from the horns of the unicorns.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 22, E'I will declare thy name unto my brethren: in the midst of the congregation will I praise thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 23, E'Ye that fear the LORD, praise him; all ye the seed of Jacob, glorify him; and fear him, all ye the seed of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 24, E'For he hath not despised nor abhorred the affliction of the afflicted; neither hath he hid his face from him; but when he cried unto him, he heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 25, E'My praise shall be of thee in the great congregation: I will pay my vows before them that fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 26, E'The meek shall eat and be satisfied: they shall praise the LORD that seek him: your heart shall live for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 27, E'All the ends of the world shall remember and turn unto the LORD: and all the kindreds of the nations shall worship before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 28, E'For the kingdom is the LORDâ€™s: and he is the governor among the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 29, E'All they that be fat upon earth shall eat and worship: all they that go down to the dust shall bow before him: and none can keep alive his own soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 30, E'A seed shall serve him; it shall be accounted to the Lord for a generation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 22, 31, E'They shall come, and shall declare his righteousness unto a people that shall be born, that he hath done this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 1, E'The LORD is my shepherd; I shall not want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 2, E'He maketh me to lie down in green pastures: he leadeth me beside the still waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 3, E'He restoreth my soul: he leadeth me in the paths of righteousness for his nameâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 4, E'Yea, though I walk through the valley of the shadow of death, I will fear no evil: for thou art with me; thy rod and thy staff they comfort me.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 5, E'Thou preparest a table before me in the presence of mine enemies: thou anointest my head with oil; my cup runneth over.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 23, 6, E'Surely goodness and mercy shall follow me all the days of my life: and I will dwell in the house of the LORD for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 1, E'The earth is the LORDâ€™s, and the fulness thereof; the world, and they that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 2, E'For he hath founded it upon the seas, and established it upon the floods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 3, E'Who shall ascend into the hill of the LORD? or who shall stand in his holy place?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 4, E'He that hath clean hands, and a pure heart; who hath not lifted up his soul unto vanity, nor sworn deceitfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 5, E'He shall receive the blessing from the LORD, and righteousness from the God of his salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 6, E'This is the generation of them that seek him, that seek thy face, O Jacob. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 7, E'Lift up your heads, O ye gates; and be ye lift up, ye everlasting doors; and the King of glory shall come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 8, E'Who is this King of glory? The LORD strong and mighty, the LORD mighty in battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 9, E'Lift up your heads, O ye gates; even lift them up, ye everlasting doors; and the King of glory shall come in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 24, 10, E'Who is this King of glory? The LORD of hosts, he is the King of glory. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 1, E'Unto thee, O LORD, do I lift up my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 2, E'O my God, I trust in thee: let me not be ashamed, let not mine enemies triumph over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 3, E'Yea, let none that wait on thee be ashamed: let them be ashamed which transgress without cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 4, E'Shew me thy ways, O LORD; teach me thy paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 5, E'Lead me in thy truth, and teach me: for thou art the God of my salvation; on thee do I wait all the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 6, E'Remember, O LORD, thy tender mercies and thy lovingkindnesses; for they have been ever of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 7, E'Remember not the sins of my youth, nor my transgressions: according to thy mercy remember thou me for thy goodnessâ€™ sake, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 8, E'Good and upright is the LORD: therefore will he teach sinners in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 9, E'The meek will he guide in judgment: and the meek will he teach his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 10, E'All the paths of the LORD are mercy and truth unto such as keep his covenant and his testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 11, E'For thy nameâ€™s sake, O LORD, pardon mine iniquity; for it is great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 12, E'What man is he that feareth the LORD? him shall he teach in the way that he shall choose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 13, E'His soul shall dwell at ease; and his seed shall inherit the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 14, E'The secret of the LORD is with them that fear him; and he will shew them his covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 15, E'Mine eyes are ever toward the LORD; for he shall pluck my feet out of the net.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 16, E'Turn thee unto me, and have mercy upon me; for I am desolate and afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 17, E'The troubles of my heart are enlarged: O bring thou me out of my distresses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 18, E'Look upon mine affliction and my pain; and forgive all my sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 19, E'Consider mine enemies; for they are many; and they hate me with cruel hatred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 20, E'O keep my soul, and deliver me: let me not be ashamed; for I put my trust in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 21, E'Let integrity and uprightness preserve me; for I wait on thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 25, 22, E'Redeem Israel, O God, out of all his troubles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 1, E'Judge me, O LORD; for I have walked in mine integrity: I have trusted also in the LORD; therefore I shall not slide.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 2, E'Examine me, O LORD, and prove me; try my reins and my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 3, E'For thy lovingkindness is before mine eyes: and I have walked in thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 4, E'I have not sat with vain persons, neither will I go in with dissemblers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 5, E'I have hated the congregation of evil doers; and will not sit with the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 6, E'I will wash mine hands in innocency: so will I compass thine altar, O LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 7, E'That I may publish with the voice of thanksgiving, and tell of all thy wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 8, E'LORD, I have loved the habitation of thy house, and the place where thine honour dwelleth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 9, E'Gather not my soul with sinners, nor my life with bloody men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 10, E'In whose hands is mischief, and their right hand is full of bribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 11, E'But as for me, I will walk in mine integrity: redeem me, and be merciful unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 26, 12, E'My foot standeth in an even place: in the congregations will I bless the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 1, E'The LORD is my light and my salvation; whom shall I fear? the LORD is the strength of my life; of whom shall I be afraid?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 2, E'When the wicked, even mine enemies and my foes, came upon me to eat up my flesh, they stumbled and fell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 3, E'Though an host should encamp against me, my heart shall not fear: though war should rise against me, in this will I be confident.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 4, E'One thing have I desired of the LORD, that will I seek after; that I may dwell in the house of the LORD all the days of my life, to behold the beauty of the LORD, and to enquire in his temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 5, E'For in the time of trouble he shall hide me in his pavilion: in the secret of his tabernacle shall he hide me; he shall set me up upon a rock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 6, E'And now shall mine head be lifted up above mine enemies round about me: therefore will I offer in his tabernacle sacrifices of joy; I will sing, yea, I will sing praises unto the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 7, E'Hear, O LORD, when I cry with my voice: have mercy also upon me, and answer me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 8, E'When thou saidst, Seek ye my face; my heart said unto thee, Thy face, LORD, will I seek.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 9, E'Hide not thy face far from me; put not thy servant away in anger: thou hast been my help; leave me not, neither forsake me, O God of my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 10, E'When my father and my mother forsake me, then the LORD will take me up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 11, E'Teach me thy way, O LORD, and lead me in a plain path, because of mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 12, E'Deliver me not over unto the will of mine enemies: for false witnesses are risen up against me, and such as breathe out cruelty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 13, E'I had fainted, unless I had believed to see the goodness of the LORD in the land of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 27, 14, E'Wait on the LORD: be of good courage, and he shall strengthen thine heart: wait, I say, on the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 1, E'Unto thee will I cry, O LORD my rock; be not silent to me: lest, if thou be silent to me, I become like them that go down into the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 2, E'Hear the voice of my supplications, when I cry unto thee, when I lift up my hands toward thy holy oracle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 3, E'Draw me not away with the wicked, and with the workers of iniquity, which speak peace to their neighbours, but mischief is in their hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 4, E'Give them according to their deeds, and according to the wickedness of their endeavours: give them after the work of their hands; render to them their desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 5, E'Because they regard not the works of the LORD, nor the operation of his hands, he shall destroy them, and not build them up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 6, E'Blessed be the LORD, because he hath heard the voice of my supplications.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 7, E'The LORD is my strength and my shield; my heart trusted in him, and I am helped: therefore my heart greatly rejoiceth; and with my song will I praise him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 8, E'The LORD is their strength, and he is the saving strength of his anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 28, 9, E'Save thy people, and bless thine inheritance: feed them also, and lift them up for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 1, E'Give unto the LORD, O ye mighty, give unto the LORD glory and strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 2, E'Give unto the LORD the glory due unto his name; worship the LORD in the beauty of holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 3, E'The voice of the LORD is upon the waters: the God of glory thundereth: the LORD is upon many waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 4, E'The voice of the LORD is powerful; the voice of the LORD is full of majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 5, E'The voice of the LORD breaketh the cedars; yea, the LORD breaketh the cedars of Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 6, E'He maketh them also to skip like a calf; Lebanon and Sirion like a young unicorn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 7, E'The voice of the LORD divideth the flames of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 8, E'The voice of the LORD shaketh the wilderness; the LORD shaketh the wilderness of Kadesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 9, E'The voice of the LORD maketh the hinds to calve, and discovereth the forests: and in his temple doth every one speak of his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 10, E'The LORD sitteth upon the flood; yea, the LORD sitteth King for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 29, 11, E'The LORD will give strength unto his people; the LORD will bless his people with peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 1, E'I will extol thee, O LORD; for thou hast lifted me up, and hast not made my foes to rejoice over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 2, E'O LORD my God, I cried unto thee, and thou hast healed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 3, E'O LORD, thou hast brought up my soul from the grave: thou hast kept me alive, that I should not go down to the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 4, E'Sing unto the LORD, O ye saints of his, and give thanks at the remembrance of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 5, E'For his anger endureth but a moment; in his favour is life: weeping may endure for a night, but joy cometh in the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 6, E'And in my prosperity I said, I shall never be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 7, E'LORD, by thy favour thou hast made my mountain to stand strong: thou didst hide thy face, and I was troubled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 8, E'I cried to thee, O LORD; and unto the LORD I made supplication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 9, E'What profit is there in my blood, when I go down to the pit? Shall the dust praise thee? shall it declare thy truth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 10, E'Hear, O LORD, and have mercy upon me: LORD, be thou my helper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 11, E'Thou hast turned for me my mourning into dancing: thou hast put off my sackcloth, and girded me with gladness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 30, 12, E'To the end that my glory may sing praise to thee, and not be silent. O LORD my God, I will give thanks unto thee for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 1, E'In thee, O LORD, do I put my trust; let me never be ashamed: deliver me in thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 2, E'Bow down thine ear to me; deliver me speedily: be thou my strong rock, for an house of defence to save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 3, E'For thou art my rock and my fortress; therefore for thy nameâ€™s sake lead me, and guide me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 4, E'Pull me out of the net that they have laid privily for me: for thou art my strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 5, E'Into thine hand I commit my spirit: thou hast redeemed me, O LORD God of truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 6, E'I have hated them that regard lying vanities: but I trust in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 7, E'I will be glad and rejoice in thy mercy: for thou hast considered my trouble; thou hast known my soul in adversities;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 8, E'And hast not shut me up into the hand of the enemy: thou hast set my feet in a large room.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 9, E'Have mercy upon me, O LORD, for I am in trouble: mine eye is consumed with grief, yea, my soul and my belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 10, E'For my life is spent with grief, and my years with sighing: my strength faileth because of mine iniquity, and my bones are consumed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 11, E'I was a reproach among all mine enemies, but especially among my neighbours, and a fear to mine acquaintance: they that did see me without fled from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 12, E'I am forgotten as a dead man out of mind: I am like a broken vessel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 13, E'For I have heard the slander of many: fear was on every side: while they took counsel together against me, they devised to take away my life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 14, E'But I trusted in thee, O LORD: I said, Thou art my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 15, E'My times are in thy hand: deliver me from the hand of mine enemies, and from them that persecute me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 16, E'Make thy face to shine upon thy servant: save me for thy merciesâ€™ sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 17, E'Let me not be ashamed, O LORD; for I have called upon thee: let the wicked be ashamed, and let them be silent in the grave.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 18, E'Let the lying lips be put to silence; which speak grievous things proudly and contemptuously against the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 19, E'Oh how great is thy goodness, which thou hast laid up for them that fear thee; which thou hast wrought for them that trust in thee before the sons of men!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 20, E'Thou shalt hide them in the secret of thy presence from the pride of man: thou shalt keep them secretly in a pavilion from the strife of tongues.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 21, E'Blessed be the LORD: for he hath shewed me his marvellous kindness in a strong city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 22, E'For I said in my haste, I am cut off from before thine eyes: nevertheless thou heardest the voice of my supplications when I cried unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 23, E'O love the LORD, all ye his saints: for the LORD preserveth the faithful, and plentifully rewardeth the proud doer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 31, 24, E'Be of good courage, and he shall strengthen your heart, all ye that hope in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 1, E'Blessed is he whose transgression is forgiven, whose sin is covered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 2, E'Blessed is the man unto whom the LORD imputeth not iniquity, and in whose spirit there is no guile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 3, E'When I kept silence, my bones waxed old through my roaring all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 4, E'For day and night thy hand was heavy upon me: my moisture is turned into the drought of summer. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 5, E'I acknowledged my sin unto thee, and mine iniquity have I not hid. I said, I will confess my transgressions unto the LORD; and thou forgavest the iniquity of my sin. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 6, E'For this shall every one that is godly pray unto thee in a time when thou mayest be found: surely in the floods of great waters they shall not come nigh unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 7, E'Thou art my hiding place; thou shalt preserve me from trouble; thou shalt compass me about with songs of deliverance. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 8, E'I will instruct thee and teach thee in the way which thou shalt go: I will guide thee with mine eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 9, E'Be ye not as the horse, or as the mule, which have no understanding: whose mouth must be held in with bit and bridle, lest they come near unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 10, E'Many sorrows shall be to the wicked: but he that trusteth in the LORD, mercy shall compass him about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 32, 11, E'Be glad in the LORD, and rejoice, ye righteous: and shout for joy, all ye that are upright in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 1, E'Rejoice in the LORD, O ye righteous: for praise is comely for the upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 2, E'Praise the LORD with harp: sing unto him with the psaltery and an instrument of ten strings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 3, E'Sing unto him a new song; play skilfully with a loud noise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 4, E'For the word of the LORD is right; and all his works are done in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 5, E'He loveth righteousness and judgment: the earth is full of the goodness of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 6, E'By the word of the LORD were the heavens made; and all the host of them by the breath of his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 7, E'He gathereth the waters of the sea together as an heap: he layeth up the depth in storehouses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 8, E'Let all the earth fear the LORD: let all the inhabitants of the world stand in awe of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 9, E'For he spake, and it was done; he commanded, and it stood fast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 10, E'The LORD bringeth the counsel of the heathen to nought: he maketh the devices of the people of none effect.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 11, E'The counsel of the LORD standeth for ever, the thoughts of his heart to all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 12, E'Blessed is the nation whose God is the LORD; and the people whom he hath chosen for his own inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 13, E'The LORD looketh from heaven; he beholdeth all the sons of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 14, E'From the place of his habitation he looketh upon all the inhabitants of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 15, E'He fashioneth their hearts alike; he considereth all their works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 16, E'There is no king saved by the multitude of an host: a mighty man is not delivered by much strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 17, E'An horse is a vain thing for safety: neither shall he deliver any by his great strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 18, E'Behold, the eye of the LORD is upon them that fear him, upon them that hope in his mercy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 19, E'To deliver their soul from death, and to keep them alive in famine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 20, E'Our soul waiteth for the LORD: he is our help and our shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 21, E'For our heart shall rejoice in him, because we have trusted in his holy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 33, 22, E'Let thy mercy, O LORD, be upon us, according as we hope in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 1, E'I will bless the LORD at all times: his praise shall continually be in my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 2, E'My soul shall make her boast in the LORD: the humble shall hear thereof, and be glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 3, E'O magnify the LORD with me, and let us exalt his name together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 4, E'I sought the LORD, and he heard me, and delivered me from all my fears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 5, E'They looked unto him, and were lightened: and their faces were not ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 6, E'This poor man cried, and the LORD heard him, and saved him out of all his troubles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 7, E'The angel of the LORD encampeth round about them that fear him, and delivereth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 8, E'O taste and see that the LORD is good: blessed is the man that trusteth in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 9, E'O fear the LORD, ye his saints: for there is no want to them that fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 10, E'The young lions do lack, and suffer hunger: but they that seek the LORD shall not want any good thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 11, E'Come, ye children, hearken unto me: I will teach you the fear of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 12, E'What man is he that desireth life, and loveth many days, that he may see good?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 13, E'Keep thy tongue from evil, and thy lips from speaking guile.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 14, E'Depart from evil, and do good; seek peace, and pursue it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 15, E'The eyes of the LORD are upon the righteous, and his ears are open unto their cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 16, E'The face of the LORD is against them that do evil, to cut off the remembrance of them from the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 17, E'The righteous cry, and the LORD heareth, and delivereth them out of all their troubles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 18, E'The LORD is nigh unto them that are of a broken heart; and saveth such as be of a contrite spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 19, E'Many are the afflictions of the righteous: but the LORD delivereth him out of them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 20, E'He keepeth all his bones: not one of them is broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 21, E'Evil shall slay the wicked: and they that hate the righteous shall be desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 34, 22, E'The LORD redeemeth the soul of his servants: and none of them that trust in him shall be desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 1, E'Plead my cause, O LORD, with them that strive with me: fight against them that fight against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 2, E'Take hold of shield and buckler, and stand up for mine help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 3, E'Draw out also the spear, and stop the way against them that persecute me: say unto my soul, I am thy salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 4, E'Let them be confounded and put to shame that seek after my soul: let them be turned back and brought to confusion that devise my hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 5, E'Let them be as chaff before the wind: and let the angel of the LORD chase them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 6, E'Let their way be dark and slippery: and let the angel of the LORD persecute them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 7, E'For without cause have they hid for me their net in a pit, which without cause they have digged for my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 8, E'Let destruction come upon him at unawares; and let his net that he hath hid catch himself: into that very destruction let him fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 9, E'And my soul shall be joyful in the LORD: it shall rejoice in his salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 10, E'All my bones shall say, LORD, who is like unto thee, which deliverest the poor from him that is too strong for him, yea, the poor and the needy from him that spoileth him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 11, E'False witnesses did rise up; they laid to my charge things that I knew not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 12, E'They rewarded me evil for good to the spoiling of my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 13, E'But as for me, when they were sick, my clothing was sackcloth: I humbled my soul with fasting; and my prayer returned into mine own bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 14, E'I behaved myself as though he had been my friend or brother: I bowed down heavily, as one that mourneth for his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 15, E'But in mine adversity they rejoiced, and gathered themselves together: yea, the abjects gathered themselves together against me, and I knew it not; they did tear me, and ceased not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 16, E'With hypocritical mockers in feasts, they gnashed upon me with their teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 17, E'Lord, how long wilt thou look on? rescue my soul from their destructions, my darling from the lions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 18, E'I will give thee thanks in the great congregation: I will praise thee among much people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 19, E'Let not them that are mine enemies wrongfully rejoice over me: neither let them wink with the eye that hate me without a cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 20, E'For they speak not peace: but they devise deceitful matters against them that are quiet in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 21, E'Yea, they opened their mouth wide against me, and said, Aha, aha, our eye hath seen it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 22, E'This thou hast seen, O LORD: keep not silence: O Lord, be not far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 23, E'Stir up thyself, and awake to my judgment, even unto my cause, my God and my Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 24, E'Judge me, O LORD my God, according to thy righteousness; and let them not rejoice over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 25, E'Let them not say in their hearts, Ah, so would we have it: let them not say, We have swallowed him up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 26, E'Let them be ashamed and brought to confusion together that rejoice at mine hurt: let them be clothed with shame and dishonour that magnify themselves against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 27, E'Let them shout for joy, and be glad, that favour my righteous cause: yea, let them say continually, Let the LORD be magnified, which hath pleasure in the prosperity of his servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 35, 28, E'And my tongue shall speak of thy righteousness and of thy praise all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 1, E'The transgression of the wicked saith within my heart, that there is no fear of God before his eyes.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 2, E'For he flattereth himself in his own eyes, until his iniquity be found to be hateful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 3, E'The words of his mouth are iniquity and deceit: he hath left off to be wise, and to do good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 4, E'He deviseth mischief upon his bed; he setteth himself in a way that is not good; he abhorreth not evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 5, E'Thy mercy, O LORD, is in the heavens; and thy faithfulness reacheth unto the clouds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 6, E'Thy righteousness is like the great mountains; thy judgments are a great deep: O LORD, thou preservest man and beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 7, E'How excellent is thy lovingkindness, O God! therefore the children of men put their trust under the shadow of thy wings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 8, E'They shall be abundantly satisfied with the fatness of thy house; and thou shalt make them drink of the river of thy pleasures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 9, E'For with thee is the fountain of life: in thy light shall we see light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 10, E'O continue thy lovingkindness unto them that know thee; and thy righteousness to the upright in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 11, E'Let not the foot of pride come against me, and let not the hand of the wicked remove me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 36, 12, E'There are the workers of iniquity fallen: they are cast down, and shall not be able to rise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 1, E'Fret not thyself because of evildoers, neither be thou envious against the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 2, E'For they shall soon be cut down like the grass, and wither as the green herb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 3, E'Trust in the LORD, and do good; so shalt thou dwell in the land, and verily thou shalt be fed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 4, E'Delight thyself also in the LORD: and he shall give thee the desires of thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 5, E'Commit thy way unto the LORD; trust also in him; and he shall bring it to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 6, E'And he shall bring forth thy righteousness as the light, and thy judgment as the noonday.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 7, E'Rest in the LORD, and wait patiently for him: fret not thyself because of him who prospereth in his way, because of the man who bringeth wicked devices to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 8, E'Cease from anger, and forsake wrath: fret not thyself in any wise to do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 9, E'For evildoers shall be cut off: but those that wait upon the LORD, they shall inherit the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 10, E'For yet a little while, and the wicked shall not be: yea, thou shalt diligently consider his place, and it shall not be.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 11, E'But the meek shall inherit the earth; and shall delight themselves in the abundance of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 12, E'The wicked plotteth against the just, and gnasheth upon him with his teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 13, E'The LORD shall laugh at him: for he seeth that his day is coming.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 14, E'The wicked have drawn out the sword, and have bent their bow, to cast down the poor and needy, and to slay such as be of upright conversation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 15, E'Their sword shall enter into their own heart, and their bows shall be broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 16, E'A little that a righteous man hath is better than the riches of many wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 17, E'For the arms of the wicked shall be broken: but the LORD upholdeth the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 18, E'The LORD knoweth the days of the upright: and their inheritance shall be for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 19, E'They shall not be ashamed in the evil time: and in the days of famine they shall be satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 20, E'But the wicked shall perish, and the enemies of the LORD shall be as the fat of lambs: they shall consume; into smoke shall they consume away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 21, E'The wicked borroweth, and payeth not again: but the righteous sheweth mercy, and giveth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 22, E'For such as be blessed of him shall inherit the earth; and they that be cursed of him shall be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 23, E'The steps of a good man are ordered by the LORD: and he delighteth in his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 24, E'Though he fall, he shall not be utterly cast down: for the LORD upholdeth him with his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 25, E'I have been young, and now am old; yet have I not seen the righteous forsaken, nor his seed begging bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 26, E'He is ever merciful, and lendeth; and his seed is blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 27, E'Depart from evil, and do good; and dwell for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 28, E'For the LORD loveth judgment, and forsaketh not his saints; they are preserved for ever: but the seed of the wicked shall be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 29, E'The righteous shall inherit the land, and dwell therein for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 30, E'The mouth of the righteous speaketh wisdom, and his tongue talketh of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 31, E'The law of his God is in his heart; none of his steps shall slide.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 32, E'The wicked watcheth the righteous, and seeketh to slay him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 33, E'The LORD will not leave him in his hand, nor condemn him when he is judged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 34, E'Wait on the LORD, and keep his way, and he shall exalt thee to inherit the land: when the wicked are cut off, thou shalt see it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 35, E'I have seen the wicked in great power, and spreading himself like a green bay tree.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 36, E'Yet he passed away, and, lo, he was not: yea, I sought him, but he could not be found.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 37, E'Mark the perfect man, and behold the upright: for the end of that man is peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 38, E'But the transgressors shall be destroyed together: the end of the wicked shall be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 39, E'But the salvation of the righteous is of the LORD: he is their strength in the time of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 37, 40, E'And the LORD shall help them, and deliver them: he shall deliver them from the wicked, and save them, because they trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 1, E'O LORD, rebuke me not in thy wrath: neither chasten me in thy hot displeasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 2, E'For thine arrows stick fast in me, and thy hand presseth me sore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 3, E'There is no soundness in my flesh because of thine anger; neither is there any rest in my bones because of my sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 4, E'For mine iniquities are gone over mine head: as an heavy burden they are too heavy for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 5, E'My wounds stink and are corrupt because of my foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 6, E'I am troubled; I am bowed down greatly; I go mourning all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 7, E'For my loins are filled with a loathsome disease: and there is no soundness in my flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 8, E'I am feeble and sore broken: I have roared by reason of the disquietness of my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 9, E'Lord, all my desire is before thee; and my groaning is not hid from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 10, E'My heart panteth, my strength faileth me: as for the light of mine eyes, it also is gone from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 11, E'My lovers and my friends stand aloof from my sore; and my kinsmen stand afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 12, E'They also that seek after my life lay snares for me: and they that seek my hurt speak mischievous things, and imagine deceits all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 13, E'But I, as a deaf man, heard not; and I was as a dumb man that openeth not his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 14, E'Thus I was as a man that heareth not, and in whose mouth are no reproofs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 15, E'For in thee, O LORD, do I hope: thou wilt hear, O Lord my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 16, E'For I said, Hear me, lest otherwise they should rejoice over me: when my foot slippeth, they magnify themselves against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 17, E'For I am ready to halt, and my sorrow is continually before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 18, E'For I will declare mine iniquity; I will be sorry for my sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 19, E'But mine enemies are lively, and they are strong: and they that hate me wrongfully are multiplied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 20, E'They also that render evil for good are mine adversaries; because I follow the thing that good is.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 21, E'Forsake me not, O LORD: O my God, be not far from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 38, 22, E'Make haste to help me, O Lord my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 1, E'I said, I will take heed to my ways, that I sin not with my tongue: I will keep my mouth with a bridle, while the wicked is before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 2, E'I was dumb with silence, I held my peace, even from good; and my sorrow was stirred.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 3, E'My heart was hot within me, while I was musing the fire burned: then spake I with my tongue,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 4, E'LORD, make me to know mine end, and the measure of my days, what it is: that I may know how frail I am.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 5, E'Behold, thou hast made my days as an handbreadth; and mine age is as nothing before thee: verily every man at his best state is altogether vanity. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 6, E'Surely every man walketh in a vain shew: surely they are disquieted in vain: he heapeth up riches, and knoweth not who shall gather them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 7, E'And now, Lord, what wait I for? my hope is in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 8, E'Deliver me from all my transgressions: make me not the reproach of the foolish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 9, E'I was dumb, I opened not my mouth; because thou didst it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 10, E'Remove thy stroke away from me: I am consumed by the blow of thine hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 11, E'When thou with rebukes dost correct man for iniquity, thou makest his beauty to consume away like a moth: surely every man is vanity. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 12, E'Hear my prayer, O LORD, and give ear unto my cry; hold not thy peace at my tears: for I am a stranger with thee, and a sojourner, as all my fathers were.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 39, 13, E'O spare me, that I may recover strength, before I go hence, and be no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 1, E'I waited patiently for the LORD; and he inclined unto me, and heard my cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 2, E'He brought me up also out of an horrible pit, out of the miry clay, and set my feet upon a rock, and established my goings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 3, E'And he hath put a new song in my mouth, even praise unto our God: many shall see it, and fear, and shall trust in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 4, E'Blessed is that man that maketh the LORD his trust, and respecteth not the proud, nor such as turn aside to lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 5, E'Many, O LORD my God, are thy wonderful works which thou hast done, and thy thoughts which are to us-ward: they cannot be reckoned up in order unto thee: if I would declare and speak of them, they are more than can be numbered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 6, E'Sacrifice and offering thou didst not desire; mine ears hast thou opened: burnt offering and sin offering hast thou not required.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 7, E'Then said I, Lo, I come: in the volume of the book it is written of me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 8, E'I delight to do thy will, O my God: yea, thy law is within my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 9, E'I have preached righteousness in the great congregation: lo, I have not refrained my lips, O LORD, thou knowest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 10, E'I have not hid thy righteousness within my heart; I have declared thy faithfulness and thy salvation: I have not concealed thy lovingkindness and thy truth from the great congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 11, E'Withhold not thou thy tender mercies from me, O LORD: let thy lovingkindness and thy truth continually preserve me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 12, E'For innumerable evils have compassed me about: mine iniquities have taken hold upon me, so that I am not able to look up; they are more than the hairs of mine head: therefore my heart faileth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 13, E'Be pleased, O LORD, to deliver me: O LORD, make haste to help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 14, E'Let them be ashamed and confounded together that seek after my soul to destroy it; let them be driven backward and put to shame that wish me evil.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 15, E'Let them be desolate for a reward of their shame that say unto me, Aha, aha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 16, E'Let all those that seek thee rejoice and be glad in thee: let such as love thy salvation say continually, The LORD be magnified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 40, 17, E'But I am poor and needy; yet the Lord thinketh upon me: thou art my help and my deliverer; make no tarrying, O my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 1, E'Blessed is he that considereth the poor: the LORD will deliver him in time of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 2, E'The LORD will preserve him, and keep him alive; and he shall be blessed upon the earth: and thou wilt not deliver him unto the will of his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 3, E'The LORD will strengthen him upon the bed of languishing: thou wilt make all his bed in his sickness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 4, E'I said, LORD, be merciful unto me: heal my soul; for I have sinned against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 5, E'Mine enemies speak evil of me, When shall he die, and his name perish?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 6, E'And if he come to see me, he speaketh vanity: his heart gathereth iniquity to itself; when he goeth abroad, he telleth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 7, E'All that hate me whisper together against me: against me do they devise my hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 8, E'An evil disease, say they, cleaveth fast unto him: and now that he lieth he shall rise up no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 9, E'Yea, mine own familiar friend, in whom I trusted, which did eat of my bread, hath lifted up his heel against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 10, E'But thou, O LORD, be merciful unto me, and raise me up, that I may requite them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 11, E'By this I know that thou favourest me, because mine enemy doth not triumph over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 12, E'And as for me, thou upholdest me in mine integrity, and settest me before thy face for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 41, 13, E'Blessed be the LORD God of Israel from everlasting, and to everlasting. Amen, and Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 1, E'As the hart panteth after the water brooks, so panteth my soul after thee, O God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 2, E'My soul thirsteth for God, for the living God: when shall I come and appear before God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 3, E'My tears have been my meat day and night, while they continually say unto me, Where is thy God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 4, E'When I remember these things, I pour out my soul in me: for I had gone with the multitude, I went with them to the house of God, with the voice of joy and praise, with a multitude that kept holyday.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 5, E'Why art thou cast down, O my soul? and why art thou disquieted in me? hope thou in God: for I shall yet praise him for the help of his countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 6, E'O my God, my soul is cast down within me: therefore will I remember thee from the land of Jordan, and of the Hermonites, from the hill Mizar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 7, E'Deep calleth unto deep at the noise of thy waterspouts: all thy waves and thy billows are gone over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 8, E'Yet the LORD will command his lovingkindness in the day time, and in the night his song shall be with me, and my prayer unto the God of my life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 9, E'I will say unto God my rock, Why hast thou forgotten me? why go I mourning because of the oppression of the enemy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 10, E'As with a sword in my bones, mine enemies reproach me; while they say daily unto me, Where is thy God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 42, 11, E'Why art thou cast down, O my soul? and why art thou disquieted within me? hope thou in God: for I shall yet praise him, who is the health of my countenance, and my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 43, 1, E'Judge me, O God, and plead my cause against an ungodly nation: O deliver me from the deceitful and unjust man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 43, 2, E'For thou art the God of my strength: why dost thou cast me off? why go I mourning because of the oppression of the enemy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 43, 3, E'O send out thy light and thy truth: let them lead me; let them bring me unto thy holy hill, and to thy tabernacles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 43, 4, E'Then will I go unto the altar of God, unto God my exceeding joy: yea, upon the harp will I praise thee, O God my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 43, 5, E'Why art thou cast down, O my soul? and why art thou disquieted within me? hope in God: for I shall yet praise him, who is the health of my countenance, and my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 1, E'We have heard with our ears, O God, our fathers have told us, what work thou didst in their days, in the times of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 2, E'How thou didst drive out the heathen with thy hand, and plantedst them; how thou didst afflict the people, and cast them out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 3, E'For they got not the land in possession by their own sword, neither did their own arm save them: but thy right hand, and thine arm, and the light of thy countenance, because thou hadst a favour unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 4, E'Thou art my King, O God: command deliverances for Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 5, E'Through thee will we push down our enemies: through thy name will we tread them under that rise up against us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 6, E'For I will not trust in my bow, neither shall my sword save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 7, E'But thou hast saved us from our enemies, and hast put them to shame that hated us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 8, E'In God we boast all the day long, and praise thy name for ever. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 9, E'But thou hast cast off, and put us to shame; and goest not forth with our armies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 10, E'Thou makest us to turn back from the enemy: and they which hate us spoil for themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 11, E'Thou hast given us like sheep appointed for meat; and hast scattered us among the heathen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 12, E'Thou sellest thy people for nought, and dost not increase thy wealth by their price.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 13, E'Thou makest us a reproach to our neighbours, a scorn and a derision to them that are round about us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 14, E'Thou makest us a byword among the heathen, a shaking of the head among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 15, E'My confusion is continually before me, and the shame of my face hath covered me,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 16, E'For the voice of him that reproacheth and blasphemeth; by reason of the enemy and avenger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 17, E'All this is come upon us; yet have we not forgotten thee, neither have we dealt falsely in thy covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 18, E'Our heart is not turned back, neither have our steps declined from thy way;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 19, E'Though thou hast sore broken us in the place of dragons, and covered us with the shadow of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 20, E'If we have forgotten the name of our God, or stretched out our hands to a strange god;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 21, E'Shall not God search this out? for he knoweth the secrets of the heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 22, E'Yea, for thy sake are we killed all the day long; we are counted as sheep for the slaughter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 23, E'Awake, why sleepest thou, O Lord? arise, cast us not off for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 24, E'Wherefore hidest thou thy face, and forgettest our affliction and our oppression?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 25, E'For our soul is bowed down to the dust: our belly cleaveth unto the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 44, 26, E'Arise for our help, and redeem us for thy merciesâ€™ sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 1, E'My heart is inditing a good matter: I speak of the things which I have made touching the king: my tongue is the pen of a ready writer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 2, E'Thou art fairer than the children of men: grace is poured into thy lips: therefore God hath blessed thee for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 3, E'Gird thy sword upon thy thigh, O most mighty, with thy glory and thy majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 4, E'And in thy majesty ride prosperously because of truth and meekness and righteousness; and thy right hand shall teach thee terrible things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 5, E'Thine arrows are sharp in the heart of the kingâ€™s enemies; whereby the people fall under thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 6, E'Thy throne, O God, is for ever and ever: the sceptre of thy kingdom is a right sceptre.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 7, E'Thou lovest righteousness, and hatest wickedness: therefore God, thy God, hath anointed thee with the oil of gladness above thy fellows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 8, E'All thy garments smell of myrrh, and aloes, and cassia, out of the ivory palaces, whereby they have made thee glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 9, E'Kingsâ€™ daughters were among thy honourable women: upon thy right hand did stand the queen in gold of Ophir.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 10, E'Hearken, O daughter, and consider, and incline thine ear; forget also thine own people, and thy fatherâ€™s house;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 11, E'So shall the king greatly desire thy beauty: for he is thy Lord; and worship thou him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 12, E'And the daughter of Tyre shall be there with a gift; even the rich among the people shall intreat thy favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 13, E'The kingâ€™s daughter is all glorious within: her clothing is of wrought gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 14, E'She shall be brought unto the king in raiment of needlework: the virgins her companions that follow her shall be brought unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 15, E'With gladness and rejoicing shall they be brought: they shall enter into the kingâ€™s palace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 16, E'Instead of thy fathers shall be thy children, whom thou mayest make princes in all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 45, 17, E'I will make thy name to be remembered in all generations: therefore shall the people praise thee for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 1, E'God is our refuge and strength, a very present help in trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 2, E'Therefore will not we fear, though the earth be removed, and though the mountains be carried into the midst of the sea;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 3, E'Though the waters thereof roar and be troubled, though the mountains shake with the swelling thereof. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 4, E'There is a river, the streams whereof shall make glad the city of God, the holy place of the tabernacles of the most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 5, E'God is in the midst of her; she shall not be moved: God shall help her, and that right early.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 6, E'The heathen raged, the kingdoms were moved: he uttered his voice, the earth melted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 7, E'The LORD of hosts is with us; the God of Jacob is our refuge. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 8, E'Come, behold the works of the LORD, what desolations he hath made in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 9, E'He maketh wars to cease unto the end of the earth; he breaketh the bow, and cutteth the spear in sunder; he burneth the chariot in the fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 10, E'Be still, and know that I am God: I will be exalted among the heathen, I will be exalted in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 46, 11, E'The LORD of hosts is with us; the God of Jacob is our refuge. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 1, E'O clap your hands, all ye people; shout unto God with the voice of triumph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 2, E'For the LORD most high is terrible; he is a great King over all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 3, E'He shall subdue the people under us, and the nations under our feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 4, E'He shall choose our inheritance for us, the excellency of Jacob whom he loved. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 5, E'God is gone up with a shout, the LORD with the sound of a trumpet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 6, E'Sing praises to God, sing praises: sing praises unto our King, sing praises.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 7, E'For God is the King of all the earth: sing ye praises with understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 8, E'God reigneth over the heathen: God sitteth upon the throne of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 47, 9, E'The princes of the people are gathered together, even the people of the God of Abraham: for the shields of the earth belong unto God: he is greatly exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 1, E'Great is the LORD, and greatly to be praised in the city of our God, in the mountain of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 2, E'Beautiful for situation, the joy of the whole earth, is mount Zion, on the sides of the north, the city of the great King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 3, E'God is known in her palaces for a refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 4, E'For, lo, the kings were assembled, they passed by together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 5, E'They saw it, and so they marvelled; they were troubled, and hasted away.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 6, E'Fear took hold upon them there, and pain, as of a woman in travail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 7, E'Thou breakest the ships of Tarshish with an east wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 8, E'As we have heard, so have we seen in the city of the LORD of hosts, in the city of our God: God will establish it for ever. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 9, E'We have thought of thy lovingkindness, O God, in the midst of thy temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 10, E'According to thy name, O God, so is thy praise unto the ends of the earth: thy right hand is full of righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 11, E'Let mount Zion rejoice, let the daughters of Judah be glad, because of thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 12, E'Walk about Zion, and go round about her: tell the towers thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 13, E'Mark ye well her bulwarks, consider her palaces; that ye may tell it to the generation following.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 48, 14, E'For this God is our God for ever and ever: he will be our guide even unto death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 1, E'Hear this, all ye people; give ear, all ye inhabitants of the world:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 2, E'Both low and high, rich and poor, together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 3, E'My mouth shall speak of wisdom; and the meditation of my heart shall be of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 4, E'I will incline mine ear to a parable: I will open my dark saying upon the harp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 5, E'Wherefore should I fear in the days of evil, when the iniquity of my heels shall compass me about?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 6, E'They that trust in their wealth, and boast themselves in the multitude of their riches;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 7, E'None of them can by any means redeem his brother, nor give to God a ransom for him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 8, E'(For the redemption of their soul is precious, and it ceaseth for ever:)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 9, E'That he should still live for ever, and not see corruption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 10, E'For he seeth that wise men die, likewise the fool and the brutish person perish, and leave their wealth to others.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 11, E'Their inward thought is, that their houses shall continue for ever, and their dwelling places to all generations; they call their lands after their own names.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 12, E'Nevertheless man being in honour abideth not: he is like the beasts that perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 13, E'This their way is their folly: yet their posterity approve their sayings. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 14, E'Like sheep they are laid in the grave; death shall feed on them; and the upright shall have dominion over them in the morning; and their beauty shall consume in the grave from their dwelling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 15, E'But God will redeem my soul from the power of the grave: for he shall receive me. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 16, E'Be not thou afraid when one is made rich, when the glory of his house is increased;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 17, E'For when he dieth he shall carry nothing away: his glory shall not descend after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 18, E'Though while he lived he blessed his soul: and men will praise thee, when thou doest well to thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 19, E'He shall go to the generation of his fathers; they shall never see light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 49, 20, E'Man that is in honour, and understandeth not, is like the beasts that perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 1, E'The mighty God, even the LORD, hath spoken, and called the earth from the rising of the sun unto the going down thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 2, E'Out of Zion, the perfection of beauty, God hath shined.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 3, E'Our God shall come, and shall not keep silence: a fire shall devour before him, and it shall be very tempestuous round about him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 4, E'He shall call to the heavens from above, and to the earth, that he may judge his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 5, E'Gather my saints together unto me; those that have made a covenant with me by sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 6, E'And the heavens shall declare his righteousness: for God is judge himself. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 7, E'Hear, O my people, and I will speak; O Israel, and I will testify against thee: I am God, even thy God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 8, E'I will not reprove thee for thy sacrifices or thy burnt offerings, to have been continually before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 9, E'I will take no bullock out of thy house, nor he goats out of thy folds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 10, E'For every beast of the forest is mine, and the cattle upon a thousand hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 11, E'I know all the fowls of the mountains: and the wild beasts of the field are mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 12, E'If I were hungry, I would not tell thee: for the world is mine, and the fulness thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 13, E'Will I eat the flesh of bulls, or drink the blood of goats?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 14, E'Offer unto God thanksgiving; and pay thy vows unto the most High:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 15, E'And call upon me in the day of trouble: I will deliver thee, and thou shalt glorify me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 16, E'But unto the wicked God saith, What hast thou to do to declare my statutes, or that thou shouldest take my covenant in thy mouth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 17, E'Seeing thou hatest instruction, and casteth my words behind thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 18, E'When thou sawest a thief, then thou consentedst with him, and hast been partaker with adulterers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 19, E'Thou givest thy mouth to evil, and thy tongue frameth deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 20, E'Thou sittest and speakest against thy brother; thou slanderest thine own motherâ€™s son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 21, E'These things hast thou done, and I kept silence; thou thoughtest that I was altogether such an one as thyself: but I will reprove thee, and set them in order before thine eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 22, E'Now consider this, ye that forget God, lest I tear you in pieces, and there be none to deliver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 50, 23, E'Whoso offereth praise glorifieth me: and to him that ordereth his conversation aright will I shew the salvation of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 1, E'Have mercy upon me, O God, according to thy lovingkindness: according unto the multitude of thy tender mercies blot out my transgressions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 2, E'Wash me throughly from mine iniquity, and cleanse me from my sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 3, E'For I acknowledge my transgressions: and my sin is ever before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 4, E'Against thee, thee only, have I sinned, and done this evil in thy sight: that thou mightest be justified when thou speakest, and be clear when thou judgest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 5, E'Behold, I was shapen in iniquity; and in sin did my mother conceive me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 6, E'Behold, thou desirest truth in the inward parts: and in the hidden part thou shalt make me to know wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 7, E'Purge me with hyssop, and I shall be clean: wash me, and I shall be whiter than snow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 8, E'Make me to hear joy and gladness; that the bones which thou hast broken may rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 9, E'Hide thy face from my sins, and blot out all mine iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 10, E'Create in me a clean heart, O God; and renew a right spirit within me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 11, E'Cast me not away from thy presence; and take not thy holy spirit from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 12, E'Restore unto me the joy of thy salvation; and uphold me with thy free spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 13, E'Then will I teach transgressors thy ways; and sinners shall be converted unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 14, E'Deliver me from bloodguiltiness, O God, thou God of my salvation: and my tongue shall sing aloud of thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 15, E'O Lord, open thou my lips; and my mouth shall shew forth thy praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 16, E'For thou desirest not sacrifice; else would I give it: thou delightest not in burnt offering.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 17, E'The sacrifices of God are a broken spirit: a broken and a contrite heart, O God, thou wilt not despise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 18, E'Do good in thy good pleasure unto Zion: build thou the walls of Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 51, 19, E'Then shalt thou be pleased with the sacrifices of righteousness, with burnt offering and whole burnt offering: then shall they offer bullocks upon thine altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 1, E'Why boastest thou thyself in mischief, O mighty man? the goodness of God endureth continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 2, E'Thy tongue deviseth mischiefs; like a sharp razor, working deceitfully.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 3, E'Thou lovest evil more than good; and lying rather than to speak righteousness. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 4, E'Thou lovest all devouring words, O thou deceitful tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 5, E'God shall likewise destroy thee for ever, he shall take thee away, and pluck thee out of thy dwelling place, and root thee out of the land of the living. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 6, E'The righteous also shall see, and fear, and shall laugh at him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 7, E'Lo, this is the man that made not God his strength; but trusted in the abundance of his riches, and strengthened himself in his wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 8, E'But I am like a green olive tree in the house of God: I trust in the mercy of God for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 52, 9, E'I will praise thee for ever, because thou hast done it: and I will wait on thy name; for it is good before thy saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 1, E'The fool hath said in his heart, There is no God. Corrupt are they, and have done abominable iniquity: there is none that doeth good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 2, E'God looked down from heaven upon the children of men, to see if there were any that did understand, that did seek God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 3, E'Every one of them is gone back: they are altogether become filthy; there is none that doeth good, no, not one.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 4, E'Have the workers of iniquity no knowledge? who eat up my people as they eat bread: they have not called upon God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 5, E'There were they in great fear, where no fear was: for God hath scattered the bones of him that encampeth against thee: thou hast put them to shame, because God hath despised them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 53, 6, E'Oh that the salvation of Israel were come out of Zion! When God bringeth back the captivity of his people, Jacob shall rejoice, and Israel shall be glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 1, E'Save me, O God, by thy name, and judge me by thy strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 2, E'Hear my prayer, O God; give ear to the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 3, E'For strangers are risen up against me, and oppressors seek after my soul: they have not set God before them. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 4, E'Behold, God is mine helper: the Lord is with them that uphold my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 5, E'He shall reward evil unto mine enemies: cut them off in thy truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 6, E'I will freely sacrifice unto thee: I will praise thy name, O LORD; for it is good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 54, 7, E'For he hath delivered me out of all trouble: and mine eye hath seen his desire upon mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 1, E'Give ear to my prayer, O God; and hide not thyself from my supplication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 2, E'Attend unto me, and hear me: I mourn in my complaint, and make a noise;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 3, E'Because of the voice of the enemy, because of the oppression of the wicked: for they cast iniquity upon me, and in wrath they hate me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 4, E'My heart is sore pained within me: and the terrors of death are fallen upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 5, E'Fearfulness and trembling are come upon me, and horror hath overwhelmed me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 6, E'And I said, Oh that I had wings like a dove! for then would I fly away, and be at rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 7, E'Lo, then would I wander far off, and remain in the wilderness. Selah.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 8, E'I would hasten my escape from the windy storm and tempest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 9, E'Destroy, O Lord, and divide their tongues: for I have seen violence and strife in the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 10, E'Day and night they go about it upon the walls thereof: mischief also and sorrow are in the midst of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 11, E'Wickedness is in the midst thereof: deceit and guile depart not from her streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 12, E'For it was not an enemy that reproached me; then I could have borne it: neither was it he that hated me that did magnify himself against me; then I would have hid myself from him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 13, E'But it was thou, a man mine equal, my guide, and mine acquaintance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 14, E'We took sweet counsel together, and walked unto the house of God in company.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 15, E'Let death seize upon them, and let them go down quick into hell: for wickedness is in their dwellings, and among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 16, E'As for me, I will call upon God; and the LORD shall save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 17, E'Evening, and morning, and at noon, will I pray, and cry aloud: and he shall hear my voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 18, E'He hath delivered my soul in peace from the battle that was against me: for there were many with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 19, E'God shall hear, and afflict them, even he that abideth of old. Selah. Because they have no changes, therefore they fear not God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 20, E'He hath put forth his hands against such as be at peace with him: he hath broken his covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 21, E'The words of his mouth were smoother than butter, but war was in his heart: his words were softer than oil, yet were they drawn swords.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 22, E'Cast thy burden upon the LORD, and he shall sustain thee: he shall never suffer the righteous to be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 55, 23, E'But thou, O God, shalt bring them down into the pit of destruction: bloody and deceitful men shall not live out half their days; but I will trust in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 1, E'Be merciful unto me, O God: for man would swallow me up; he fighting daily oppresseth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 2, E'Mine enemies would daily swallow me up: for they be many that fight against me, O thou most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 3, E'What time I am afraid, I will trust in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 4, E'In God I will praise his word, in God I have put my trust; I will not fear what flesh can do unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 5, E'Every day they wrest my words: all their thoughts are against me for evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 6, E'They gather themselves together, they hide themselves, they mark my steps, when they wait for my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 7, E'Shall they escape by iniquity? in thine anger cast down the people, O God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 8, E'Thou tellest my wanderings: put thou my tears into thy bottle: are they not in thy book?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 9, E'When I cry unto thee, then shall mine enemies turn back: this I know; for God is for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 10, E'In God will I praise his word: in the LORD will I praise his word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 11, E'In God have I put my trust: I will not be afraid what man can do unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 12, E'Thy vows are upon me, O God: I will render praises unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 56, 13, E'For thou hast delivered my soul from death: wilt not thou deliver my feet from falling, that I may walk before God in the light of the living?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 1, E'Be merciful unto me, O God, be merciful unto me: for my soul trusteth in thee: yea, in the shadow of thy wings will I make my refuge, until these calamities be overpast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 2, E'I will cry unto God most high; unto God that performeth all things for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 3, E'He shall send from heaven, and save me from the reproach of him that would swallow me up. Selah. God shall send forth his mercy and his truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 4, E'My soul is among lions: and I lie even among them that are set on fire, even the sons of men, whose teeth are spears and arrows, and their tongue a sharp sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 5, E'Be thou exalted, O God, above the heavens; let thy glory be above all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 6, E'They have prepared a net for my steps; my soul is bowed down: they have digged a pit before me, into the midst whereof they are fallen themselves. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 7, E'My heart is fixed, O God, my heart is fixed: I will sing and give praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 8, E'Awake up, my glory; awake, psaltery and harp: I myself will awake early.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 9, E'I will praise thee, O Lord, among the people: I will sing unto thee among the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 10, E'For thy mercy is great unto the heavens, and thy truth unto the clouds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 57, 11, E'Be thou exalted, O God, above the heavens: let thy glory be above all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 1, E'Do ye indeed speak righteousness, O congregation? do ye judge uprightly, O ye sons of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 2, E'Yea, in heart ye work wickedness; ye weigh the violence of your hands in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 3, E'The wicked are estranged from the womb: they go astray as soon as they be born, speaking lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 4, E'Their poison is like the poison of a serpent: they are like the deaf adder that stoppeth her ear;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 5, E'Which will not hearken to the voice of charmers, charming never so wisely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 6, E'Break their teeth, O God, in their mouth: break out the great teeth of the young lions, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 7, E'Let them melt away as waters which run continually: when he bendeth his bow to shoot his arrows, let them be as cut in pieces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 8, E'As a snail which melteth, let every one of them pass away: like the untimely birth of a woman, that they may not see the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 9, E'Before your pots can feel the thorns, he shall take them away as with a whirlwind, both living, and in his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 10, E'The righteous shall rejoice when he seeth the vengeance: he shall wash his feet in the blood of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 58, 11, E'So that a man shall say, Verily there is a reward for the righteous: verily he is a God that judgeth in the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 1, E'Deliver me from mine enemies, O my God: defend me from them that rise up against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 2, E'Deliver me from the workers of iniquity, and save me from bloody men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 3, E'For, lo, they lie in wait for my soul: the mighty are gathered against me; not for my transgression, nor for my sin, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 4, E'They run and prepare themselves without my fault: awake to help me, and behold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 5, E'Thou therefore, O LORD God of hosts, the God of Israel, awake to visit all the heathen: be not merciful to any wicked transgressors. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 6, E'They return at evening: they make a noise like a dog, and go round about the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 7, E'Behold, they belch out with their mouth: swords are in their lips: for who, say they, doth hear?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 8, E'But thou, O LORD, shalt laugh at them; thou shalt have all the heathen in derision.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 9, E'Because of his strength will I wait upon thee: for God is my defence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 10, E'The God of my mercy shall prevent me: God shall let me see my desire upon mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 11, E'Slay them not, lest my people forget: scatter them by thy power; and bring them down, O Lord our shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 12, E'For the sin of their mouth and the words of their lips let them even be taken in their pride: and for cursing and lying which they speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 13, E'Consume them in wrath, consume them, that they may not be: and let them know that God ruleth in Jacob unto the ends of the earth. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 14, E'And at evening let them return; and let them make a noise like a dog, and go round about the city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 15, E'Let them wander up and down for meat, and grudge if they be not satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 16, E'But I will sing of thy power; yea, I will sing aloud of thy mercy in the morning: for thou hast been my defence and refuge in the day of my trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 59, 17, E'Unto thee, O my strength, will I sing: for God is my defence, and the God of my mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 1, E'O God, thou hast cast us off, thou hast scattered us, thou hast been displeased; O turn thyself to us again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 2, E'Thou hast made the earth to tremble; thou hast broken it: heal the breaches thereof; for it shaketh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 3, E'Thou hast shewed thy people hard things: thou hast made us to drink the wine of astonishment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 4, E'Thou hast given a banner to them that fear thee, that it may be displayed because of the truth. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 5, E'That thy beloved may be delivered; save with thy right hand, and hear me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 6, E'God hath spoken in his holiness; I will rejoice, I will divide Shechem, and mete out the valley of Succoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 7, E'Gilead is mine, and Manasseh is mine; Ephraim also is the strength of mine head; Judah is my lawgiver;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 8, E'Moab is my washpot; over Edom will I cast out my shoe: Philistia, triumph thou because of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 9, E'Who will bring me into the strong city? who will lead me into Edom?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 10, E'Wilt not thou, O God, which hadst cast us off? and thou, O God, which didst not go out with our armies?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 11, E'Give us help from trouble: for vain is the help of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 60, 12, E'Through God we shall do valiantly: for he it is that shall tread down our enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 1, E'Hear my cry, O God; attend unto my prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 2, E'From the end of the earth will I cry unto thee, when my heart is overwhelmed: lead me to the rock that is higher than I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 3, E'For thou hast been a shelter for me, and a strong tower from the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 4, E'I will abide in thy tabernacle for ever: I will trust in the covert of thy wings. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 5, E'For thou, O God, hast heard my vows: thou hast given me the heritage of those that fear thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 6, E'Thou wilt prolong the kingâ€™s life: and his years as many generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 7, E'He shall abide before God for ever: O prepare mercy and truth, which may preserve him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 61, 8, E'So will I sing praise unto thy name for ever, that I may daily perform my vows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 1, E'Truly my soul waiteth upon God: from him cometh my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 2, E'He only is my rock and my salvation; he is my defence; I shall not be greatly moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 3, E'How long will ye imagine mischief against a man? ye shall be slain all of you: as a bowing wall shall ye be, and as a tottering fence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 4, E'They only consult to cast him down from his excellency: they delight in lies: they bless with their mouth, but they curse inwardly. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 5, E'My soul, wait thou only upon God; for my expectation is from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 6, E'He only is my rock and my salvation: he is my defence; I shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 7, E'In God is my salvation and my glory: the rock of my strength, and my refuge, is in God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 8, E'Trust in him at all times; ye people, pour out your heart before him: God is a refuge for us. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 9, E'Surely men of low degree are vanity, and men of high degree are a lie: to be laid in the balance, they are altogether lighter than vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 10, E'Trust not in oppression, and become not vain in robbery: if riches increase, set not your heart upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 11, E'God hath spoken once; twice have I heard this; that power belongeth unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 62, 12, E'Also unto thee, O Lord, belongeth mercy: for thou renderest to every man according to his work.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 1, E'O God, thou art my God; early will I seek thee: my soul thirsteth for thee, my flesh longeth for thee in a dry and thirsty land, where no water is;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 2, E'To see thy power and thy glory, so as I have seen thee in the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 3, E'Because thy lovingkindness is better than life, my lips shall praise thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 4, E'Thus will I bless thee while I live: I will lift up my hands in thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 5, E'My soul shall be satisfied as with marrow and fatness; and my mouth shall praise thee with joyful lips:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 6, E'When I remember thee upon my bed, and meditate on thee in the night watches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 7, E'Because thou hast been my help, therefore in the shadow of thy wings will I rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 8, E'My soul followeth hard after thee: thy right hand upholdeth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 9, E'But those that seek my soul, to destroy it, shall go into the lower parts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 10, E'They shall fall by the sword: they shall be a portion for foxes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 63, 11, E'But the king shall rejoice in God; every one that sweareth by him shall glory: but the mouth of them that speak lies shall be stopped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 1, E'Hear my voice, O God, in my prayer: preserve my life from fear of the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 2, E'Hide me from the secret counsel of the wicked; from the insurrection of the workers of iniquity:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 3, E'Who whet their tongue like a sword, and bend their bows to shoot their arrows, even bitter words:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 4, E'That they may shoot in secret at the perfect: suddenly do they shoot at him, and fear not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 5, E'They encourage themselves in an evil matter: they commune of laying snares privily; they say, Who shall see them?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 6, E'They search out iniquities; they accomplish a diligent search: both the inward thought of every one of them, and the heart, is deep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 7, E'But God shall shoot at them with an arrow; suddenly shall they be wounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 8, E'So they shall make their own tongue to fall upon themselves: all that see them shall flee away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 9, E'And all men shall fear, and shall declare the work of God; for they shall wisely consider of his doing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 64, 10, E'The righteous shall be glad in the LORD, and shall trust in him; and all the upright in heart shall glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 1, E'Praise waiteth for thee, O God, in Sion: and unto thee shall the vow be performed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 2, E'O thou that hearest prayer, unto thee shall all flesh come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 3, E'Iniquities prevail against me: as for our transgressions, thou shalt purge them away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 4, E'Blessed is the man whom thou choosest, and causest to approach unto thee, that he may dwell in thy courts: we shall be satisfied with the goodness of thy house, even of thy holy temple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 5, E'By terrible things in righteousness wilt thou answer us, O God of our salvation; who art the confidence of all the ends of the earth, and of them that are afar off upon the sea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 6, E'Which by his strength setteth fast the mountains; being girded with power:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 7, E'Which stilleth the noise of the seas, the noise of their waves, and the tumult of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 8, E'They also that dwell in the uttermost parts are afraid at thy tokens: thou makest the outgoings of the morning and evening to rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 9, E'Thou visitest the earth, and waterest it: thou greatly enrichest it with the river of God, which is full of water: thou preparest them corn, when thou hast so provided for it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 10, E'Thou waterest the ridges thereof abundantly: thou settlest the furrows thereof: thou makest it soft with showers: thou blessest the springing thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 11, E'Thou crownest the year with thy goodness; and thy paths drop fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 12, E'They drop upon the pastures of the wilderness: and the little hills rejoice on every side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 65, 13, E'The pastures are clothed with flocks; the valleys also are covered over with corn; they shout for joy, they also sing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 1, E'Make a joyful noise unto God, all ye lands:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 2, E'Sing forth the honour of his name: make his praise glorious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 3, E'Say unto God, How terrible art thou in thy works! through the greatness of thy power shall thine enemies submit themselves unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 4, E'All the earth shall worship thee, and shall sing unto thee; they shall sing to thy name. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 5, E'Come and see the works of God: he is terrible in his doing toward the children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 6, E'He turned the sea into dry land: they went through the flood on foot: there did we rejoice in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 7, E'He ruleth by his power for ever; his eyes behold the nations: let not the rebellious exalt themselves. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 8, E'O bless our God, ye people, and make the voice of his praise to be heard:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 9, E'Which holdeth our soul in life, and suffereth not our feet to be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 10, E'For thou, O God, hast proved us: thou hast tried us, as silver is tried.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 11, E'Thou broughtest us into the net; thou laidst affliction upon our loins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 12, E'Thou hast caused men to ride over our heads; we went through fire and through water: but thou broughtest us out into a wealthy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 13, E'I will go into thy house with burnt offerings: I will pay thee my vows,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 14, E'Which my lips have uttered, and my mouth hath spoken, when I was in trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 15, E'I will offer unto thee burnt sacrifices of fatlings, with the incense of rams; I will offer bullocks with goats. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 16, E'Come and hear, all ye that fear God, and I will declare what he hath done for my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 17, E'I cried unto him with my mouth, and he was extolled with my tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 18, E'If I regard iniquity in my heart, the Lord will not hear me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 19, E'But verily God hath heard me; he hath attended to the voice of my prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 66, 20, E'Blessed be God, which hath not turned away my prayer, nor his mercy from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 1, E'God be merciful unto us, and bless us; and cause his face to shine upon us; Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 2, E'That thy way may be known upon earth, thy saving health among all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 3, E'Let the people praise thee, O God; let all the people praise thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 4, E'O let the nations be glad and sing for joy: for thou shalt judge the people righteously, and govern the nations upon earth. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 5, E'Let the people praise thee, O God; let all the people praise thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 6, E'Then shall the earth yield her increase; and God, even our own God, shall bless us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 67, 7, E'God shall bless us; and all the ends of the earth shall fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 1, E'Let God arise, let his enemies be scattered: let them also that hate him flee before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 2, E'As smoke is driven away, so drive them away: as wax melteth before the fire, so let the wicked perish at the presence of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 3, E'But let the righteous be glad; let them rejoice before God: yea, let them exceedingly rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 4, E'Sing unto God, sing praises to his name: extol him that rideth upon the heavens by his name JAH, and rejoice before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 5, E'A father of the fatherless, and a judge of the widows, is God in his holy habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 6, E'God setteth the solitary in families: he bringeth out those which are bound with chains: but the rebellious dwell in a dry land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 7, E'O God, when thou wentest forth before thy people, when thou didst march through the wilderness; Selah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 8, E'The earth shook, the heavens also dropped at the presence of God: even Sinai itself was moved at the presence of God, the God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 9, E'Thou, O God, didst send a plentiful rain, whereby thou didst confirm thine inheritance, when it was weary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 10, E'Thy congregation hath dwelt therein: thou, O God, hast prepared of thy goodness for the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 11, E'The Lord gave the word: great was the company of those that published it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 12, E'Kings of armies did flee apace: and she that tarried at home divided the spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 13, E'Though ye have lien among the pots, yet shall ye be as the wings of a dove covered with silver, and her feathers with yellow gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 14, E'When the Almighty scattered kings in it, it was white as snow in Salmon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 15, E'The hill of God is as the hill of Bashan; an high hill as the hill of Bashan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 16, E'Why leap ye, ye high hills? this is the hill which God desireth to dwell in; yea, the LORD will dwell in it for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 17, E'The chariots of God are twenty thousand, even thousands of angels: the Lord is among them, as in Sinai, in the holy place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 18, E'Thou hast ascended on high, thou hast led captivity captive: thou hast received gifts for men; yea, for the rebellious also, that the LORD God might dwell among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 19, E'Blessed be the Lord, who daily loadeth us with benefits, even the God of our salvation. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 20, E'He that is our God is the God of salvation; and unto GOD the Lord belong the issues from death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 21, E'But God shall wound the head of his enemies, and the hairy scalp of such an one as goeth on still in his trespasses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 22, E'The Lord said, I will bring again from Bashan, I will bring my people again from the depths of the sea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 23, E'That thy foot may be dipped in the blood of thine enemies, and the tongue of thy dogs in the same.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 24, E'They have seen thy goings, O God; even the goings of my God, my King, in the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 25, E'The singers went before, the players on instruments followed after; among them were the damsels playing with timbrels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 26, E'Bless ye God in the congregations, even the Lord, from the fountain of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 27, E'There is little Benjamin with their ruler, the princes of Judah and their council, the princes of Zebulun, and the princes of Naphtali.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 28, E'Thy God hath commanded thy strength: strengthen, O God, that which thou hast wrought for us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 29, E'Because of thy temple at Jerusalem shall kings bring presents unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 30, E'Rebuke the company of spearmen, the multitude of the bulls, with the calves of the people, till every one submit himself with pieces of silver: scatter thou the people that delight in war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 31, E'Princes shall come out of Egypt; Ethiopia shall soon stretch out her hands unto God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 32, E'Sing unto God, ye kingdoms of the earth; O sing praises unto the Lord; Selah:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 33, E'To him that rideth upon the heavens of heavens, which were of old; lo, he doth send out his voice, and that a mighty voice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 34, E'Ascribe ye strength unto God: his excellency is over Israel, and his strength is in the clouds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 68, 35, E'O God, thou art terrible out of thy holy places: the God of Israel is he that giveth strength and power unto his people. Blessed be God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 1, E'Save me, O God; for the waters are come in unto my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 2, E'I sink in deep mire, where there is no standing: I am come into deep waters, where the floods overflow me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 3, E'I am weary of my crying: my throat is dried: mine eyes fail while I wait for my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 4, E'They that hate me without a cause are more than the hairs of mine head: they that would destroy me, being mine enemies wrongfully, are mighty: then I restored that which I took not away.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 5, E'O God, thou knowest my foolishness; and my sins are not hid from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 6, E'Let not them that wait on thee, O Lord GOD of hosts, be ashamed for my sake: let not those that seek thee be confounded for my sake, O God of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 7, E'Because for thy sake I have borne reproach; shame hath covered my face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 8, E'I am become a stranger unto my brethren, and an alien unto my motherâ€™s children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 9, E'For the zeal of thine house hath eaten me up; and the reproaches of them that reproached thee are fallen upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 10, E'When I wept, and chastened my soul with fasting, that was to my reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 11, E'I made sackcloth also my garment; and I became a proverb to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 12, E'They that sit in the gate speak against me; and I was the song of the drunkards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 13, E'But as for me, my prayer is unto thee, O LORD, in an acceptable time: O God, in the multitude of thy mercy hear me, in the truth of thy salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 14, E'Deliver me out of the mire, and let me not sink: let me be delivered from them that hate me, and out of the deep waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 15, E'Let not the waterflood overflow me, neither let the deep swallow me up, and let not the pit shut her mouth upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 16, E'Hear me, O LORD; for thy lovingkindness is good: turn unto me according to the multitude of thy tender mercies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 17, E'And hide not thy face from thy servant; for I am in trouble: hear me speedily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 18, E'Draw nigh unto my soul, and redeem it: deliver me because of mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 19, E'Thou hast known my reproach, and my shame, and my dishonour: mine adversaries are all before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 20, E'Reproach hath broken my heart; and I am full of heaviness: and I looked for some to take pity, but there was none; and for comforters, but I found none.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 21, E'They gave me also gall for my meat; and in my thirst they gave me vinegar to drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 22, E'Let their table become a snare before them: and that which should have been for their welfare, let it become a trap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 23, E'Let their eyes be darkened, that they see not; and make their loins continually to shake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 24, E'Pour out thine indignation upon them, and let thy wrathful anger take hold of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 25, E'Let their habitation be desolate; and let none dwell in their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 26, E'For they persecute him whom thou hast smitten; and they talk to the grief of those whom thou hast wounded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 27, E'Add iniquity unto their iniquity: and let them not come into thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 28, E'Let them be blotted out of the book of the living, and not be written with the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 29, E'But I am poor and sorrowful: let thy salvation, O God, set me up on high.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 30, E'I will praise the name of God with a song, and will magnify him with thanksgiving.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 31, E'This also shall please the LORD better than an ox or bullock that hath horns and hoofs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 32, E'The humble shall see this, and be glad: and your heart shall live that seek God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 33, E'For the LORD heareth the poor, and despiseth not his prisoners.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 34, E'Let the heaven and earth praise him, the seas, and every thing that moveth therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 35, E'For God will save Zion, and will build the cities of Judah: that they may dwell there, and have it in possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 69, 36, E'The seed also of his servants shall inherit it: and they that love his name shall dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 70, 1, E'MAKE HASTE, O GOD, TO DELIVER ME; MAKE HASTE TO HELP ME, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 70, 2, E'Let them be ashamed and confounded that seek after my soul: let them be turned backward, and put to confusion, that desire my hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 70, 3, E'Let them be turned back for a reward of their shame that say, Aha, aha.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 70, 4, E'Let all those that seek thee rejoice and be glad in thee: and let such as love thy salvation say continually, Let God be magnified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 70, 5, E'But I am poor and needy: make haste unto me, O God: thou art my help and my deliverer; O LORD, make no tarrying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 1, E'In thee, O LORD, do I put my trust: let me never be put to confusion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 2, E'Deliver me in thy righteousness, and cause me to escape: incline thine ear unto me, and save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 3, E'Be thou my strong habitation, whereunto I may continually resort: thou hast given commandment to save me; for thou art my rock and my fortress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 4, E'Deliver me, O my God, out of the hand of the wicked, out of the hand of the unrighteous and cruel man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 5, E'For thou art my hope, O Lord GOD: thou art my trust from my youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 6, E'By thee have I been holden up from the womb: thou art he that took me out of my motherâ€™s bowels: my praise shall be continually of thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 7, E'I am as a wonder unto many; but thou art my strong refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 8, E'Let my mouth be filled with thy praise and with thy honour all the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 9, E'Cast me not off in the time of old age; forsake me not when my strength faileth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 10, E'For mine enemies speak against me; and they that lay wait for my soul take counsel together,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 11, E'Saying, God hath forsaken him: persecute and take him; for there is none to deliver him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 12, E'O God, be not far from me: O my God, make haste for my help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 13, E'Let them be confounded and consumed that are adversaries to my soul; let them be covered with reproach and dishonour that seek my hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 14, E'But I will hope continually, and will yet praise thee more and more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 15, E'My mouth shall shew forth thy righteousness and thy salvation all the day; for I know not the numbers thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 16, E'I will go in the strength of the Lord GOD: I will make mention of thy righteousness, even of thine only.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 17, E'O God, thou hast taught me from my youth: and hitherto have I declared thy wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 18, E'Now also when I am old and greyheaded, O God, forsake me not; until I have shewed thy strength unto this generation, and thy power to every one that is to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 19, E'Thy righteousness also, O God, is very high, who hast done great things: O God, who is like unto thee!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 20, E'Thou, which hast shewed me great and sore troubles, shalt quicken me again, and shalt bring me up again from the depths of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 21, E'Thou shalt increase my greatness, and comfort me on every side.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 22, E'I will also praise thee with the psaltery, even thy truth, O my God: unto thee will I sing with the harp, O thou Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 23, E'My lips shall greatly rejoice when I sing unto thee; and my soul, which thou hast redeemed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 71, 24, E'My tongue also shall talk of thy righteousness all the day long: for they are confounded, for they are brought unto shame, that seek my hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 1, E'Give the king thy judgments, O God, and thy righteousness unto the kingâ€™s son.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 2, E'He shall judge thy people with righteousness, and thy poor with judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 3, E'The mountains shall bring peace to the people, and the little hills, by righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 4, E'He shall judge the poor of the people, he shall save the children of the needy, and shall break in pieces the oppressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 5, E'They shall fear thee as long as the sun and moon endure, throughout all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 6, E'He shall come down like rain upon the mown grass: as showers that water the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 7, E'In his days shall the righteous flourish; and abundance of peace so long as the moon endureth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 8, E'He shall have dominion also from sea to sea, and from the river unto the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 9, E'They that dwell in the wilderness shall bow before him; and his enemies shall lick the dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 10, E'The kings of Tarshish and of the isles shall bring presents: the kings of Sheba and Seba shall offer gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 11, E'Yea, all kings shall fall down before him: all nations shall serve him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 12, E'For he shall deliver the needy when he crieth; the poor also, and him that hath no helper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 13, E'He shall spare the poor and needy, and shall save the souls of the needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 14, E'He shall redeem their soul from deceit and violence: and precious shall their blood be in his sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 15, E'And he shall live, and to him shall be given of the gold of Sheba: prayer also shall be made for him continually; and daily shall he be praised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 16, E'There shall be an handful of corn in the earth upon the top of the mountains; the fruit thereof shall shake like Lebanon: and they of the city shall flourish like grass of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 17, E'His name shall endure for ever: his name shall be continued as long as the sun: and men shall be blessed in him: all nations shall call him blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 18, E'Blessed be the LORD God, the God of Israel, who only doeth wondrous things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 19, E'And blessed be his glorious name for ever: and let the whole earth be filled with his glory; Amen, and Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 72, 20, E'The prayers of David the son of Jesse are ended.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 1, E'Truly God is good to Israel, even to such as are of a clean heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 2, E'But as for me, my feet were almost gone; my steps had well nigh slipped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 3, E'For I was envious at the foolish, when I saw the prosperity of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 4, E'For there are no bands in their death: but their strength is firm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 5, E'They are not in trouble as other men; neither are they plagued like other men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 6, E'Therefore pride compasseth them about as a chain; violence covereth them as a garment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 7, E'Their eyes stand out with fatness: they have more than heart could wish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 8, E'They are corrupt, and speak wickedly concerning oppression: they speak loftily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 9, E'They set their mouth against the heavens, and their tongue walketh through the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 10, E'Therefore his people return hither: and waters of a full cup are wrung out to them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 11, E'And they say, How doth God know? and is there knowledge in the most High?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 12, E'Behold, these are the ungodly, who prosper in the world; they increase in riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 13, E'Verily I have cleansed my heart in vain, and washed my hands in innocency.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 14, E'For all the day long have I been plagued, and chastened every morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 15, E'If I say, I will speak thus; behold, I should offend against the generation of thy children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 16, E'When I thought to know this, it was too painful for me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 17, E'Until I went into the sanctuary of God; then understood I their end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 18, E'Surely thou didst set them in slippery places: thou castedst them down into destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 19, E'How are they brought into desolation, as in a moment! they are utterly consumed with terrors.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 20, E'As a dream when one awaketh; so, O Lord, when thou awakest, thou shalt despise their image.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 21, E'Thus my heart was grieved, and I was pricked in my reins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 22, E'So foolish was I, and ignorant: I was as a beast before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 23, E'Nevertheless I am continually with thee: thou hast holden me by my right hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 24, E'Thou shalt guide me with thy counsel, and afterward receive me to glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 25, E'Whom have I in heaven but thee? and there is none upon earth that I desire beside thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 26, E'My flesh and my heart faileth: but God is the strength of my heart, and my portion for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 27, E'For, lo, they that are far from thee shall perish: thou hast destroyed all them that go a whoring from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 73, 28, E'But it is good for me to draw near to God: I have put my trust in the Lord GOD, that I may declare all thy works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 1, E'O God, why hast thou cast us off for ever? why doth thine anger smoke against the sheep of thy pasture?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 2, E'Remember thy congregation, which thou hast purchased of old; the rod of thine inheritance, which thou hast redeemed; this mount Zion, wherein thou hast dwelt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 3, E'Lift up thy feet unto the perpetual desolations; even all that the enemy hath done wickedly in the sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 4, E'Thine enemies roar in the midst of thy congregations; they set up their ensigns for signs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 5, E'A man was famous according as he had lifted up axes upon the thick trees.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 6, E'But now they break down the carved work thereof at once with axes and hammers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 7, E'They have cast fire into thy sanctuary, they have defiled by casting down the dwelling place of thy name to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 8, E'They said in their hearts, Let us destroy them together: they have burned up all the synagogues of God in the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 9, E'We see not our signs: there is no more any prophet: neither is there among us any that knoweth how long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 10, E'O God, how long shall the adversary reproach? shall the enemy blaspheme thy name for ever?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 11, E'Why withdrawest thou thy hand, even thy right hand? pluck it out of thy bosom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 12, E'For God is my King of old, working salvation in the midst of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 13, E'Thou didst divide the sea by thy strength: thou brakest the heads of the dragons in the waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 14, E'Thou brakest the heads of leviathan in pieces, and gavest him to be meat to the people inhabiting the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 15, E'Thou didst cleave the fountain and the flood: thou driedst up mighty rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 16, E'The day is thine, the night also is thine: thou hast prepared the light and the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 17, E'Thou hast set all the borders of the earth: thou hast made summer and winter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 18, E'Remember this, that the enemy hath reproached, O LORD, and that the foolish people have blasphemed thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 19, E'O deliver not the soul of thy turtledove unto the multitude of the wicked: forget not the congregation of thy poor for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 20, E'Have respect unto the covenant: for the dark places of the earth are full of the habitations of cruelty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 21, E'O let not the oppressed return ashamed: let the poor and needy praise thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 22, E'Arise, O God, plead thine own cause: remember how the foolish man reproacheth thee daily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 74, 23, E'Forget not the voice of thine enemies: the tumult of those that rise up against thee increaseth continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 1, E'Unto thee, O God, do we give thanks, unto thee do we give thanks: for that thy name is near thy wondrous works declare.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 2, E'When I shall receive the congregation I will judge uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 3, E'The earth and all the inhabitants thereof are dissolved: I bear up the pillars of it. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 4, E'I said unto the fools, Deal not foolishly: and to the wicked, Lift not up the horn:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 5, E'Lift not up your horn on high: speak not with a stiff neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 6, E'For promotion cometh neither from the east, nor from the west, nor from the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 7, E'But God is the judge: he putteth down one, and setteth up another.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 8, E'For in the hand of the LORD there is a cup, and the wine is red; it is full of mixture; and he poureth out of the same: but the dregs thereof, all the wicked of the earth shall wring them out, and drink them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 9, E'But I will declare for ever; I will sing praises to the God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 75, 10, E'All the horns of the wicked also will I cut off; but the horns of the righteous shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 1, E'In Judah is God known: his name is great in Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 2, E'In Salem also is his tabernacle, and his dwelling place in Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 3, E'There brake he the arrows of the bow, the shield, and the sword, and the battle. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 4, E'Thou art more glorious and excellent than the mountains of prey.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 5, E'The stouthearted are spoiled, they have slept their sleep: and none of the men of might have found their hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 6, E'At thy rebuke, O God of Jacob, both the chariot and horse are cast into a dead sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 7, E'Thou, even thou, art to be feared: and who may stand in thy sight when once thou art angry?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 8, E'Thou didst cause judgment to be heard from heaven; the earth feared, and was still,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 9, E'When God arose to judgment, to save all the meek of the earth. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 10, E'Surely the wrath of man shall praise thee: the remainder of wrath shalt thou restrain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 11, E'Vow, and pay unto the LORD your God: let all that be round about him bring presents unto him that ought to be feared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 76, 12, E'He shall cut off the spirit of princes: he is terrible to the kings of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 1, E'I cried unto God with my voice, even unto God with my voice; and he gave ear unto me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 2, E'In the day of my trouble I sought the Lord: my sore ran in the night, and ceased not: my soul refused to be comforted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 3, E'I remembered God, and was troubled: I complained, and my spirit was overwhelmed. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 4, E'Thou holdest mine eyes waking: I am so troubled that I cannot speak.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 5, E'I have considered the days of old, the years of ancient times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 6, E'I call to remembrance my song in the night: I commune with mine own heart: and my spirit made diligent search.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 7, E'Will the Lord cast off for ever? and will he be favourable no more?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 8, E'Is his mercy clean gone for ever? doth his promise fail for evermore?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 9, E'Hath God forgotten to be gracious? hath he in anger shut up his tender mercies? Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 10, E'And I said, This is my infirmity: but I will remember the years of the right hand of the most High.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 11, E'I will remember the works of the LORD: surely I will remember thy wonders of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 12, E'I will meditate also of all thy work, and talk of thy doings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 13, E'Thy way, O God, is in the sanctuary: who is so great a God as our God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 14, E'Thou art the God that doest wonders: thou hast declared thy strength among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 15, E'Thou hast with thine arm redeemed thy people, the sons of Jacob and Joseph. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 16, E'The waters saw thee, O God, the waters saw thee; they were afraid: the depths also were troubled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 17, E'The clouds poured out water: the skies sent out a sound: thine arrows also went abroad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 18, E'The voice of thy thunder was in the heaven: the lightnings lightened the world: the earth trembled and shook.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 19, E'Thy way is in the sea, and thy path in the great waters, and thy footsteps are not known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 77, 20, E'Thou leddest thy people like a flock by the hand of Moses and Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 1, E'Give ear, O my people, to my law: incline your ears to the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 2, E'I will open my mouth in a parable: I will utter dark sayings of old:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 3, E'Which we have heard and known, and our fathers have told us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 4, E'We will not hide them from their children, shewing to the generation to come the praises of the LORD, and his strength, and his wonderful works that he hath done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 5, E'For he established a testimony in Jacob, and appointed a law in Israel, which he commanded our fathers, that they should make them known to their children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 6, E'That the generation to come might know them, even the children which should be born; who should arise and declare them to their children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 7, E'That they might set their hope in God, and not forget the works of God, but keep his commandments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 8, E'And might not be as their fathers, a stubborn and rebellious generation; a generation that set not their heart aright, and whose spirit was not stedfast with God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 9, E'The children of Ephraim, being armed, and carrying bows, turned back in the day of battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 10, E'They kept not the covenant of God, and refused to walk in his law;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 11, E'And forgat his works, and his wonders that he had shewed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 12, E'Marvellous things did he in the sight of their fathers, in the land of Egypt, in the field of Zoan.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 13, E'He divided the sea, and caused them to pass through; and he made the waters to stand as an heap.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 14, E'In the daytime also he led them with a cloud, and all the night with a light of fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 15, E'He clave the rocks in the wilderness, and gave them drink as out of the great depths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 16, E'He brought streams also out of the rock, and caused waters to run down like rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 17, E'And they sinned yet more against him by provoking the most High in the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 18, E'And they tempted God in their heart by asking meat for their lust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 19, E'Yea, they spake against God; they said, Can God furnish a table in the wilderness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 20, E'Behold, he smote the rock, that the waters gushed out, and the streams overflowed; can he give bread also? can he provide flesh for his people?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 21, E'Therefore the LORD heard this, and was wroth: so a fire was kindled against Jacob, and anger also came up against Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 22, E'Because they believed not in God, and trusted not in his salvation:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 23, E'Though he had commanded the clouds from above, and opened the doors of heaven,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 24, E'And had rained down manna upon them to eat, and had given them of the corn of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 25, E'Man did eat angelsâ€™ food: he sent them meat to the full.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 26, E'He caused an east wind to blow in the heaven: and by his power he brought in the south wind.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 27, E'He rained flesh also upon them as dust, and feathered fowls like as the sand of the sea:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 28, E'And he let it fall in the midst of their camp, round about their habitations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 29, E'So they did eat, and were well filled: for he gave them their own desire;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 30, E'They were not estranged from their lust. But while their meat was yet in their mouths,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 31, E'The wrath of God came upon them, and slew the fattest of them, and smote down the chosen men of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 32, E'For all this they sinned still, and believed not for his wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 33, E'Therefore their days did he consume in vanity, and their years in trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 34, E'When he slew them, then they sought him: and they returned and enquired early after God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 35, E'And they remembered that God was their rock, and the high God their redeemer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 36, E'Nevertheless they did flatter him with their mouth, and they lied unto him with their tongues.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 37, E'For their heart was not right with him, neither were they stedfast in his covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 38, E'But he, being full of compassion, forgave their iniquity, and destroyed them not: yea, many a time turned he his anger away, and did not stir up all his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 39, E'For he remembered that they were but flesh; a wind that passeth away, and cometh not again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 40, E'How oft did they provoke him in the wilderness, and grieve him in the desert!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 41, E'Yea, they turned back and tempted God, and limited the Holy One of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 42, E'They remembered not his hand, nor the day when he delivered them from the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 43, E'How he had wrought his signs in Egypt, and his wonders in the field of Zoan:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 44, E'And had turned their rivers into blood; and their floods, that they could not drink.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 45, E'He sent divers sorts of flies among them, which devoured them; and frogs, which destroyed them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 46, E'He gave also their increase unto the caterpiller, and their labour unto the locust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 47, E'He destroyed their vines with hail, and their sycomore trees with frost.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 48, E'He gave up their cattle also to the hail, and their flocks to hot thunderbolts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 49, E'He cast upon them the fierceness of his anger, wrath, and indignation, and trouble, by sending evil angels among them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 50, E'He made a way to his anger; he spared not their soul from death, but gave their life over to the pestilence;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 51, E'And smote all the firstborn in Egypt; the chief of their strength in the tabernacles of Ham:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 52, E'But made his own people to go forth like sheep, and guided them in the wilderness like a flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 53, E'And he led them on safely, so that they feared not: but the sea overwhelmed their enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 54, E'And he brought them to the border of his sanctuary, even to this mountain, which his right hand had purchased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 55, E'He cast out the heathen also before them, and divided them an inheritance by line, and made the tribes of Israel to dwell in their tents.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 56, E'Yet they tempted and provoked the most high God, and kept not his testimonies:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 57, E'But turned back, and dealt unfaithfully like their fathers: they were turned aside like a deceitful bow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 58, E'For they provoked him to anger with their high places, and moved him to jealousy with their graven images.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 59, E'When God heard this, he was wroth, and greatly abhorred Israel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 60, E'So that he forsook the tabernacle of Shiloh, the tent which he placed among men;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 61, E'And delivered his strength into captivity, and his glory into the enemyâ€™s hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 62, E'He gave his people over also unto the sword; and was wroth with his inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 63, E'The fire consumed their young men; and their maidens were not given to marriage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 64, E'Their priests fell by the sword; and their widows made no lamentation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 65, E'Then the LORD awaked as one out of sleep, and like a mighty man that shouteth by reason of wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 66, E'And he smote his enemies in the hinder parts: he put them to a perpetual reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 67, E'Moreover he refused the tabernacle of Joseph, and chose not the tribe of Ephraim:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 68, E'But chose the tribe of Judah, the mount Zion which he loved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 69, E'And he built his sanctuary like high palaces, like the earth which he hath established for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 70, E'He chose David also his servant, and took him from the sheepfolds:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 71, E'From following the ewes great with young he brought him to feed Jacob his people, and Israel his inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 78, 72, E'So he fed them according to the integrity of his heart; and guided them by the skilfulness of his hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 1, E'O GOD, the heathen are come into thine inheritance; thy holy temple have they defiled; they have laid Jerusalem on heaps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 2, E'The dead bodies of thy servants have they given to be meat unto the fowls of the heaven, the flesh of thy saints unto the beasts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 3, E'Their blood have they shed like water round about Jerusalem; and there was none to bury them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 4, E'We are become a reproach to our neighbours, a scorn and derision to them that are round about us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 5, E'How long, LORD? wilt thou be angry for ever? shall thy jealousy burn like fire?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 6, E'Pour out thy wrath upon the heathen that have not known thee, and upon the kingdoms that have not called upon thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 7, E'For they have devoured Jacob, and laid waste his dwelling place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 8, E'O remember not against us former iniquities: let thy tender mercies speedily prevent us: for we are brought very low.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 9, E'Help us, O God of our salvation, for the glory of thy name: and deliver us, and purge away our sins, for thy nameâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 10, E'Wherefore should the heathen say, Where is their God? let him be known among the heathen in our sight by the revenging of the blood of thy servants which is shed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 11, E'Let the sighing of the prisoner come before thee; according to the greatness of thy power preserve thou those that are appointed to die;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 12, E'And render unto our neighbours sevenfold into their bosom their reproach, wherewith they have reproached thee, O Lord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 79, 13, E'So we thy people and sheep of thy pasture will give thee thanks for ever: we will shew forth thy praise to all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 1, E'Give ear, O Shepherd of Israel, thou that leadest Joseph like a flock; thou that dwellest between the cherubims, shine forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 2, E'Before Ephraim and Benjamin and Manasseh stir up thy strength, and come and save us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 3, E'Turn us again, O God, and cause thy face to shine; and we shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 4, E'O LORD God of hosts, how long wilt thou be angry against the prayer of thy people?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 5, E'Thou feedest them with the bread of tears; and givest them tears to drink in great measure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 6, E'Thou makest us a strife unto our neighbours: and our enemies laugh among themselves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 7, E'Turn us again, O God of hosts, and cause thy face to shine; and we shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 8, E'Thou hast brought a vine out of Egypt: thou hast cast out the heathen, and planted it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 9, E'Thou preparedst room before it, and didst cause it to take deep root, and it filled the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 10, E'The hills were covered with the shadow of it, and the boughs thereof were like the goodly cedars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 11, E'She sent out her boughs unto the sea, and her branches unto the river.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 12, E'Why hast thou then broken down her hedges, so that all they which pass by the way do pluck her?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 13, E'The boar out of the wood doth waste it, and the wild beast of the field doth devour it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 14, E'Return, we beseech thee, O God of hosts: look down from heaven, and behold, and visit this vine;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 15, E'And the vineyard which thy right hand hath planted, and the branch that thou madest strong for thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 16, E'It is burned with fire, it is cut down: they perish at the rebuke of thy countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 17, E'Let thy hand be upon the man of thy right hand, upon the son of man whom thou madest strong for thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 18, E'So will not we go back from thee: quicken us, and we will call upon thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 80, 19, E'Turn us again, O LORD God of hosts, cause thy face to shine; and we shall be saved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 1, E'Sing aloud unto God our strength: make a joyful noise unto the God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 2, E'Take a psalm, and bring hither the timbrel, the pleasant harp with the psaltery.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 3, E'Blow up the trumpet in the new moon, in the time appointed, on our solemn feast day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 4, E'For this was a statute for Israel, and a law of the God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 5, E'This he ordained in Joseph for a testimony, when he went out through the land of Egypt: where I heard a language that I understood not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 6, E'I removed his shoulder from the burden: his hands were delivered from the pots.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 7, E'Thou calledst in trouble, and I delivered thee; I answered thee in the secret place of thunder: I proved thee at the waters of Meribah. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 8, E'Hear, O my people, and I will testify unto thee: O Israel, if thou wilt hearken unto me;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 9, E'There shall no strange god be in thee; neither shalt thou worship any strange god.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 10, E'I am the LORD thy God, which brought thee out of the land of Egypt: open thy mouth wide, and I will fill it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 11, E'But my people would not hearken to my voice; and Israel would none of me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 12, E'So I gave them up unto their own heartsâ€™ lust: and they walked in their own counsels.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 13, E'Oh that my people had hearkened unto me, and Israel had walked in my ways!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 14, E'I should soon have subdued their enemies, and turned my hand against their adversaries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 15, E'The haters of the LORD should have submitted themselves unto him: but their time should have endured for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 81, 16, E'He should have fed them also with the finest of the wheat: and with honey out of the rock should I have satisfied thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 1, E'God standeth in the congregation of the mighty; he judgeth among the gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 2, E'How long will ye judge unjustly, and accept the persons of the wicked? Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 3, E'Defend the poor and fatherless: do justice to the afflicted and needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 4, E'Deliver the poor and needy: rid them out of the hand of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 5, E'They know not, neither will they understand; they walk on in darkness: all the foundations of the earth are out of course.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 6, E'I have said, Ye are gods; and all of you are children of the most High.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 7, E'But ye shall die like men, and fall like one of the princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 82, 8, E'Arise, O God, judge the earth: for thou shalt inherit all nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 1, E'Keep not thou silence, O God: hold not thy peace, and be not still, O God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 2, E'For, lo, thine enemies make a tumult: and they that hate thee have lifted up the head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 3, E'They have taken crafty counsel against thy people, and consulted against thy hidden ones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 4, E'They have said, Come, and let us cut them off from being a nation; that the name of Israel may be no more in remembrance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 5, E'For they have consulted together with one consent: they are confederate against thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 6, E'The tabernacles of Edom, and the Ishmaelites; of Moab, and the Hagarenes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 7, E'Gebal, and Ammon, and Amalek; the Philistines with the inhabitants of Tyre;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 8, E'Assur also is joined with them: they have holpen the children of Lot. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 9, E'Do unto them as unto the Midianites; as to Sisera, as to Jabin, at the brook of Kison:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 10, E'Which perished at Endor: they became as dung for the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 11, E'Make their nobles like Oreb, and like Zeeb: yea, all their princes as Zebah, and as Zalmunna:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 12, E'Who said, Let us take to ourselves the houses of God in possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 13, E'O my God, make them like a wheel; as the stubble before the wind.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 14, E'As the fire burneth a wood, and as the flame setteth the mountains on fire;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 15, E'So persecute them with thy tempest, and make them afraid with thy storm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 16, E'Fill their faces with shame; that they may seek thy name, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 17, E'Let them be confounded and troubled for ever; yea, let them be put to shame, and perish:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 83, 18, E'That men may know that thou, whose name alone is JEHOVAH, art the most high over all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 1, E'How amiable are thy tabernacles, O LORD of hosts!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 2, E'My soul longeth, yea, even fainteth for the courts of the LORD: my heart and my flesh crieth out for the living God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 3, E'Yea, the sparrow hath found an house, and the swallow a nest for herself, where she may lay her young, even thine altars, O LORD of hosts, my King, and my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 4, E'Blessed are they that dwell in thy house: they will be still praising thee. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 5, E'Blessed is the man whose strength is in thee; in whose heart are the ways of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 6, E'Who passing through the valley of Baca make it a well; the rain also filleth the pools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 7, E'They go from strength to strength, every one of them in Zion appeareth before God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 8, E'O LORD God of hosts, hear my prayer: give ear, O God of Jacob. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 9, E'Behold, O God our shield, and look upon the face of thine anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 10, E'For a day in thy courts is better than a thousand. I had rather be a doorkeeper in the house of my God, than to dwell in the tents of wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 11, E'For the LORD God is a sun and shield: the LORD will give grace and glory: no good thing will he withhold from them that walk uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 84, 12, E'O LORD of hosts, blessed is the man that trusteth in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 1, E'Lord, thou hast been favourable unto thy land: thou hast brought back the captivity of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 2, E'Thou hast forgiven the iniquity of thy people, thou hast covered all their sin. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 3, E'Thou hast taken away all thy wrath: thou hast turned thyself from the fierceness of thine anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 4, E'Turn us, O God of our salvation, and cause thine anger toward us to cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 5, E'Wilt thou be angry with us for ever? wilt thou draw out thine anger to all generations?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 6, E'Wilt thou not revive us again: that thy people may rejoice in thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 7, E'Shew us thy mercy, O LORD, and grant us thy salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 8, E'I will hear what God the LORD will speak: for he will speak peace unto his people, and to his saints: but let them not turn again to folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 9, E'Surely his salvation is nigh them that fear him; that glory may dwell in our land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 10, E'Mercy and truth are met together; righteousness and peace have kissed each other.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 11, E'Truth shall spring out of the earth; and righteousness shall look down from heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 12, E'Yea, the LORD shall give that which is good; and our land shall yield her increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 85, 13, E'Righteousness shall go before him; and shall set us in the way of his steps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 1, E'Bow down thine ear, O LORD, hear me: for I am poor and needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 2, E'Preserve my soul; for I am holy: O thou my God, save thy servant that trusteth in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 3, E'Be merciful unto me, O Lord: for I cry unto thee daily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 4, E'Rejoice the soul of thy servant: for unto thee, O Lord, do I lift up my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 5, E'For thou, Lord, art good, and ready to forgive; and plenteous in mercy unto all them that call upon thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 6, E'Give ear, O LORD, unto my prayer; and attend to the voice of my supplications.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 7, E'In the day of my trouble I will call upon thee: for thou wilt answer me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 8, E'Among the gods there is none like unto thee, O Lord; neither are there any works like unto thy works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 9, E'All nations whom thou hast made shall come and worship before thee, O Lord; and shall glorify thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 10, E'For thou art great, and doest wondrous things: thou art God alone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 11, E'Teach me thy way, O LORD; I will walk in thy truth: unite my heart to fear thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 12, E'I will praise thee, O Lord my God, with all my heart: and I will glorify thy name for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 13, E'For great is thy mercy toward me: and thou hast delivered my soul from the lowest hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 14, E'O God, the proud are risen against me, and the assemblies of violent men have sought after my soul; and have not set thee before them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 15, E'But thou, O Lord, art a God full of compassion, and gracious, long suffering, and plenteous in mercy and truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 16, E'O turn unto me, and have mercy upon me; give thy strength unto thy servant, and save the son of thine handmaid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 86, 17, E'Shew me a token for good; that they which hate me may see it, and be ashamed: because thou, LORD, hast holpen me, and comforted me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 1, E'His foundation is in the holy mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 2, E'The LORD loveth the gates of Zion more than all the dwellings of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 3, E'Glorious things are spoken of thee, O city of God. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 4, E'I will make mention of Rahab and Babylon to them that know me: behold Philistia, and Tyre, with Ethiopia; this man was born there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 5, E'And of Zion it shall be said, This and that man was born in her: and the highest himself shall establish her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 6, E'The LORD shall count, when he writeth up the people, that this man was born there. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 87, 7, E'As well the singers as the players on instruments shall be there: all my springs are in thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 1, E'O LORD God of my salvation, I have cried day and night before thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 2, E'Let my prayer come before thee: incline thine ear unto my cry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 3, E'For my soul is full of troubles: and my life draweth nigh unto the grave.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 4, E'I am counted with them that go down into the pit: I am as a man that hath no strength:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 5, E'Free among the dead, like the slain that lie in the grave, whom thou rememberest no more: and they are cut off from thy hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 6, E'Thou hast laid me in the lowest pit, in darkness, in the deeps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 7, E'Thy wrath lieth hard upon me, and thou hast afflicted me with all thy waves. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 8, E'Thou hast put away mine acquaintance far from me; thou hast made me an abomination unto them: I am shut up, and I cannot come forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 9, E'Mine eye mourneth by reason of affliction: LORD, I have called daily upon thee, I have stretched out my hands unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 10, E'Wilt thou shew wonders to the dead? shall the dead arise and praise thee? Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 11, E'Shall thy lovingkindness be declared in the grave? or thy faithfulness in destruction?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 12, E'Shall thy wonders be known in the dark? and thy righteousness in the land of forgetfulness?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 13, E'But unto thee have I cried, O LORD; and in the morning shall my prayer prevent thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 14, E'LORD, why castest thou off my soul? why hidest thou thy face from me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 15, E'I am afflicted and ready to die from my youth up: while I suffer thy terrors I am distracted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 16, E'Thy fierce wrath goeth over me; thy terrors have cut me off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 17, E'They came round about me daily like water; they compassed me about together.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 88, 18, E'Lover and friend hast thou put far from me, and mine acquaintance into darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 1, E'I will sing of the mercies of the LORD for ever: with my mouth will I make known thy faithfulness to all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 2, E'For I have said, Mercy shall be built up for ever: thy faithfulness shalt thou establish in the very heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 3, E'I have made a covenant with my chosen, I have sworn unto David my servant,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 4, E'Thy seed will I establish for ever, and build up thy throne to all generations. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 5, E'And the heavens shall praise thy wonders, O LORD: thy faithfulness also in the congregation of the saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 6, E'For who in the heaven can be compared unto the LORD? who among the sons of the mighty can be likened unto the LORD?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 7, E'God is greatly to be feared in the assembly of the saints, and to be had in reverence of all them that are about him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 8, E'O LORD God of hosts, who is a strong LORD like unto thee? or to thy faithfulness round about thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 9, E'Thou rulest the raging of the sea: when the waves thereof arise, thou stillest them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 10, E'Thou hast broken Rahab in pieces, as one that is slain; thou hast scattered thine enemies with thy strong arm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 11, E'The heavens are thine, the earth also is thine: as for the world and the fulness thereof, thou hast founded them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 12, E'The north and the south thou hast created them: Tabor and Hermon shall rejoice in thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 13, E'Thou hast a mighty arm: strong is thy hand, and high is thy right hand.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 14, E'Justice and judgment are the habitation of thy throne: mercy and truth shall go before thy face.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 15, E'Blessed is the people that know the joyful sound: they shall walk, O LORD, in the light of thy countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 16, E'In thy name shall they rejoice all the day: and in thy righteousness shall they be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 17, E'For thou art the glory of their strength: and in thy favour our horn shall be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 18, E'For the LORD is our defence; and the Holy One of Israel is our king.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 19, E'Then thou spakest in vision to thy holy one, and saidst, I have laid help upon one that is mighty; I have exalted one chosen out of the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 20, E'I have found David my servant; with my holy oil have I anointed him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 21, E'With whom my hand shall be established: mine arm also shall strengthen him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 22, E'The enemy shall not exact upon him; nor the son of wickedness afflict him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 23, E'And I will beat down his foes before his face, and plague them that hate him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 24, E'But my faithfulness and my mercy shall be with him: and in my name shall his horn be exalted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 25, E'I will set his hand also in the sea, and his right hand in the rivers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 26, E'He shall cry unto me, Thou art my father, my God, and the rock of my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 27, E'Also I will make him my firstborn, higher than the kings of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 28, E'My mercy will I keep for him for evermore, and my covenant shall stand fast with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 29, E'His seed also will I make to endure for ever, and his throne as the days of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 30, E'If his children forsake my law, and walk not in my judgments;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 31, E'If they break my statutes, and keep not my commandments;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 32, E'Then will I visit their transgression with the rod, and their iniquity with stripes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 33, E'Nevertheless my lovingkindness will I not utterly take from him, nor suffer my faithfulness to fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 34, E'My covenant will I not break, nor alter the thing that is gone out of my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 35, E'Once have I sworn by my holiness that I will not lie unto David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 36, E'His seed shall endure for ever, and his throne as the sun before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 37, E'It shall be established for ever as the moon, and as a faithful witness in heaven. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 38, E'But thou hast cast off and abhorred, thou hast been wroth with thine anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 39, E'Thou hast made void the covenant of thy servant: thou hast profaned his crown by casting it to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 40, E'Thou hast broken down all his hedges; thou hast brought his strong holds to ruin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 41, E'All that pass by the way spoil him: he is a reproach to his neighbours.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 42, E'Thou hast set up the right hand of his adversaries; thou hast made all his enemies to rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 43, E'Thou hast also turned the edge of his sword, and hast not made him to stand in the battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 44, E'Thou hast made his glory to cease, and cast his throne down to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 45, E'The days of his youth hast thou shortened: thou hast covered him with shame. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 46, E'How long, LORD? wilt thou hide thyself for ever? shall thy wrath burn like fire?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 47, E'Remember how short my time is: wherefore hast thou made all men in vain?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 48, E'What man is he that liveth, and shall not see death? shall he deliver his soul from the hand of the grave? Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 49, E'Lord, where are thy former lovingkindnesses, which thou swarest unto David in thy truth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 50, E'Remember, Lord, the reproach of thy servants; how I do bear in my bosom the reproach of all the mighty people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 51, E'Wherewith thine enemies have reproached, O LORD; wherewith they have reproached the footsteps of thine anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 89, 52, E'Blessed be the LORD for evermore. Amen, and Amen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 1, E'Lord, thou hast been our dwelling place in all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 2, E'Before the mountains were brought forth, or ever thou hadst formed the earth and the world, even from everlasting to everlasting, thou art God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 3, E'Thou turnest man to destruction; and sayest, Return, ye children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 4, E'For a thousand years in thy sight are but as yesterday when it is past, and as a watch in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 5, E'Thou carriest them away as with a flood; they are as a sleep: in the morning they are like grass which groweth up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 6, E'In the morning it flourisheth, and groweth up; in the evening it is cut down, and withereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 7, E'For we are consumed by thine anger, and by thy wrath are we troubled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 8, E'Thou hast set our iniquities before thee, our secret sins in the light of thy countenance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 9, E'For all our days are passed away in thy wrath: we spend our years as a tale that is told.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 10, E'The days of our years are threescore years and ten; and if by reason of strength they be fourscore years, yet is their strength labour and sorrow; for it is soon cut off, and we fly away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 11, E'Who knoweth the power of thine anger? even according to thy fear, so is thy wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 12, E'So teach us to number our days, that we may apply our hearts unto wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 13, E'Return, O LORD, how long? and let it repent thee concerning thy servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 14, E'O satisfy us early with thy mercy; that we may rejoice and be glad all our days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 15, E'Make us glad according to the days wherein thou hast afflicted us, and the years wherein we have seen evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 16, E'Let thy work appear unto thy servants, and thy glory unto their children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 90, 17, E'And let the beauty of the LORD our God be upon us: and establish thou the work of our hands upon us; yea, the work of our hands establish thou it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 1, E'He that dwelleth in the secret place of the most High shall abide under the shadow of the Almighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 2, E'I will say of the LORD, He is my refuge and my fortress: my God; in him will I trust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 3, E'Surely he shall deliver thee from the snare of the fowler, and from the noisome pestilence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 4, E'He shall cover thee with his feathers, and under his wings shalt thou trust: his truth shall be thy shield and buckler.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 5, E'Thou shalt not be afraid for the terror by night; nor for the arrow that flieth by day;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 6, E'Nor for the pestilence that walketh in darkness; nor for the destruction that wasteth at noonday.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 7, E'A thousand shall fall at thy side, and ten thousand at thy right hand; but it shall not come nigh thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 8, E'Only with thine eyes shalt thou behold and see the reward of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 9, E'Because thou hast made the LORD, which is my refuge, even the most High, thy habitation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 10, E'There shall no evil befall thee, neither shall any plague come nigh thy dwelling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 11, E'For he shall give his angels charge over thee, to keep thee in all thy ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 12, E'They shall bear thee up in their hands, lest thou dash thy foot against a stone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 13, E'Thou shalt tread upon the lion and adder: the young lion and the dragon shalt thou trample under feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 14, E'Because he hath set his love upon me, therefore will I deliver him: I will set him on high, because he hath known my name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 15, E'He shall call upon me, and I will answer him: I will be with him in trouble; I will deliver him, and honour him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 91, 16, E'With long life will I satisfy him, and shew him my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 1, E'IT IS A GOOD THING TO GIVE THANKS UNTO THE LORD, AND TO SING PRAISES UNTO THY NAME, O MOST HIGH:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 2, E'To shew forth thy lovingkindness in the morning, and thy faithfulness every night,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 3, E'Upon an instrument of ten strings, and upon the psaltery; upon the harp with a solemn sound.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 4, E'For thou, LORD, hast made me glad through thy work: I will triumph in the works of thy hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 5, E'O LORD, how great are thy works! and thy thoughts are very deep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 6, E'A brutish man knoweth not; neither doth a fool understand this.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 7, E'When the wicked spring as the grass, and when all the workers of iniquity do flourish; it is that they shall be destroyed for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 8, E'But thou, LORD, art most high for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 9, E'For, lo, thine enemies, O LORD, for, lo, thine enemies shall perish; all the workers of iniquity shall be scattered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 10, E'But my horn shalt thou exalt like the horn of an unicorn: I shall be anointed with fresh oil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 11, E'Mine eye also shall see my desire on mine enemies, and mine ears shall hear my desire of the wicked that rise up against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 12, E'The righteous shall flourish like the palm tree: he shall grow like a cedar in Lebanon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 13, E'Those that be planted in the house of the LORD shall flourish in the courts of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 14, E'They shall still bring forth fruit in old age; they shall be fat and flourishing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 92, 15, E'To shew that the LORD is upright: he is my rock, and there is no unrighteousness in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 93, 1, E'The LORD reigneth, he is clothed with majesty; the LORD is clothed with strength, wherewith he hath girded himself: the world also is stablished, that it cannot be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 93, 2, E'Thy throne is established of old: thou art from everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 93, 3, E'The floods have lifted up, O LORD, the floods have lifted up their voice; the floods lift up their waves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 93, 4, E'The LORD on high is mightier than the noise of many waters, yea, than the mighty waves of the sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 93, 5, E'Thy testimonies are very sure: holiness becometh thine house, O LORD, for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 1, E'O Lord God, to whom vengeance belongeth; O God, to whom vengeance belongeth, shew thyself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 2, E'Lift up thyself, thou judge of the earth: render a reward to the proud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 3, E'LORD, how long shall the wicked, how long shall the wicked triumph?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 4, E'How long shall they utter and speak hard things? and all the workers of iniquity boast themselves?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 5, E'They break in pieces thy people, O LORD, and afflict thine heritage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 6, E'They slay the widow and the stranger, and murder the fatherless.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 7, E'Yet they say, The LORD shall not see, neither shall the God of Jacob regard it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 8, E'Understand, ye brutish among the people: and ye fools, when will ye be wise?')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 9, E'He that planted the ear, shall he not hear? he that formed the eye, shall he not see?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 10, E'He that chastiseth the heathen, shall not he correct? he that teacheth man knowledge, shall not he know?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 11, E'The LORD knoweth the thoughts of man, that they are vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 12, E'Blessed is the man whom thou chastenest, O LORD, and teachest him out of thy law;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 13, E'That thou mayest give him rest from the days of adversity, until the pit be digged for the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 14, E'For the LORD will not cast off his people, neither will he forsake his inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 15, E'But judgment shall return unto righteousness: and all the upright in heart shall follow it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 16, E'Who will rise up for me against the evildoers? or who will stand up for me against the workers of iniquity?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 17, E'Unless the LORD had been my help, my soul had almost dwelt in silence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 18, E'When I said, My foot slippeth; thy mercy, O LORD, held me up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 19, E'In the multitude of my thoughts within me thy comforts delight my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 20, E'Shall the throne of iniquity have fellowship with thee, which frameth mischief by a law?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 21, E'They gather themselves together against the soul of the righteous, and condemn the innocent blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 22, E'But the LORD is my defence; and my God is the rock of my refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 94, 23, E'And he shall bring upon them their own iniquity, and shall cut them off in their own wickedness; yea, the LORD our God shall cut them off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 1, E'O come, let us sing unto the LORD: let us make a joyful noise to the rock of our salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 2, E'Let us come before his presence with thanksgiving, and make a joyful noise unto him with psalms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 3, E'For the LORD is a great God, and a great King above all gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 4, E'In his hand are the deep places of the earth: the strength of the hills is his also.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 5, E'The sea is his, and he made it: and his hands formed the dry land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 6, E'O come, let us worship and bow down: let us kneel before the LORD our maker.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 7, E'For he is our God; and we are the people of his pasture, and the sheep of his hand. To day if ye will hear his voice,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 8, E'Harden not your heart, as in the provocation, and as in the day of temptation in the wilderness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 9, E'When your fathers tempted me, proved me, and saw my work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 10, E'Forty years long was I grieved with this generation, and said, It is a people that do err in their heart, and they have not known my ways:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 95, 11, E'Unto whom I sware in my wrath that they should not enter into my rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 1, E'O sing unto the LORD a new song: sing unto the LORD, all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 2, E'Sing unto the LORD, bless his name; shew forth his salvation from day to day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 3, E'Declare his glory among the heathen, his wonders among all people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 4, E'For the LORD is great, and greatly to be praised: he is to be feared above all gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 5, E'For all the gods of the nations are idols: but the LORD made the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 6, E'Honour and majesty are before him: strength and beauty are in his sanctuary.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 7, E'Give unto the LORD, O ye kindreds of the people, give unto the LORD glory and strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 8, E'Give unto the LORD the glory due unto his name: bring an offering, and come into his courts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 9, E'O worship the LORD in the beauty of holiness: fear before him, all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 10, E'Say among the heathen that the LORD reigneth: the world also shall be established that it shall not be moved: he shall judge the people righteously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 11, E'Let the heavens rejoice, and let the earth be glad; let the sea roar, and the fulness thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 12, E'Let the field be joyful, and all that is therein: then shall all the trees of the wood rejoice'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 96, 13, E'Before the LORD: for he cometh, for he cometh to judge the earth: he shall judge the world with righteousness, and the people with his truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 1, E'The LORD reigneth; let the earth rejoice; let the multitude of isles be glad thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 2, E'Clouds and darkness are round about him: righteousness and judgment are the habitation of his throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 3, E'A fire goeth before him, and burneth up his enemies round about.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 4, E'His lightnings enlightened the world: the earth saw, and trembled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 5, E'The hills melted like wax at the presence of the LORD, at the presence of the Lord of the whole earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 6, E'The heavens declare his righteousness, and all the people see his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 7, E'Confounded be all they that serve graven images, that boast themselves of idols: worship him, all ye gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 8, E'Zion heard, and was glad; and the daughters of Judah rejoiced because of thy judgments, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 9, E'For thou, LORD, art high above all the earth: thou art exalted far above all gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 10, E'Ye that love the LORD, hate evil: he preserveth the souls of his saints; he delivereth them out of the hand of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 11, E'Light is sown for the righteous, and gladness for the upright in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 97, 12, E'Rejoice in the LORD, ye righteous; and give thanks at the remembrance of his holiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 1, E'O sing unto the LORD a new song; for he hath done marvellous things: his right hand, and his holy arm, hath gotten him the victory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 2, E'The LORD hath made known his salvation: his righteousness hath he openly shewed in the sight of the heathen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 3, E'He hath remembered his mercy and his truth toward the house of Israel: all the ends of the earth have seen the salvation of our God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 4, E'Make a joyful noise unto the LORD, all the earth: make a loud noise, and rejoice, and sing praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 5, E'Sing unto the LORD with the harp; with the harp, and the voice of a psalm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 6, E'With trumpets and sound of cornet make a joyful noise before the LORD, the King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 7, E'Let the sea roar, and the fulness thereof; the world, and they that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 8, E'Let the floods clap their hands: let the hills be joyful together'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 98, 9, E'Before the LORD; for he cometh to judge the earth: with righteousness shall he judge the world, and the people with equity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 1, E'The LORD reigneth; let the people tremble: he sitteth between the cherubims; let the earth be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 2, E'The LORD is great in Zion; and he is high above all the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 3, E'Let them praise thy great and terrible name; for it is holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 4, E'The kingâ€™s strength also loveth judgment; thou dost establish equity, thou executest judgment and righteousness in Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 5, E'Exalt ye the LORD our God, and worship at his footstool; for he is holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 6, E'Moses and Aaron among his priests, and Samuel among them that call upon his name; they called upon the LORD, and he answered them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 7, E'He spake unto them in the cloudy pillar: they kept his testimonies, and the ordinance that he gave them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 8, E'Thou answeredst them, O LORD our God: thou wast a God that forgavest them, though thou tookest vengeance of their inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 99, 9, E'Exalt the LORD our God, and worship at his holy hill; for the LORD our God is holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 100, 1, E'Make a joyful noise unto the LORD, all ye lands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 100, 2, E'Serve the LORD with gladness: come before his presence with singing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 100, 3, E'Know ye that the LORD he is God: it is he that hath made us, and not we ourselves; we are his people, and the sheep of his pasture.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 100, 4, E'Enter into his gates with thanksgiving, and into his courts with praise: be thankful unto him, and bless his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 100, 5, E'For the LORD is good; his mercy is everlasting; and his truth endureth to all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 1, E'I will sing of mercy and judgment: unto thee, O LORD, will I sing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 2, E'I will behave myself wisely in a perfect way. O when wilt thou come unto me? I will walk within my house with a perfect heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 3, E'I will set no wicked thing before mine eyes: I hate the work of them that turn aside; it shall not cleave to me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 4, E'A froward heart shall depart from me: I will not know a wicked person.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 5, E'Whoso privily slandereth his neighbour, him will I cut off: him that hath an high look and a proud heart will not I suffer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 6, E'Mine eyes shall be upon the faithful of the land, that they may dwell with me: he that walketh in a perfect way, he shall serve me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 7, E'He that worketh deceit shall not dwell within my house: he that telleth lies shall not tarry in my sight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 101, 8, E'I will early destroy all the wicked of the land; that I may cut off all wicked doers from the city of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 1, E'Hear my prayer, O LORD, and let my cry come unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 2, E'Hide not thy face from me in the day when I am in trouble; incline thine ear unto me: in the day when I call answer me speedily.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 3, E'For my days are consumed like smoke, and my bones are burned as an hearth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 4, E'My heart is smitten, and withered like grass; so that I forget to eat my bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 5, E'By reason of the voice of my groaning my bones cleave to my skin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 6, E'I am like a pelican of the wilderness: I am like an owl of the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 7, E'I watch, and am as a sparrow alone upon the house top.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 8, E'Mine enemies reproach me all the day; and they that are mad against me are sworn against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 9, E'For I have eaten ashes like bread, and mingled my drink with weeping,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 10, E'Because of thine indignation and thy wrath: for thou hast lifted me up, and cast me down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 11, E'My days are like a shadow that declineth; and I am withered like grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 12, E'But thou, O LORD, shalt endure for ever; and thy remembrance unto all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 13, E'Thou shalt arise, and have mercy upon Zion: for the time to favour her, yea, the set time, is come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 14, E'For thy servants take pleasure in her stones, and favour the dust thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 15, E'So the heathen shall fear the name of the LORD, and all the kings of the earth thy glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 16, E'When the LORD shall build up Zion, he shall appear in his glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 17, E'He will regard the prayer of the destitute, and not despise their prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 18, E'This shall be written for the generation to come: and the people which shall be created shall praise the LORD.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 19, E'For he hath looked down from the height of his sanctuary; from heaven did the LORD behold the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 20, E'To hear the groaning of the prisoner; to loose those that are appointed to death;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 21, E'To declare the name of the LORD in Zion, and his praise in Jerusalem;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 22, E'When the people are gathered together, and the kingdoms, to serve the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 23, E'He weakened my strength in the way; he shortened my days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 24, E'I said, O my God, take me not away in the midst of my days: thy years are throughout all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 25, E'Of old hast thou laid the foundation of the earth: and the heavens are the work of thy hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 26, E'They shall perish, but thou shalt endure: yea, all of them shall wax old like a garment; as a vesture shalt thou change them, and they shall be changed:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 27, E'But thou art the same, and thy years shall have no end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 102, 28, E'The children of thy servants shall continue, and their seed shall be established before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 1, E'Bless the LORD, O my soul: and all that is within me, bless his holy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 2, E'Bless the LORD, O my soul, and forget not all his benefits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 3, E'Who forgiveth all thine iniquities; who healeth all thy diseases;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 4, E'Who redeemeth thy life from destruction; who crowneth thee with lovingkindness and tender mercies;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 5, E'Who satisfieth thy mouth with good things; so that thy youth is renewed like the eagleâ€™s.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 6, E'The LORD executeth righteousness and judgment for all that are oppressed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 7, E'He made known his ways unto Moses, his acts unto the children of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 8, E'The LORD is merciful and gracious, slow to anger, and plenteous in mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 9, E'He will not always chide: neither will he keep his anger for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 10, E'He hath not dealt with us after our sins; nor rewarded us according to our iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 11, E'For as the heaven is high above the earth, so great is his mercy toward them that fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 12, E'As far as the east is from the west, so far hath he removed our transgressions from us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 13, E'Like as a father pitieth his children, so the LORD pitieth them that fear him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 14, E'For he knoweth our frame; he remembereth that we are dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 15, E'As for man, his days are as grass: as a flower of the field, so he flourisheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 16, E'For the wind passeth over it, and it is gone; and the place thereof shall know it no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 17, E'But the mercy of the LORD is from everlasting to everlasting upon them that fear him, and his righteousness unto childrenâ€™s children;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 18, E'To such as keep his covenant, and to those that remember his commandments to do them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 19, E'The LORD hath prepared his throne in the heavens; and his kingdom ruleth over all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 20, E'Bless the LORD, ye his angels, that excel in strength, that do his commandments, hearkening unto the voice of his word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 21, E'Bless ye the LORD, all ye his hosts; ye ministers of his, that do his pleasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 103, 22, E'Bless the LORD, all his works in all places of his dominion: bless the LORD, O my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 1, E'Bless the LORD, O my soul. O LORD my God, thou art very great; thou art clothed with honour and majesty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 2, E'Who coverest thyself with light as with a garment: who stretchest out the heavens like a curtain:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 3, E'Who layeth the beams of his chambers in the waters: who maketh the clouds his chariot: who walketh upon the wings of the wind:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 4, E'Who maketh his angels spirits; his ministers a flaming fire:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 5, E'Who laid the foundations of the earth, that it should not be removed for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 6, E'Thou coveredst it with the deep as with a garment: the waters stood above the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 7, E'At thy rebuke they fled; at the voice of thy thunder they hasted away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 8, E'They go up by the mountains; they go down by the valleys unto the place which thou hast founded for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 9, E'Thou hast set a bound that they may not pass over; that they turn not again to cover the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 10, E'He sendeth the springs into the valleys, which run among the hills.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 11, E'They give drink to every beast of the field: the wild asses quench their thirst.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 12, E'By them shall the fowls of the heaven have their habitation, which sing among the branches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 13, E'He watereth the hills from his chambers: the earth is satisfied with the fruit of thy works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 14, E'He causeth the grass to grow for the cattle, and herb for the service of man: that he may bring forth food out of the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 15, E'And wine that maketh glad the heart of man, and oil to make his face to shine, and bread which strengtheneth manâ€™s heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 16, E'The trees of the LORD are full of sap; the cedars of Lebanon, which he hath planted;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 17, E'Where the birds make their nests: as for the stork, the fir trees are her house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 18, E'The high hills are a refuge for the wild goats; and the rocks for the conies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 19, E'He appointed the moon for seasons: the sun knoweth his going down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 20, E'Thou makest darkness, and it is night: wherein all the beasts of the forest do creep forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 21, E'The young lions roar after their prey, and seek their meat from God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 22, E'The sun ariseth, they gather themselves together, and lay them down in their dens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 23, E'Man goeth forth unto his work and to his labour until the evening.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 24, E'O LORD, how manifold are thy works! in wisdom hast thou made them all: the earth is full of thy riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 25, E'So is this great and wide sea, wherein are things creeping innumerable, both small and great beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 26, E'There go the ships: there is that leviathan, whom thou hast made to play therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 27, E'These wait all upon thee; that thou mayest give them their meat in due season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 28, E'That thou givest them they gather: thou openest thine hand, they are filled with good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 29, E'Thou hidest thy face, they are troubled: thou takest away their breath, they die, and return to their dust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 30, E'Thou sendest forth thy spirit, they are created: and thou renewest the face of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 31, E'The glory of the LORD shall endure for ever: the LORD shall rejoice in his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 32, E'He looketh on the earth, and it trembleth: he toucheth the hills, and they smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 33, E'I will sing unto the LORD as long as I live: I will sing praise to my God while I have my being.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 34, E'My meditation of him shall be sweet: I will be glad in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 104, 35, E'Let the sinners be consumed out of the earth, and let the wicked be no more. Bless thou the LORD, O my soul. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 1, E'O give thanks unto the LORD; call upon his name: make known his deeds among the people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 2, E'Sing unto him, sing psalms unto him: talk ye of all his wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 3, E'Glory ye in his holy name: let the heart of them rejoice that seek the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 4, E'Seek the LORD, and his strength: seek his face evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 5, E'Remember his marvellous works that he hath done; his wonders, and the judgments of his mouth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 6, E'O ye seed of Abraham his servant, ye children of Jacob his chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 7, E'He is the LORD our God: his judgments are in all the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 8, E'He hath remembered his covenant for ever, the word which he commanded to a thousand generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 9, E'Which covenant he made with Abraham, and his oath unto Isaac;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 10, E'And confirmed the same unto Jacob for a law, and to Israel for an everlasting covenant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 11, E'Saying, Unto thee will I give the land of Canaan, the lot of your inheritance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 12, E'When they were but a few men in number; yea, very few, and strangers in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 13, E'When they went from one nation to another, from one kingdom to another people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 14, E'He suffered no man to do them wrong: yea, he reproved kings for their sakes;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 15, E'Saying, Touch not mine anointed, and do my prophets no harm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 16, E'Moreover he called for a famine upon the land: he brake the whole staff of bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 17, E'He sent a man before them, even Joseph, who was sold for a servant:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 18, E'Whose feet they hurt with fetters: he was laid in iron:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 19, E'Until the time that his word came: the word of the LORD tried him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 20, E'The king sent and loosed him; even the ruler of the people, and let him go free.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 21, E'He made him lord of his house, and ruler of all his substance:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 22, E'To bind his princes at his pleasure; and teach his senators wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 23, E'Israel also came into Egypt; and Jacob sojourned in the land of Ham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 24, E'And he increased his people greatly; and made them stronger than their enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 25, E'He turned their heart to hate his people, to deal subtilly with his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 26, E'He sent Moses his servant; and Aaron whom he had chosen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 27, E'They shewed his signs among them, and wonders in the land of Ham.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 28, E'He sent darkness, and made it dark; and they rebelled not against his word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 29, E'He turned their waters into blood, and slew their fish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 30, E'Their land brought forth frogs in abundance, in the chambers of their kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 31, E'He spake, and there came divers sorts of flies, and lice in all their coasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 32, E'He gave them hail for rain, and flaming fire in their land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 33, E'He smote their vines also and their fig trees; and brake the trees of their coasts.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 34, E'He spake, and the locusts came, and caterpillers, and that without number,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 35, E'And did eat up all the herbs in their land, and devoured the fruit of their ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 36, E'He smote also all the firstborn in their land, the chief of all their strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 37, E'He brought them forth also with silver and gold: and there was not one feeble person among their tribes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 38, E'Egypt was glad when they departed: for the fear of them fell upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 39, E'He spread a cloud for a covering; and fire to give light in the night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 40, E'The people asked, and he brought quails, and satisfied them with the bread of heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 41, E'He opened the rock, and the waters gushed out; they ran in the dry places like a river.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 42, E'For he remembered his holy promise, and Abraham his servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 43, E'And he brought forth his people with joy, and his chosen with gladness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 44, E'And gave them the lands of the heathen: and they inherited the labour of the people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 105, 45, E'That they might observe his statutes, and keep his laws. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 1, E'Praise ye the LORD. O give thanks unto the LORD; for he is good: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 2, E'Who can utter the mighty acts of the LORD? who can shew forth all his praise?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 3, E'Blessed are they that keep judgment, and he that doeth righteousness at all times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 4, E'Remember me, O LORD, with the favour that thou bearest unto thy people: O visit me with thy salvation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 5, E'That I may see the good of thy chosen, that I may rejoice in the gladness of thy nation, that I may glory with thine inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 6, E'We have sinned with our fathers, we have committed iniquity, we have done wickedly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 7, E'Our fathers understood not thy wonders in Egypt; they remembered not the multitude of thy mercies; but provoked him at the sea, even at the Red sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 8, E'Nevertheless he saved them for his nameâ€™s sake, that he might make his mighty power to be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 9, E'He rebuked the Red sea also, and it was dried up: so he led them through the depths, as through the wilderness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 10, E'And he saved them from the hand of him that hated them, and redeemed them from the hand of the enemy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 11, E'And the waters covered their enemies: there was not one of them left.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 12, E'Then believed they his words; they sang his praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 13, E'They soon forgat his works; they waited not for his counsel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 14, E'But lusted exceedingly in the wilderness, and tempted God in the desert.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 15, E'And he gave them their request; but sent leanness into their soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 16, E'They envied Moses also in the camp, and Aaron the saint of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 17, E'The earth opened and swallowed up Dathan, and covered the company of Abiram.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 18, E'And a fire was kindled in their company; the flame burned up the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 19, E'They made a calf in Horeb, and worshipped the molten image.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 20, E'Thus they changed their glory into the similitude of an ox that eateth grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 21, E'They forgat God their saviour, which had done great things in Egypt;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 22, E'Wondrous works in the land of Ham, and terrible things by the Red sea.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 23, E'Therefore he said that he would destroy them, had not Moses his chosen stood before him in the breach, to turn away his wrath, lest he should destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 24, E'Yea, they despised the pleasant land, they believed not his word:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 25, E'But murmured in their tents, and hearkened not unto the voice of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 26, E'Therefore he lifted up his hand against them, to overthrow them in the wilderness:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 27, E'To overthrow their seed also among the nations, and to scatter them in the lands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 28, E'They joined themselves also unto Baalpeor, and ate the sacrifices of the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 29, E'Thus they provoked him to anger with their inventions: and the plague brake in upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 30, E'Then stood up Phinehas, and executed judgment: and so the plague was stayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 31, E'And that was counted unto him for righteousness unto all generations for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 32, E'They angered him also at the waters of strife, so that it went ill with Moses for their sakes:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 33, E'Because they provoked his spirit, so that he spake unadvisedly with his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 34, E'They did not destroy the nations, concerning whom the LORD commanded them:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 35, E'But were mingled among the heathen, and learned their works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 36, E'And they served their idols: which were a snare unto them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 37, E'Yea, they sacrificed their sons and their daughters unto devils,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 38, E'And shed innocent blood, even the blood of their sons and of their daughters, whom they sacrificed unto the idols of Canaan: and the land was polluted with blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 39, E'Thus were they defiled with their own works, and went a whoring with their own inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 40, E'Therefore was the wrath of the LORD kindled against his people, insomuch that he abhorred his own inheritance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 41, E'And he gave them into the hand of the heathen; and they that hated them ruled over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 42, E'Their enemies also oppressed them, and they were brought into subjection under their hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 43, E'Many times did he deliver them; but they provoked him with their counsel, and were brought low for their iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 44, E'Nevertheless he regarded their affliction, when he heard their cry:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 45, E'And he remembered for them his covenant, and repented according to the multitude of his mercies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 46, E'He made them also to be pitied of all those that carried them captives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 47, E'Save us, O LORD our God, and gather us from among the heathen, to give thanks unto thy holy name, and to triumph in thy praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 106, 48, E'Blessed be the LORD God of Israel from everlasting to everlasting: and let all the people say, Amen. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 1, E'O give thanks unto the LORD, for he is good: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 2, E'Let the redeemed of the LORD say so, whom he hath redeemed from the hand of the enemy;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 3, E'And gathered them out of the lands, from the east, and from the west, from the north, and from the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 4, E'They wandered in the wilderness in a solitary way; they found no city to dwell in.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 5, E'Hungry and thirsty, their soul fainted in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 6, E'Then they cried unto the LORD in their trouble, and he delivered them out of their distresses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 7, E'And he led them forth by the right way, that they might go to a city of habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 8, E'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 9, E'For he satisfieth the longing soul, and filleth the hungry soul with goodness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 10, E'Such as sit in darkness and in the shadow of death, being bound in affliction and iron;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 11, E'Because they rebelled against the words of God, and contemned the counsel of the most High:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 12, E'Therefore he brought down their heart with labour; they fell down, and there was none to help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 13, E'Then they cried unto the LORD in their trouble, and he saved them out of their distresses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 14, E'He brought them out of darkness and the shadow of death, and brake their bands in sunder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 15, E'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 16, E'For he hath broken the gates of brass, and cut the bars of iron in sunder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 17, E'Fools because of their transgression, and because of their iniquities, are afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 18, E'Their soul abhorreth all manner of meat; and they draw near unto the gates of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 19, E'Then they cry unto the LORD in their trouble, and he saveth them out of their distresses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 20, E'He sent his word, and healed them, and delivered them from their destructions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 21, E'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 22, E'And let them sacrifice the sacrifices of thanksgiving, and declare his works with rejoicing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 23, E'They that go down to the sea in ships, that do business in great waters;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 24, E'These see the works of the LORD, and his wonders in the deep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 25, E'For he commandeth, and raiseth the stormy wind, which lifteth up the waves thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 26, E'They mount up to the heaven, they go down again to the depths: their soul is melted because of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 27, E'They reel to and fro, and stagger like a drunken man, and are at their witâ€™s end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 28, E'Then they cry unto the LORD in their trouble, and he bringeth them out of their distresses.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 29, E'He maketh the storm a calm, so that the waves thereof are still.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 30, E'Then are they glad because they be quiet; so he bringeth them unto their desired haven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 31, E'Oh that men would praise the LORD for his goodness, and for his wonderful works to the children of men!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 32, E'Let them exalt him also in the congregation of the people, and praise him in the assembly of the elders.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 33, E'He turneth rivers into a wilderness, and the watersprings into dry ground;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 34, E'A fruitful land into barrenness, for the wickedness of them that dwell therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 35, E'He turneth the wilderness into a standing water, and dry ground into watersprings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 36, E'And there he maketh the hungry to dwell, that they may prepare a city for habitation;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 37, E'And sow the fields, and plant vineyards, which may yield fruits of increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 38, E'He blesseth them also, so that they are multiplied greatly; and suffereth not their cattle to decrease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 39, E'Again, they are minished and brought low through oppression, affliction, and sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 40, E'He poureth contempt upon princes, and causeth them to wander in the wilderness, where there is no way.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 41, E'Yet setteth he the poor on high from affliction, and maketh him families like a flock.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 42, E'The righteous shall see it, and rejoice: and all iniquity shall stop her mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 107, 43, E'Whoso is wise, and will observe these things, even they shall understand the lovingkindness of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 1, E'O God, my heart is fixed; I will sing and give praise, even with my glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 2, E'Awake, psaltery and harp: I myself will awake early.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 3, E'I will praise thee, O LORD, among the people: and I will sing praises unto thee among the nations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 4, E'For thy mercy is great above the heavens: and thy truth reacheth unto the clouds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 5, E'Be thou exalted, O God, above the heavens: and thy glory above all the earth;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 6, E'That thy beloved may be delivered: save with thy right hand, and answer me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 7, E'God hath spoken in his holiness; I will rejoice, I will divide Shechem, and mete out the valley of Succoth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 8, E'Gilead is mine; Manasseh is mine; Ephraim also is the strength of mine head; Judah is my lawgiver;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 9, E'Moab is my washpot; over Edom will I cast out my shoe; over Philistia will I triumph.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 10, E'Who will bring me into the strong city? who will lead me into Edom?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 11, E'Wilt not thou, O God, who hast cast us off? and wilt not thou, O God, go forth with our hosts?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 12, E'Give us help from trouble: for vain is the help of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 108, 13, E'Through God we shall do valiantly: for he it is that shall tread down our enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 1, E'Hold not thy peace, O God of my praise;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 2, E'For the mouth of the wicked and the mouth of the deceitful are opened against me: they have spoken against me with a lying tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 3, E'They compassed me about also with words of hatred; and fought against me without a cause.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 4, E'For my love they are my adversaries: but I give myself unto prayer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 5, E'And they have rewarded me evil for good, and hatred for my love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 6, E'Set thou a wicked man over him: and let Satan stand at his right hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 7, E'When he shall be judged, let him be condemned: and let his prayer become sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 8, E'Let his days be few; and let another take his office.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 9, E'Let his children be fatherless, and his wife a widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 10, E'Let his children be continually vagabonds, and beg: let them seek their bread also out of their desolate places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 11, E'Let the extortioner catch all that he hath; and let the strangers spoil his labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 12, E'Let there be none to extend mercy unto him: neither let there be any to favour his fatherless children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 13, E'Let his posterity be cut off; and in the generation following let their name be blotted out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 14, E'Let the iniquity of his fathers be remembered with the LORD; and let not the sin of his mother be blotted out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 15, E'Let them be before the LORD continually, that he may cut off the memory of them from the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 16, E'Because that he remembered not to shew mercy, but persecuted the poor and needy man, that he might even slay the broken in heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 17, E'As he loved cursing, so let it come unto him: as he delighted not in blessing, so let it be far from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 18, E'As he clothed himself with cursing like as with his garment, so let it come into his bowels like water, and like oil into his bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 19, E'Let it be unto him as the garment which covereth him, and for a girdle wherewith he is girded continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 20, E'Let this be the reward of mine adversaries from the LORD, and of them that speak evil against my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 21, E'But do thou for me, O GOD the Lord, for thy nameâ€™s sake: because thy mercy is good, deliver thou me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 22, E'For I am poor and needy, and my heart is wounded within me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 23, E'I am gone like the shadow when it declineth: I am tossed up and down as the locust.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 24, E'My knees are weak through fasting; and my flesh faileth of fatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 25, E'I became also a reproach unto them: when they looked upon me they shaked their heads.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 26, E'Help me, O LORD my God: O save me according to thy mercy:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 27, E'That they may know that this is thy hand; that thou, LORD, hast done it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 28, E'Let them curse, but bless thou: when they arise, let them be ashamed; but let thy servant rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 29, E'Let mine adversaries be clothed with shame, and let them cover themselves with their own confusion, as with a mantle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 30, E'I will greatly praise the LORD with my mouth; yea, I will praise him among the multitude.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 109, 31, E'For he shall stand at the right hand of the poor, to save him from those that condemn his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 1, E'The LORD said unto my Lord, Sit thou at my right hand, until I make thine enemies thy footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 2, E'The LORD shall send the rod of thy strength out of Zion: rule thou in the midst of thine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 3, E'Thy people shall be willing in the day of thy power, in the beauties of holiness from the womb of the morning: thou hast the dew of thy youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 4, E'The LORD hath sworn, and will not repent, Thou art a priest for ever after the order of Melchizedek.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 5, E'The Lord at thy right hand shall strike through kings in the day of his wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 6, E'He shall judge among the heathen, he shall fill the places with the dead bodies; he shall wound the heads over many countries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 110, 7, E'He shall drink of the brook in the way: therefore shall he lift up the head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 1, E'Praise ye the LORD. I will praise the LORD with my whole heart, in the assembly of the upright, and in the congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 2, E'The works of the LORD are great, sought out of all them that have pleasure therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 3, E'His work is honourable and glorious: and his righteousness endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 4, E'He hath made his wonderful works to be remembered: the LORD is gracious and full of compassion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 5, E'He hath given meat unto them that fear him: he will ever be mindful of his covenant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 6, E'He hath shewed his people the power of his works, that he may give them the heritage of the heathen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 7, E'The works of his hands are verity and judgment; all his commandments are sure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 8, E'They stand fast for ever and ever, and are done in truth and uprightness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 9, E'He sent redemption unto his people: he hath commanded his covenant for ever: holy and reverend is his name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 111, 10, E'The fear of the LORD is the beginning of wisdom: a good understanding have all they that do his commandments: his praise endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 1, E'Praise ye the LORD. Blessed is the man that feareth the LORD, that delighteth greatly in his commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 2, E'His seed shall be mighty upon earth: the generation of the upright shall be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 3, E'Wealth and riches shall be in his house: and his righteousness endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 4, E'Unto the upright there ariseth light in the darkness: he is gracious, and full of compassion, and righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 5, E'A good man sheweth favour, and lendeth: he will guide his affairs with discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 6, E'Surely he shall not be moved for ever: the righteous shall be in everlasting remembrance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 7, E'He shall not be afraid of evil tidings: his heart is fixed, trusting in the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 8, E'His heart is established, he shall not be afraid, until he see his desire upon his enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 9, E'He hath dispersed, he hath given to the poor; his righteousness endureth for ever; his horn shall be exalted with honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 112, 10, E'The wicked shall see it, and be grieved; he shall gnash with his teeth, and melt away: the desire of the wicked shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 1, E'Praise ye the LORD. Praise, O ye servants of the LORD, praise the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 2, E'Blessed be the name of the LORD from this time forth and for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 3, E'From the rising of the sun unto the going down of the same the LORDâ€™s name is to be praised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 4, E'The LORD is high above all nations, and his glory above the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 5, E'Who is like unto the LORD our God, who dwelleth on high,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 6, E'Who humbleth himself to behold the things that are in heaven, and in the earth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 7, E'He raiseth up the poor out of the dust, and lifteth the needy out of the dunghill;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 8, E'That he may set him with princes, even with the princes of his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 113, 9, E'He maketh the barren woman to keep house, and to be a joyful mother of children. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 1, E'When Israel went out of Egypt, the house of Jacob from a people of strange language;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 2, E'Judah was his sanctuary, and Israel his dominion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 3, E'The sea saw it, and fled: Jordan was driven back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 4, E'The mountains skipped like rams, and the little hills like lambs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 5, E'What ailed thee, O thou sea, that thou fleddest? thou Jordan, that thou wast driven back?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 6, E'Ye mountains, that ye skipped like rams; and ye little hills, like lambs?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 7, E'Tremble, thou earth, at the presence of the Lord, at the presence of the God of Jacob;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 114, 8, E'Which turned the rock into a standing water, the flint into a fountain of waters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 1, E'Not unto us, O LORD, not unto us, but unto thy name give glory, for thy mercy, and for thy truthâ€™s sake.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 2, E'Wherefore should the heathen say, Where is now their God?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 3, E'But our God is in the heavens: he hath done whatsoever he hath pleased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 4, E'Their idols are silver and gold, the work of menâ€™s hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 5, E'They have mouths, but they speak not: eyes have they, but they see not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 6, E'They have ears, but they hear not: noses have they, but they smell not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 7, E'They have hands, but they handle not: feet have they, but they walk not: neither speak they through their throat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 8, E'They that make them are like unto them; so is every one that trusteth in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 9, E'O Israel, trust thou in the LORD: he is their help and their shield.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 10, E'O house of Aaron, trust in the LORD: he is their help and their shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 11, E'Ye that fear the LORD, trust in the LORD: he is their help and their shield.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 12, E'The LORD hath been mindful of us: he will bless us; he will bless the house of Israel; he will bless the house of Aaron.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 13, E'He will bless them that fear the LORD, both small and great.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 14, E'The LORD shall increase you more and more, you and your children.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 15, E'Ye are blessed of the LORD which made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 16, E'The heaven, even the heavens, are the LORDâ€™s: but the earth hath he given to the children of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 17, E'The dead praise not the LORD, neither any that go down into silence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 115, 18, E'But we will bless the LORD from this time forth and for evermore. Praise the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 1, E'I love the LORD, because he hath heard my voice and my supplications.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 2, E'Because he hath inclined his ear unto me, therefore will I call upon him as long as I live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 3, E'The sorrows of death compassed me, and the pains of hell gat hold upon me: I found trouble and sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 4, E'Then called I upon the name of the LORD; O LORD, I beseech thee, deliver my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 5, E'Gracious is the LORD, and righteous; yea, our God is merciful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 6, E'The LORD preserveth the simple: I was brought low, and he helped me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 7, E'Return unto thy rest, O my soul; for the LORD hath dealt bountifully with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 8, E'For thou hast delivered my soul from death, mine eyes from tears, and my feet from falling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 9, E'I will walk before the LORD in the land of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 10, E'I believed, therefore have I spoken: I was greatly afflicted:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 11, E'I said in my haste, All men are liars.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 12, E'What shall I render unto the LORD for all his benefits toward me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 13, E'I will take the cup of salvation, and call upon the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 14, E'I will pay my vows unto the LORD now in the presence of all his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 15, E'Precious in the sight of the LORD is the death of his saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 16, E'O LORD, truly I am thy servant; I am thy servant, and the son of thine handmaid: thou hast loosed my bonds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 17, E'I will offer to thee the sacrifice of thanksgiving, and will call upon the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 18, E'I will pay my vows unto the LORD now in the presence of all his people,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 116, 19, E'In the courts of the LORDâ€™s house, in the midst of thee, O Jerusalem. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 117, 1, E'O Praise the LORD, all ye nations: praise him, all ye people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 117, 2, E'For his merciful kindness is great toward us: and the truth of the LORD endureth for ever. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 1, E'O give thanks unto the LORD; for he is good: because his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 2, E'Let Israel now say, that his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 3, E'Let the house of Aaron now say, that his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 4, E'Let them now that fear the LORD say, that his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 5, E'I called upon the LORD in distress: the LORD answered me, and set me in a large place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 6, E'The LORD is on my side; I will not fear: what can man do unto me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 7, E'The LORD taketh my part with them that help me: therefore shall I see my desire upon them that hate me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 8, E'It is better to trust in the LORD than to put confidence in man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 9, E'It is better to trust in the LORD than to put confidence in princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 10, E'All nations compassed me about: but in the name of the LORD will I destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 11, E'They compassed me about; yea, they compassed me about: but in the name of the LORD I will destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 12, E'They compassed me about like bees; they are quenched as the fire of thorns: for in the name of the LORD I will destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 13, E'Thou hast thrust sore at me that I might fall: but the LORD helped me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 14, E'The LORD is my strength and song, and is become my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 15, E'The voice of rejoicing and salvation is in the tabernacles of the righteous: the right hand of the LORD doeth valiantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 16, E'The right hand of the LORD is exalted: the right hand of the LORD doeth valiantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 17, E'I shall not die, but live, and declare the works of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 18, E'The LORD hath chastened me sore: but he hath not given me over unto death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 19, E'Open to me the gates of righteousness: I will go into them, and I will praise the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 20, E'This gate of the LORD, into which the righteous shall enter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 21, E'I will praise thee: for thou hast heard me, and art become my salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 22, E'The stone which the builders refused is become the head stone of the corner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 23, E'This is the LORDâ€™s doing; it is marvellous in our eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 24, E'This is the day which the LORD hath made; we will rejoice and be glad in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 25, E'Save now, I beseech thee, O LORD: O LORD, I beseech thee, send now prosperity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 26, E'Blessed be he that cometh in the name of the LORD: we have blessed you out of the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 27, E'God is the LORD, which hath shewed us light: bind the sacrifice with cords, even unto the horns of the altar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 28, E'Thou art my God, and I will praise thee: thou art my God, I will exalt thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 118, 29, E'O give thanks unto the LORD; for he is good: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 1, E'Blessed are the undefiled in the way, who walk in the law of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 2, E'Blessed are they that keep his testimonies, and that seek him with the whole heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 3, E'They also do no iniquity: they walk in his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 4, E'Thou hast commanded us to keep thy precepts diligently.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 5, E'O that my ways were directed to keep thy statutes!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 6, E'Then shall I not be ashamed, when I have respect unto all thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 7, E'I will praise thee with uprightness of heart, when I shall have learned thy righteous judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 8, E'I will keep thy statutes: O forsake me not utterly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 9, E'Wherewithal shall a young man cleanse his way? by taking heed thereto according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 10, E'With my whole heart have I sought thee: O let me not wander from thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 11, E'Thy word have I hid in mine heart, that I might not sin against thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 12, E'Blessed art thou, O LORD: teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 13, E'With my lips have I declared all the judgments of thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 14, E'I have rejoiced in the way of thy testimonies, as much as in all riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 15, E'I will meditate in thy precepts, and have respect unto thy ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 16, E'I will delight myself in thy statutes: I will not forget thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 17, E'Deal bountifully with thy servant, that I may live, and keep thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 18, E'Open thou mine eyes, that I may behold wondrous things out of thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 19, E'I am a stranger in the earth: hide not thy commandments from me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 20, E'My soul breaketh for the longing that it hath unto thy judgments at all times.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 21, E'Thou hast rebuked the proud that are cursed, which do err from thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 22, E'Remove from me reproach and contempt; for I have kept thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 23, E'Princes also did sit and speak against me: but thy servant did meditate in thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 24, E'Thy testimonies also are my delight and my counsellors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 25, E'My soul cleaveth unto the dust: quicken thou me according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 26, E'I have declared my ways, and thou heardest me: teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 27, E'Make me to understand the way of thy precepts: so shall I talk of thy wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 28, E'My soul melteth for heaviness: strengthen thou me according unto thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 29, E'Remove from me the way of lying: and grant me thy law graciously.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 30, E'I have chosen the way of truth: thy judgments have I laid before me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 31, E'I have stuck unto thy testimonies: O LORD, put me not to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 32, E'I will run the way of thy commandments, when thou shalt enlarge my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 33, E'Teach me, O LORD, the way of thy statutes; and I shall keep it unto the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 34, E'Give me understanding, and I shall keep thy law; yea, I shall observe it with my whole heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 35, E'Make me to go in the path of thy commandments; for therein do I delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 36, E'Incline my heart unto thy testimonies, and not to covetousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 37, E'Turn away mine eyes from beholding vanity; and quicken thou me in thy way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 38, E'Stablish thy word unto thy servant, who is devoted to thy fear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 39, E'Turn away my reproach which I fear: for thy judgments are good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 40, E'Behold, I have longed after thy precepts: quicken me in thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 41, E'Let thy mercies come also unto me, O LORD, even thy salvation, according to thy word.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 42, E'So shall I have wherewith to answer him that reproacheth me: for I trust in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 43, E'And take not the word of truth utterly out of my mouth; for I have hoped in thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 44, E'So shall I keep thy law continually for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 45, E'And I will walk at liberty: for I seek thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 46, E'I will speak of thy testimonies also before kings, and will not be ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 47, E'And I will delight myself in thy commandments, which I have loved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 48, E'My hands also will I lift up unto thy commandments, which I have loved; and I will meditate in thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 49, E'Remember the word unto thy servant, upon which thou hast caused me to hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 50, E'This is my comfort in my affliction: for thy word hath quickened me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 51, E'The proud have had me greatly in derision: yet have I not declined from thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 52, E'I remembered thy judgments of old, O LORD; and have comforted myself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 53, E'Horror hath taken hold upon me because of the wicked that forsake thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 54, E'Thy statutes have been my songs in the house of my pilgrimage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 55, E'I have remembered thy name, O LORD, in the night, and have kept thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 56, E'This I had, because I kept thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 57, E'Thou art my portion, O LORD: I have said that I would keep thy words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 58, E'I intreated thy favour with my whole heart: be merciful unto me according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 59, E'I thought on my ways, and turned my feet unto thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 60, E'I made haste, and delayed not to keep thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 61, E'The bands of the wicked have robbed me: but I have not forgotten thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 62, E'At midnight I will rise to give thanks unto thee because of thy righteous judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 63, E'I am a companion of all them that fear thee, and of them that keep thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 64, E'The earth, O LORD, is full of thy mercy: teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 65, E'Thou hast dealt well with thy servant, O LORD, according unto thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 66, E'Teach me good judgment and knowledge: for I have believed thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 67, E'Before I was afflicted I went astray: but now have I kept thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 68, E'Thou art good, and doest good; teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 69, E'The proud have forged a lie against me: but I will keep thy precepts with my whole heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 70, E'Their heart is as fat as grease; but I delight in thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 71, E'It is good for me that I have been afflicted; that I might learn thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 72, E'The law of thy mouth is better unto me than thousands of gold and silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 73, E'Thy hands have made me and fashioned me: give me understanding, that I may learn thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 74, E'They that fear thee will be glad when they see me; because I have hoped in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 75, E'I know, O LORD, that thy judgments are right, and that thou in faithfulness hast afflicted me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 76, E'Let, I pray thee, thy merciful kindness be for my comfort, according to thy word unto thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 77, E'Let thy tender mercies come unto me, that I may live: for thy law is my delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 78, E'Let the proud be ashamed; for they dealt perversely with me without a cause: but I will meditate in thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 79, E'Let those that fear thee turn unto me, and those that have known thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 80, E'Let my heart be sound in thy statutes; that I be not ashamed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 81, E'My soul fainteth for thy salvation: but I hope in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 82, E'Mine eyes fail for thy word, saying, When wilt thou comfort me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 83, E'For I am become like a bottle in the smoke; yet do I not forget thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 84, E'How many are the days of thy servant? when wilt thou execute judgment on them that persecute me?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 85, E'The proud have digged pits for me, which are not after thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 86, E'All thy commandments are faithful: they persecute me wrongfully; help thou me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 87, E'They had almost consumed me upon earth; but I forsook not thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 88, E'Quicken me after thy lovingkindness; so shall I keep the testimony of thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 89, E'For ever, O LORD, thy word is settled in heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 90, E'Thy faithfulness is unto all generations: thou hast established the earth, and it abideth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 91, E'They continue this day according to thine ordinances: for all are thy servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 92, E'Unless thy law had been my delights, I should then have perished in mine affliction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 93, E'I will never forget thy precepts: for with them thou hast quickened me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 94, E'I am thine, save me; for I have sought thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 95, E'The wicked have waited for me to destroy me: but I will consider thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 96, E'I have seen an end of all perfection: but thy commandment is exceeding broad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 97, E'O how love I thy law! it is my meditation all the day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 98, E'Thou through thy commandments hast made me wiser than mine enemies: for they are ever with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 99, E'I have more understanding than all my teachers: for thy testimonies are my meditation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 100, E'I understand more than the ancients, because I keep thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 101, E'I have refrained my feet from every evil way, that I might keep thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 102, E'I have not departed from thy judgments: for thou hast taught me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 103, E'How sweet are thy words unto my taste! yea, sweeter than honey to my mouth!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 104, E'Through thy precepts I get understanding: therefore I hate every false way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 105, E'Thy word is a lamp unto my feet, and a light unto my path.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 106, E'I have sworn, and I will perform it, that I will keep thy righteous judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 107, E'I am afflicted very much: quicken me, O LORD, according unto thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 108, E'Accept, I beseech thee, the freewill offerings of my mouth, O LORD, and teach me thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 109, E'My soul is continually in my hand: yet do I not forget thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 110, E'The wicked have laid a snare for me: yet I erred not from thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 111, E'Thy testimonies have I taken as an heritage for ever: for they are the rejoicing of my heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 112, E'I have inclined mine heart to perform thy statutes alway, even unto the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 113, E'I hate vain thoughts: but thy law do I love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 114, E'Thou art my hiding place and my shield: I hope in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 115, E'Depart from me, ye evildoers: for I will keep the commandments of my God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 116, E'Uphold me according unto thy word, that I may live: and let me not be ashamed of my hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 117, E'Hold thou me up, and I shall be safe: and I will have respect unto thy statutes continually.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 118, E'Thou hast trodden down all them that err from thy statutes: for their deceit is falsehood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 119, E'Thou puttest away all the wicked of the earth like dross: therefore I love thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 120, E'My flesh trembleth for fear of thee; and I am afraid of thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 121, E'I have done judgment and justice: leave me not to mine oppressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 122, E'Be surety for thy servant for good: let not the proud oppress me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 123, E'Mine eyes fail for thy salvation, and for the word of thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 124, E'Deal with thy servant according unto thy mercy, and teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 125, E'I am thy servant; give me understanding, that I may know thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 126, E'It is time for thee, LORD, to work: for they have made void thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 127, E'Therefore I love thy commandments above gold; yea, above fine gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 128, E'Therefore I esteem all thy precepts concerning all things to be right; and I hate every false way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 129, E'Thy testimonies are wonderful: therefore doth my soul keep them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 130, E'The entrance of thy words giveth light; it giveth understanding unto the simple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 131, E'I opened my mouth, and panted: for I longed for thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 132, E'Look thou upon me, and be merciful unto me, as thou usest to do unto those that love thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 133, E'Order my steps in thy word: and let not any iniquity have dominion over me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 134, E'Deliver me from the oppression of man: so will I keep thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 135, E'Make thy face to shine upon thy servant; and teach me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 136, E'Rivers of waters run down mine eyes, because they keep not thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 137, E'Righteous art thou, O LORD, and upright are thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 138, E'Thy testimonies that thou hast commanded are righteous and very faithful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 139, E'My zeal hath consumed me, because mine enemies have forgotten thy words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 140, E'Thy word is very pure: therefore thy servant loveth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 141, E'I am small and despised: yet do not I forget thy precepts.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 142, E'Thy righteousness is an everlasting righteousness, and thy law is the truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 143, E'Trouble and anguish have taken hold on me: yet thy commandments are my delights.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 144, E'The righteousness of thy testimonies is everlasting: give me understanding, and I shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 145, E'I cried with my whole heart; hear me, O LORD: I will keep thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 146, E'I cried unto thee; save me, and I shall keep thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 147, E'I prevented the dawning of the morning, and cried: I hoped in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 148, E'Mine eyes prevent the night watches, that I might meditate in thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 149, E'Hear my voice according unto thy lovingkindness: O LORD, quicken me according to thy judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 150, E'They draw nigh that follow after mischief: they are far from thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 151, E'Thou art near, O LORD; and all thy commandments are truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 152, E'Concerning thy testimonies, I have known of old that thou hast founded them for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 153, E'Consider mine affliction, and deliver me: for I do not forget thy law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 154, E'Plead my cause, and deliver me: quicken me according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 155, E'Salvation is far from the wicked: for they seek not thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 156, E'Great are thy tender mercies, O LORD: quicken me according to thy judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 157, E'Many are my persecutors and mine enemies; yet do I not decline from thy testimonies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 158, E'I beheld the transgressors, and was grieved; because they kept not thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 159, E'Consider how I love thy precepts: quicken me, O LORD, according to thy lovingkindness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 160, E'Thy word is true from the beginning: and every one of thy righteous judgments endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 161, E'Princes have persecuted me without a cause: but my heart standeth in awe of thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 162, E'I rejoice at thy word, as one that findeth great spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 163, E'I hate and abhor lying: but thy law do I love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 164, E'Seven times a day do I praise thee because of thy righteous judgments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 165, E'Great peace have they which love thy law: and nothing shall offend them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 166, E'LORD, I have hoped for thy salvation, and done thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 167, E'My soul hath kept thy testimonies; and I love them exceedingly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 168, E'I have kept thy precepts and thy testimonies: for all my ways are before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 169, E'Let my cry come near before thee, O LORD: give me understanding according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 170, E'Let my supplication come before thee: deliver me according to thy word.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 171, E'My lips shall utter praise, when thou hast taught me thy statutes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 172, E'My tongue shall speak of thy word: for all thy commandments are righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 173, E'Let thine hand help me; for I have chosen thy precepts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 174, E'I have longed for thy salvation, O LORD; and thy law is my delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 175, E'Let my soul live, and it shall praise thee; and let thy judgments help me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 119, 176, E'I have gone astray like a lost sheep; seek thy servant; for I do not forget thy commandments.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 1, E'In my distress I cried unto the LORD, and he heard me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 2, E'Deliver my soul, O LORD, from lying lips, and from a deceitful tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 3, E'What shall be given unto thee? or what shall be done unto thee, thou false tongue?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 4, E'Sharp arrows of the mighty, with coals of juniper.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 5, E'Woe is me, that I sojourn in Mesech, that I dwell in the tents of Kedar!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 6, E'My soul hath long dwelt with him that hateth peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 120, 7, E'I am for peace: but when I speak, they are for war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 1, E'I will lift up mine eyes unto the hills, from whence cometh my help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 2, E'My help cometh from the LORD, which made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 3, E'He will not suffer thy foot to be moved: he that keepeth thee will not slumber.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 4, E'Behold, he that keepeth Israel shall neither slumber nor sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 5, E'The LORD is thy keeper: the LORD is thy shade upon thy right hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 6, E'The sun shall not smite thee by day, nor the moon by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 7, E'The LORD shall preserve thee from all evil: he shall preserve thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 121, 8, E'The LORD shall preserve thy going out and thy coming in from this time forth, and even for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 1, E'I was glad when they said unto me, Let us go into the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 2, E'Our feet shall stand within thy gates, O Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 3, E'Jerusalem is builded as a city that is compact together:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 4, E'Whither the tribes go up, the tribes of the LORD, unto the testimony of Israel, to give thanks unto the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 5, E'For there are set thrones of judgment, the thrones of the house of David.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 6, E'Pray for the peace of Jerusalem: they shall prosper that love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 7, E'Peace be within thy walls, and prosperity within thy palaces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 8, E'For my brethren and companionsâ€™ sakes, I will now say, Peace be within thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 122, 9, E'Because of the house of the LORD our God I will seek thy good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 123, 1, E'Unto thee lift I up mine eyes, O thou that dwellest in the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 123, 2, E'Behold, as the eyes of servants look unto the hand of their masters, and as the eyes of a maiden unto the hand of her mistress; so our eyes wait upon the LORD our God, until that he have mercy upon us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 123, 3, E'Have mercy upon us, O LORD, have mercy upon us: for we are exceedingly filled with contempt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 123, 4, E'Our soul is exceedingly filled with the scorning of those that are at ease, and with the contempt of the proud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 1, E'If it had not been the LORD who was on our side, now may Israel say;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 2, E'If it had not been the LORD who was on our side, when men rose up against us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 3, E'Then they had swallowed us up quick, when their wrath was kindled against us:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 4, E'Then the waters had overwhelmed us, the stream had gone over our soul:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 5, E'Then the proud waters had gone over our soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 6, E'Blessed be the LORD, who hath not given us as a prey to their teeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 7, E'Our soul is escaped as a bird out of the snare of the fowlers: the snare is broken, and we are escaped.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 124, 8, E'Our help is in the name of the LORD, who made heaven and earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 125, 1, E'They that trust in the LORD shall be as mount Zion, which cannot be removed, but abideth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 125, 2, E'As the mountains are round about Jerusalem, so the LORD is round about his people from henceforth even for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 125, 3, E'For the rod of the wicked shall not rest upon the lot of the righteous; lest the righteous put forth their hands unto iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 125, 4, E'Do good, O LORD, unto those that be good, and to them that are upright in their hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 125, 5, E'As for such as turn aside unto their crooked ways, the LORD shall lead them forth with the workers of iniquity: but peace shall be upon Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 1, E'When the LORD turned again the captivity of Zion, we were like them that dream.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 2, E'Then was our mouth filled with laughter, and our tongue with singing: then said they among the heathen, The LORD hath done great things for them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 3, E'The LORD hath done great things for us; whereof we are glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 4, E'Turn again our captivity, O LORD, as the streams in the south.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 5, E'They that sow in tears shall reap in joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 126, 6, E'He that goeth forth and weepeth, bearing precious seed, shall doubtless come again with rejoicing, bringing his sheaves with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 127, 1, E'Except the LORD build the house, they labour in vain that build it: except the LORD keep the city, the watchman waketh but in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 127, 2, E'It is vain for you to rise up early, to sit up late, to eat the bread of sorrows: for so he giveth his beloved sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 127, 3, E'Lo, children are an heritage of the LORD: and the fruit of the womb is his reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 127, 4, E'As arrows are in the hand of a mighty man; so are children of the youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 127, 5, E'Happy is the man that hath his quiver full of them: they shall not be ashamed, but they shall speak with the enemies in the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 1, E'Blessed is every one that feareth the LORD; that walketh in his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 2, E'For thou shalt eat the labour of thine hands: happy shalt thou be, and it shall be well with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 3, E'Thy wife shall be as a fruitful vine by the sides of thine house: thy children like olive plants round about thy table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 4, E'Behold, that thus shall the man be blessed that feareth the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 5, E'The LORD shall bless thee out of Zion: and thou shalt see the good of Jerusalem all the days of thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 128, 6, E'Yea, thou shalt see thy childrenâ€™s children, and peace upon Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 1, E'Many a time have they afflicted me from my youth, may Israel now say:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 2, E'Many a time have they afflicted me from my youth: yet they have not prevailed against me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 3, E'The plowers plowed upon my back: they made long their furrows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 4, E'The LORD is righteous: he hath cut asunder the cords of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 5, E'Let them all be confounded and turned back that hate Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 6, E'Let them be as the grass upon the housetops, which withereth afore it groweth up:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 7, E'Wherewith the mower filleth not his hand; nor he that bindeth sheaves his bosom.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 129, 8, E'Neither do they which go by say, The blessing of the LORD be upon you: we bless you in the name of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 1, E'Out of the depths have I cried unto thee, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 2, E'Lord, hear my voice: let thine ears be attentive to the voice of my supplications.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 3, E'If thou, LORD, shouldest mark iniquities, O Lord, who shall stand?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 4, E'But there is forgiveness with thee, that thou mayest be feared.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 5, E'I wait for the LORD, my soul doth wait, and in his word do I hope.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 6, E'My soul waiteth for the Lord more than they that watch for the morning: I say, more than they that watch for the morning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 7, E'Let Israel hope in the LORD: for with the LORD there is mercy, and with him is plenteous redemption.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 130, 8, E'And he shall redeem Israel from all his iniquities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 131, 1, E'Lord, my heart is not haughty, nor mine eyes lofty: neither do I exercise myself in great matters, or in things too high for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 131, 2, E'Surely I have behaved and quieted myself, as a child that is weaned of his mother: my soul is even as a weaned child.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 131, 3, E'Let Israel hope in the LORD from henceforth and for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 1, E'Lord, remember David, and all his afflictions:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 2, E'How he sware unto the LORD, and vowed unto the mighty God of Jacob;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 3, E'Surely I will not come into the tabernacle of my house, nor go up into my bed;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 4, E'I will not give sleep to mine eyes, or slumber to mine eyelids,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 5, E'Until I find out a place for the LORD, an habitation for the mighty God of Jacob.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 6, E'Lo, we heard of it at Ephratah: we found it in the fields of the wood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 7, E'We will go into his tabernacles: we will worship at his footstool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 8, E'Arise, O LORD, into thy rest; thou, and the ark of thy strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 9, E'Let thy priests be clothed with righteousness; and let thy saints shout for joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 10, E'For thy servant Davidâ€™s sake turn not away the face of thine anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 11, E'The LORD hath sworn in truth unto David; he will not turn from it; Of the fruit of thy body will I set upon thy throne.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 12, E'If thy children will keep my covenant and my testimony that I shall teach them, their children shall also sit upon thy throne for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 13, E'For the LORD hath chosen Zion; he hath desired it for his habitation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 14, E'This is my rest for ever: here will I dwell; for I have desired it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 15, E'I will abundantly bless her provision: I will satisfy her poor with bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 16, E'I will also clothe her priests with salvation: and her saints shall shout aloud for joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 17, E'There will I make the horn of David to bud: I have ordained a lamp for mine anointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 132, 18, E'His enemies will I clothe with shame: but upon himself shall his crown flourish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 133, 1, E'Behold, how good and how pleasant it is for brethren to dwell together in unity!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 133, 2, E'It is like the precious ointment upon the head, that ran down upon the beard, even Aaronâ€™s beard: that went down to the skirts of his garments;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 133, 3, E'As the dew of Hermon, and as the dew that descended upon the mountains of Zion: for there the LORD commanded the blessing, even life for evermore.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 134, 1, E'Behold, bless ye the LORD, all ye servants of the LORD, which by night stand in the house of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 134, 2, E'Lift up your hands in the sanctuary, and bless the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 134, 3, E'The LORD that made heaven and earth bless thee out of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 1, E'Praise ye the LORD. Praise ye the name of the LORD; praise him, O ye servants of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 2, E'Ye that stand in the house of the LORD, in the courts of the house of our God,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 3, E'Praise the LORD; for the LORD is good: sing praises unto his name; for it is pleasant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 4, E'For the LORD hath chosen Jacob unto himself, and Israel for his peculiar treasure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 5, E'For I know that the LORD is great, and that our Lord is above all gods.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 6, E'Whatsoever the LORD pleased, that did he in heaven, and in earth, in the seas, and all deep places.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 7, E'He causeth the vapours to ascend from the ends of the earth; he maketh lightnings for the rain; he bringeth the wind out of his treasuries.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 8, E'Who smote the firstborn of Egypt, both of man and beast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 9, E'Who sent tokens and wonders into the midst of thee, O Egypt, upon Pharaoh, and upon all his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 10, E'Who smote great nations, and slew mighty kings;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 11, E'Sihon king of the Amorites, and Og king of Bashan, and all the kingdoms of Canaan:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 12, E'And gave their land for an heritage, an heritage unto Israel his people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 13, E'Thy name, O LORD, endureth for ever; and thy memorial, O LORD, throughout all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 14, E'For the LORD will judge his people, and he will repent himself concerning his servants.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 15, E'The idols of the heathen are silver and gold, the work of menâ€™s hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 16, E'They have mouths, but they speak not; eyes have they, but they see not;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 17, E'They have ears, but they hear not; neither is there any breath in their mouths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 18, E'They that make them are like unto them: so is every one that trusteth in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 19, E'Bless the LORD, O house of Israel: bless the LORD, O house of Aaron:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 20, E'Bless the LORD, O house of Levi: ye that fear the LORD, bless the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 135, 21, E'Blessed be the LORD out of Zion, which dwelleth at Jerusalem. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 1, E'O give thanks unto the LORD; for he is good: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 2, E'O give thanks unto the God of gods: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 3, E'O give thanks to the Lord of lords: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 4, E'To him who alone doeth great wonders: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 5, E'To him that by wisdom made the heavens: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 6, E'To him that stretched out the earth above the waters: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 7, E'To him that made great lights: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 8, E'The sun to rule by day: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 9, E'The moon and stars to rule by night: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 10, E'To him that smote Egypt in their firstborn: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 11, E'And brought out Israel from among them: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 12, E'With a strong hand, and with a stretched out arm: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 13, E'To him which divided the Red sea into parts: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 14, E'And made Israel to pass through the midst of it: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 15, E'But overthrew Pharaoh and his host in the Red sea: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 16, E'To him which led his people through the wilderness: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 17, E'To him which smote great kings: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 18, E'And slew famous kings: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 19, E'Sihon king of the Amorites: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 20, E'And Og the king of Bashan: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 21, E'And gave their land for an heritage: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 22, E'Even an heritage unto Israel his servant: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 23, E'Who remembered us in our low estate: for his mercy endureth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 24, E'And hath redeemed us from our enemies: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 25, E'Who giveth food to all flesh: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 136, 26, E'O give thanks unto the God of heaven: for his mercy endureth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 1, E'By the rivers of Babylon, there we sat down, yea, we wept, when we remembered Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 2, E'We hanged our harps upon the willows in the midst thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 3, E'For there they that carried us away captive required of us a song; and they that wasted us required of us mirth, saying, Sing us one of the songs of Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 4, E'How shall we sing the LORDâ€™s song in a strange land?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 5, E'If I forget thee, O Jerusalem, let my right hand forget her cunning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 6, E'If I do not remember thee, let my tongue cleave to the roof of my mouth; if I prefer not Jerusalem above my chief joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 7, E'Remember, O LORD, the children of Edom in the day of Jerusalem; who said, Rase it, rase it, even to the foundation thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 8, E'O daughter of Babylon, who art to be destroyed; happy shall he be, that rewardeth thee as thou hast served us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 137, 9, E'Happy shall he be, that taketh and dasheth thy little ones against the stones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 1, E'I will praise thee with my whole heart: before the gods will I sing praise unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 2, E'I will worship toward thy holy temple, and praise thy name for thy lovingkindness and for thy truth: for thou hast magnified thy word above all thy name.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 3, E'In the day when I cried thou answeredst me, and strengthenedst me with strength in my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 4, E'All the kings of the earth shall praise thee, O LORD, when they hear the words of thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 5, E'Yea, they shall sing in the ways of the LORD: for great is the glory of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 6, E'Though the LORD be high, yet hath he respect unto the lowly: but the proud he knoweth afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 7, E'Though I walk in the midst of trouble, thou wilt revive me: thou shalt stretch forth thine hand against the wrath of mine enemies, and thy right hand shall save me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 138, 8, E'The LORD will perfect that which concerneth me: thy mercy, O LORD, endureth for ever: forsake not the works of thine own hands.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 1, E'O LORD, thou hast searched me, and known me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 2, E'Thou knowest my downsitting and mine uprising, thou understandest my thought afar off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 3, E'Thou compassest my path and my lying down, and art acquainted with all my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 4, E'For there is not a word in my tongue, but, lo, O LORD, thou knowest it altogether.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 5, E'Thou hast beset me behind and before, and laid thine hand upon me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 6, E'Such knowledge is too wonderful for me; it is high, I cannot attain unto it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 7, E'Whither shall I go from thy spirit? or whither shall I flee from thy presence?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 8, E'If I ascend up into heaven, thou art there: if I make my bed in hell, behold, thou art there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 9, E'If I take the wings of the morning, and dwell in the uttermost parts of the sea;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 10, E'Even there shall thy hand lead me, and thy right hand shall hold me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 11, E'If I say, Surely the darkness shall cover me; even the night shall be light about me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 12, E'Yea, the darkness hideth not from thee; but the night shineth as the day: the darkness and the light are both alike to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 13, E'For thou hast possessed my reins: thou hast covered me in my motherâ€™s womb.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 14, E'I will praise thee; for I am fearfully and wonderfully made: marvellous are thy works; and that my soul knoweth right well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 15, E'My substance was not hid from thee, when I was made in secret, and curiously wrought in the lowest parts of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 16, E'Thine eyes did see my substance, yet being unperfect; and in thy book all my members were written, which in continuance were fashioned, when as yet there was none of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 17, E'How precious also are thy thoughts unto me, O God! how great is the sum of them!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 18, E'If I should count them, they are more in number than the sand: when I awake, I am still with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 19, E'Surely thou wilt slay the wicked, O God: depart from me therefore, ye bloody men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 20, E'For they speak against thee wickedly, and thine enemies take thy name in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 21, E'Do not I hate them, O LORD, that hate thee? and am not I grieved with those that rise up against thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 22, E'I hate them with perfect hatred: I count them mine enemies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 23, E'Search me, O God, and know my heart: try me, and know my thoughts:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 139, 24, E'And see if there be any wicked way in me, and lead me in the way everlasting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 1, E'Deliver me, O LORD, from the evil man: preserve me from the violent man;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 2, E'Which imagine mischiefs in their heart; continually are they gathered together for war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 3, E'They have sharpened their tongues like a serpent; addersâ€™ poison is under their lips. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 4, E'Keep me, O LORD, from the hands of the wicked; preserve me from the violent man; who have purposed to overthrow my goings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 5, E'The proud have hid a snare for me, and cords; they have spread a net by the wayside; they have set gins for me. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 6, E'I said unto the LORD, Thou art my God: hear the voice of my supplications, O LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 7, E'O GOD the Lord, the strength of my salvation, thou hast covered my head in the day of battle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 8, E'Grant not, O LORD, the desires of the wicked: further not his wicked device; lest they exalt themselves. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 9, E'As for the head of those that compass me about, let the mischief of their own lips cover them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 10, E'Let burning coals fall upon them: let them be cast into the fire; into deep pits, that they rise not up again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 11, E'Let not an evil speaker be established in the earth: evil shall hunt the violent man to overthrow him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 12, E'I know that the LORD will maintain the cause of the afflicted, and the right of the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 140, 13, E'Surely the righteous shall give thanks unto thy name: the upright shall dwell in thy presence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 1, E'Lord, I cry unto thee: make haste unto me; give ear unto my voice, when I cry unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 2, E'Let my prayer be set forth before thee as incense; and the lifting up of my hands as the evening sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 3, E'Set a watch, O LORD, before my mouth; keep the door of my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 4, E'Incline not my heart to any evil thing, to practise wicked works with men that work iniquity: and let me not eat of their dainties.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 5, E'Let the righteous smite me; it shall be a kindness: and let him reprove me; it shall be an excellent oil, which shall not break my head: for yet my prayer also shall be in their calamities.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 6, E'When their judges are overthrown in stony places, they shall hear my words; for they are sweet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 7, E'Our bones are scattered at the graveâ€™s mouth, as when one cutteth and cleaveth wood upon the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 8, E'But mine eyes are unto thee, O GOD the Lord: in thee is my trust; leave not my soul destitute.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 9, E'Keep me from the snares which they have laid for me, and the gins of the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 141, 10, E'Let the wicked fall into their own nets, whilst that I withal escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 1, E'I cried unto the LORD with my voice; with my voice unto the LORD did I make my supplication.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 2, E'I poured out my complaint before him; I shewed before him my trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 3, E'When my spirit was overwhelmed within me, then thou knewest my path. In the way wherein I walked have they privily laid a snare for me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 4, E'I looked on my right hand, and beheld, but there was no man that would know me: refuge failed me; no man cared for my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 5, E'I cried unto thee, O LORD: I said, Thou art my refuge and my portion in the land of the living.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 6, E'Attend unto my cry; for I am brought very low: deliver me from my persecutors; for they are stronger than I.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 142, 7, E'Bring my soul out of prison, that I may praise thy name: the righteous shall compass me about; for thou shalt deal bountifully with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 1, E'Hear my prayer, O LORD, give ear to my supplications: in thy faithfulness answer me, and in thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 2, E'And enter not into judgment with thy servant: for in thy sight shall no man living be justified.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 3, E'For the enemy hath persecuted my soul; he hath smitten my life down to the ground; he hath made me to dwell in darkness, as those that have been long dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 4, E'Therefore is my spirit overwhelmed within me; my heart within me is desolate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 5, E'I remember the days of old; I meditate on all thy works; I muse on the work of thy hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 6, E'I stretch forth my hands unto thee: my soul thirsteth after thee, as a thirsty land. Selah.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 7, E'Hear me speedily, O LORD: my spirit faileth: hide not thy face from me, lest I be like unto them that go down into the pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 8, E'Cause me to hear thy lovingkindness in the morning; for in thee do I trust: cause me to know the way wherein I should walk; for I lift up my soul unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 9, E'Deliver me, O LORD, from mine enemies: I flee unto thee to hide me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 10, E'Teach me to do thy will; for thou art my God: thy spirit is good; lead me into the land of uprightness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 11, E'Quicken me, O LORD, for thy nameâ€™s sake: for thy righteousnessâ€™ sake bring my soul out of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 143, 12, E'And of thy mercy cut off mine enemies, and destroy all them that afflict my soul: for I am thy servant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 1, E'Blessed be the LORD my strength, which teacheth my hands to war, and my fingers to fight:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 2, E'My goodness, and my fortress; my high tower, and my deliverer; my shield, and he in whom I trust; who subdueth my people under me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 3, E'LORD, what is man, that thou takest knowledge of him! or the son of man, that thou makest account of him!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 4, E'Man is like to vanity: his days are as a shadow that passeth away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 5, E'Bow thy heavens, O LORD, and come down: touch the mountains, and they shall smoke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 6, E'Cast forth lightning, and scatter them: shoot out thine arrows, and destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 7, E'Send thine hand from above; rid me, and deliver me out of great waters, from the hand of strange children;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 8, E'Whose mouth speaketh vanity, and their right hand is a right hand of falsehood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 9, E'I will sing a new song unto thee, O God: upon a psaltery and an instrument of ten strings will I sing praises unto thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 10, E'It is he that giveth salvation unto kings: who delivereth David his servant from the hurtful sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 11, E'Rid me, and deliver me from the hand of strange children, whose mouth speaketh vanity, and their right hand is a right hand of falsehood:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 12, E'That our sons may be as plants grown up in their youth; that our daughters may be as corner stones, polished after the similitude of a palace:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 13, E'That our garners may be full, affording all manner of store: that our sheep may bring forth thousands and ten thousands in our streets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 14, E'That our oxen may be strong to labour; that there be no breaking in, nor going out; that there be no complaining in our streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 144, 15, E'Happy is that people, that is in such a case: yea, happy is that people, whose God is the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 1, E'I will extol thee, my God, O king; and I will bless thy name for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 2, E'Every day will I bless thee; and I will praise thy name for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 3, E'Great is the LORD, and greatly to be praised; and his greatness is unsearchable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 4, E'One generation shall praise thy works to another, and shall declare thy mighty acts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 5, E'I will speak of the glorious honour of thy majesty, and of thy wondrous works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 6, E'And men shall speak of the might of thy terrible acts: and I will declare thy greatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 7, E'They shall abundantly utter the memory of thy great goodness, and shall sing of thy righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 8, E'The LORD is gracious, and full of compassion; slow to anger, and of great mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 9, E'The LORD is good to all: and his tender mercies are over all his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 10, E'All thy works shall praise thee, O LORD; and thy saints shall bless thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 11, E'They shall speak of the glory of thy kingdom, and talk of thy power;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 12, E'To make known to the sons of men his mighty acts, and the glorious majesty of his kingdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 13, E'Thy kingdom is an everlasting kingdom, and thy dominion endureth throughout all generations.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 14, E'The LORD upholdeth all that fall, and raiseth up all those that be bowed down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 15, E'The eyes of all wait upon thee; and thou givest them their meat in due season.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 16, E'Thou openest thine hand, and satisfiest the desire of every living thing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 17, E'The LORD is righteous in all his ways, and holy in all his works.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 18, E'The LORD is nigh unto all them that call upon him, to all that call upon him in truth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 19, E'He will fulfil the desire of them that fear him: he also will hear their cry, and will save them.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 20, E'The LORD preserveth all them that love him: but all the wicked will he destroy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 145, 21, E'My mouth shall speak the praise of the LORD: and let all flesh bless his holy name for ever and ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 1, E'Praise ye the LORD. Praise the LORD, O my soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 2, E'While I live will I praise the LORD: I will sing praises unto my God while I have any being.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 3, E'Put not your trust in princes, nor in the son of man, in whom there is no help.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 4, E'His breath goeth forth, he returneth to his earth; in that very day his thoughts perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 5, E'Happy is he that hath the God of Jacob for his help, whose hope is in the LORD his God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 6, E'Which made heaven, and earth, the sea, and all that therein is: which keepeth truth for ever:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 7, E'Which executeth judgment for the oppressed: which giveth food to the hungry. The LORD looseth the prisoners:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 8, E'The LORD openeth the eyes of the blind: the LORD raiseth them that are bowed down: the LORD loveth the righteous:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 9, E'The LORD preserveth the strangers; he relieveth the fatherless and widow: but the way of the wicked he turneth upside down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 146, 10, E'The LORD shall reign for ever, even thy God, O Zion, unto all generations. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 1, E'Praise ye the LORD: for it is good to sing praises unto our God; for it is pleasant; and praise is comely.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 2, E'The LORD doth build up Jerusalem: he gathereth together the outcasts of Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 3, E'He healeth the broken in heart, and bindeth up their wounds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 4, E'He telleth the number of the stars; he calleth them all by their names.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 5, E'Great is our Lord, and of great power: his understanding is infinite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 6, E'The LORD lifteth up the meek: he casteth the wicked down to the ground.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 7, E'Sing unto the LORD with thanksgiving; sing praise upon the harp unto our God:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 8, E'Who covereth the heaven with clouds, who prepareth rain for the earth, who maketh grass to grow upon the mountains.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 9, E'He giveth to the beast his food, and to the young ravens which cry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 10, E'He delighteth not in the strength of the horse: he taketh not pleasure in the legs of a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 11, E'The LORD taketh pleasure in them that fear him, in those that hope in his mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 12, E'Praise the LORD, O Jerusalem; praise thy God, O Zion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 13, E'For he hath strengthened the bars of thy gates; he hath blessed thy children within thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 14, E'He maketh peace in thy borders, and filleth thee with the finest of the wheat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 15, E'He sendeth forth his commandment upon earth: his word runneth very swiftly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 16, E'He giveth snow like wool: he scattereth the hoarfrost like ashes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 17, E'He casteth forth his ice like morsels: who can stand before his cold?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 18, E'He sendeth out his word, and melteth them: he causeth his wind to blow, and the waters flow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 19, E'He sheweth his word unto Jacob, his statutes and his judgments unto Israel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 147, 20, E'He hath not dealt so with any nation: and as for his judgments, they have not known them. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 1, E'Praise ye the LORD. Praise ye the LORD from the heavens: praise him in the heights.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 2, E'Praise ye him, all his angels: praise ye him, all his hosts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 3, E'Praise ye him, sun and moon: praise him, all ye stars of light.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 4, E'Praise him, ye heavens of heavens, and ye waters that be above the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 5, E'Let them praise the name of the LORD: for he commanded, and they were created.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 6, E'He hath also stablished them for ever and ever: he hath made a decree which shall not pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 7, E'Praise the LORD from the earth, ye dragons, and all deeps:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 8, E'Fire, and hail; snow, and vapours; stormy wind fulfilling his word:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 9, E'Mountains, and all hills; fruitful trees, and all cedars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 10, E'Beasts, and all cattle; creeping things, and flying fowl:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 11, E'Kings of the earth, and all people; princes, and all judges of the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 12, E'Both young men, and maidens; old men, and children:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 13, E'Let them praise the name of the LORD: for his name alone is excellent; his glory is above the earth and heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 148, 14, E'He also exalteth the horn of his people, the praise of all his saints; even of the children of Israel, a people near unto him. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 1, E'Praise ye the LORD. Sing unto the LORD a new song, and his praise in the congregation of saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 2, E'Let Israel rejoice in him that made him: let the children of Zion be joyful in their King.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 3, E'Let them praise his name in the dance: let them sing praises unto him with the timbrel and harp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 4, E'For the LORD taketh pleasure in his people: he will beautify the meek with salvation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 5, E'Let the saints be joyful in glory: let them sing aloud upon their beds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 6, E'Let the high praises of God be in their mouth, and a two-edged sword in their hand;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 7, E'To execute vengeance upon the heathen, and punishments upon the people;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 8, E'To bind their kings with chains, and their nobles with fetters of iron;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 149, 9, E'To execute upon them the judgment written: this honour have all his saints. Praise ye the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 1, E'Praise ye the LORD. Praise God in his sanctuary: praise him in the firmament of his power.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 2, E'Praise him for his mighty acts: praise him according to his excellent greatness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 3, E'Praise him with the sound of the trumpet: praise him with the psaltery and harp.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 4, E'Praise him with the timbrel and dance: praise him with stringed instruments and organs.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 5, E'Praise him upon the loud cymbals: praise him upon the high sounding cymbals.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '4c412ed8-820d-4d17-b803-4d29a409034b', 150, 6, E'Let every thing that hath breath praise the LORD. Praise ye the LORD.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Psalms') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 1, E'The proverbs of Solomon the son of David, king of Israel;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 2, E'To know wisdom and instruction; to perceive the words of understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 3, E'To receive the instruction of wisdom, justice, and judgment, and equity;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 4, E'To give subtilty to the simple, to the young man knowledge and discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 5, E'A wise man will hear, and will increase learning; and a man of understanding shall attain unto wise counsels:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 6, E'To understand a proverb, and the interpretation; the words of the wise, and their dark sayings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 7, E'The fear of the LORD is the beginning of knowledge: but fools despise wisdom and instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 8, E'My son, hear the instruction of thy father, and forsake not the law of thy mother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 9, E'For they shall be an ornament of grace unto thy head, and chains about thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 10, E'My son, if sinners entice thee, consent thou not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 11, E'If they say, Come with us, let us lay wait for blood, let us lurk privily for the innocent without cause:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 12, E'Let us swallow them up alive as the grave; and whole, as those that go down into the pit:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 13, E'We shall find all precious substance, we shall fill our houses with spoil:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 14, E'Cast in thy lot among us; let us all have one purse:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 15, E'My son, walk not thou in the way with them; refrain thy foot from their path:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 16, E'For their feet run to evil, and make haste to shed blood.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 17, E'Surely in vain the net is spread in the sight of any bird.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 18, E'And they lay wait for their own blood; they lurk privily for their own lives.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 19, E'So are the ways of every one that is greedy of gain; which taketh away the life of the owners thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 20, E'Wisdom crieth without; she uttereth her voice in the streets:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 21, E'She crieth in the chief place of concourse, in the openings of the gates: in the city she uttereth her words, saying,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 22, E'How long, ye simple ones, will ye love simplicity? and the scorners delight in their scorning, and fools hate knowledge?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 23, E'Turn you at my reproof: behold, I will pour out my spirit unto you, I will make known my words unto you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 24, E'Because I have called, and ye refused; I have stretched out my hand, and no man regarded;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 25, E'But ye have set at nought all my counsel, and would none of my reproof:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 26, E'I also will laugh at your calamity; I will mock when your fear cometh;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 27, E'When your fear cometh as desolation, and your destruction cometh as a whirlwind; when distress and anguish cometh upon you.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 28, E'Then shall they call upon me, but I will not answer; they shall seek me early, but they shall not find me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 29, E'For that they hated knowledge, and did not choose the fear of the LORD:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 30, E'They would none of my counsel: they despised all my reproof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 31, E'Therefore shall they eat of the fruit of their own way, and be filled with their own devices.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 32, E'For the turning away of the simple shall slay them, and the prosperity of fools shall destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 1, 33, E'But whoso hearkeneth unto me shall dwell safely, and shall be quiet from fear of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 1, E'My son, if thou wilt receive my words, and hide my commandments with thee;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 2, E'So that thou incline thine ear unto wisdom, and apply thine heart to understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 3, E'Yea, if thou criest after knowledge, and liftest up thy voice for understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 4, E'If thou seekest her as silver, and searchest for her as for hid treasures;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 5, E'Then shalt thou understand the fear of the LORD, and find the knowledge of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 6, E'For the LORD giveth wisdom: out of his mouth cometh knowledge and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 7, E'He layeth up sound wisdom for the righteous: he is a buckler to them that walk uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 8, E'He keepeth the paths of judgment, and preserveth the way of his saints.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 9, E'Then shalt thou understand righteousness, and judgment, and equity; yea, every good path.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 10, E'When wisdom entereth into thine heart, and knowledge is pleasant unto thy soul;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 11, E'Discretion shall preserve thee, understanding shall keep thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 12, E'To deliver thee from the way of the evil man, from the man that speaketh froward things;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 13, E'Who leave the paths of uprightness, to walk in the ways of darkness;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 14, E'Who rejoice to do evil, and delight in the frowardness of the wicked;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 15, E'Whose ways are crooked, and they froward in their paths:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 16, E'To deliver thee from the strange woman, even from the stranger which flattereth with her words;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 17, E'Which forsaketh the guide of her youth, and forgetteth the covenant of her God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 18, E'For her house inclineth unto death, and her paths unto the dead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 19, E'None that go unto her return again, neither take they hold of the paths of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 20, E'That thou mayest walk in the way of good men, and keep the paths of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 21, E'For the upright shall dwell in the land, and the perfect shall remain in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 2, 22, E'But the wicked shall be cut off from the earth, and the transgressors shall be rooted out of it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 1, E'My son, forget not my law; but let thine heart keep my commandments:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 2, E'For length of days, and long life, and peace, shall they add to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 3, E'Let not mercy and truth forsake thee: bind them about thy neck; write them upon the table of thine heart:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 4, E'So shalt thou find favour and good understanding in the sight of God and man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 5, E'Trust in the LORD with all thine heart; and lean not unto thine own understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 6, E'In all thy ways acknowledge him, and he shall direct thy paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 7, E'Be not wise in thine own eyes: fear the LORD, and depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 8, E'It shall be health to thy navel, and marrow to thy bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 9, E'Honour the LORD with thy substance, and with the firstfruits of all thine increase:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 10, E'So shall thy barns be filled with plenty, and thy presses shall burst out with new wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 11, E'My son, despise not the chastening of the LORD; neither be weary of his correction:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 12, E'For whom the LORD loveth he correcteth; even as a father the son in whom he delighteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 13, E'Happy is the man that findeth wisdom, and the man that getteth understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 14, E'For the merchandise of it is better than the merchandise of silver, and the gain thereof than fine gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 15, E'She is more precious than rubies: and all the things thou canst desire are not to be compared unto her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 16, E'Length of days is in her right hand; and in her left hand riches and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 17, E'Her ways are ways of pleasantness, and all her paths are peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 18, E'She is a tree of life to them that lay hold upon her: and happy is every one that retaineth her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 19, E'The LORD by wisdom hath founded the earth; by understanding hath he established the heavens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 20, E'By his knowledge the depths are broken up, and the clouds drop down the dew.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 21, E'My son, let not them depart from thine eyes: keep sound wisdom and discretion:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 22, E'So shall they be life unto thy soul, and grace to thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 23, E'Then shalt thou walk in thy way safely, and thy foot shall not stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 24, E'When thou liest down, thou shalt not be afraid: yea, thou shalt lie down, and thy sleep shall be sweet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 25, E'Be not afraid of sudden fear, neither of the desolation of the wicked, when it cometh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 26, E'For the LORD shall be thy confidence, and shall keep thy foot from being taken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 27, E'Withhold not good from them to whom it is due, when it is in the power of thine hand to do it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 28, E'Say not unto thy neighbour, Go, and come again, and to morrow I will give; when thou hast it by thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 29, E'Devise not evil against thy neighbour, seeing he dwelleth securely by thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 30, E'Strive not with a man without cause, if he have done thee no harm.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 31, E'Envy thou not the oppressor, and choose none of his ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 32, E'For the froward is abomination to the LORD: but his secret is with the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 33, E'The curse of the LORD is in the house of the wicked: but he blesseth the habitation of the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 34, E'Surely he scorneth the scorners: but he giveth grace unto the lowly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 3, 35, E'The wise shall inherit glory: but shame shall be the promotion of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 1, E'Hear, ye children, the instruction of a father, and attend to know understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 2, E'For I give you good doctrine, forsake ye not my law.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 3, E'For I was my fatherâ€™s son, tender and only beloved in the sight of my mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 4, E'He taught me also, and said unto me, Let thine heart retain my words: keep my commandments, and live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 5, E'Get wisdom, get understanding: forget it not; neither decline from the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 6, E'Forsake her not, and she shall preserve thee: love her, and she shall keep thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 7, E'Wisdom is the principal thing; therefore get wisdom: and with all thy getting get understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 8, E'Exalt her, and she shall promote thee: she shall bring thee to honour, when thou dost embrace her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 9, E'She shall give to thine head an ornament of grace: a crown of glory shall she deliver to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 10, E'Hear, O my son, and receive my sayings; and the years of thy life shall be many.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 11, E'I have taught thee in the way of wisdom; I have led thee in right paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 12, E'When thou goest, thy steps shall not be straitened; and when thou runnest, thou shalt not stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 13, E'Take fast hold of instruction; let her not go: keep her; for she is thy life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 14, E'Enter not into the path of the wicked, and go not in the way of evil men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 15, E'Avoid it, pass not by it, turn from it, and pass away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 16, E'For they sleep not, except they have done mischief; and their sleep is taken away, unless they cause some to fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 17, E'For they eat the bread of wickedness, and drink the wine of violence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 18, E'But the path of the just is as the shining light, that shineth more and more unto the perfect day.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 19, E'The way of the wicked is as darkness: they know not at what they stumble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 20, E'My son, attend to my words; incline thine ear unto my sayings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 21, E'Let them not depart from thine eyes; keep them in the midst of thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 22, E'For they are life unto those that find them, and health to all their flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 23, E'Keep thy heart with all diligence; for out of it are the issues of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 24, E'Put away from thee a froward mouth, and perverse lips put far from thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 25, E'Let thine eyes look right on, and let thine eyelids look straight before thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 26, E'Ponder the path of thy feet, and let all thy ways be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 4, 27, E'Turn not to the right hand nor to the left: remove thy foot from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 1, E'My son, attend unto my wisdom, and bow thine ear to my understanding:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 2, E'That thou mayest regard discretion, and that thy lips may keep knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 3, E'For the lips of a strange woman drop as an honeycomb, and her mouth is smoother than oil:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 4, E'But her end is bitter as wormwood, sharp as a two-edged sword.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 5, E'Her feet go down to death; her steps take hold on hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 6, E'Lest thou shouldest ponder the path of life, her ways are moveable, that thou canst not know them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 7, E'Hear me now therefore, O ye children, and depart not from the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 8, E'Remove thy way far from her, and come not nigh the door of her house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 9, E'Lest thou give thine honour unto others, and thy years unto the cruel:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 10, E'Lest strangers be filled with thy wealth; and thy labours be in the house of a stranger;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 11, E'And thou mourn at the last, when thy flesh and thy body are consumed,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 12, E'And say, How have I hated instruction, and my heart despised reproof;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 13, E'And have not obeyed the voice of my teachers, nor inclined mine ear to them that instructed me!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 14, E'I was almost in all evil in the midst of the congregation and assembly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 15, E'Drink waters out of thine own cistern, and running waters out of thine own well.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 16, E'Let thy fountains be dispersed abroad, and rivers of waters in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 17, E'Let them be only thine own, and not strangersâ€™ with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 18, E'Let thy fountain be blessed: and rejoice with the wife of thy youth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 19, E'Let her be as the loving hind and pleasant roe; let her breasts satisfy thee at all times; and be thou ravished always with her love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 20, E'And why wilt thou, my son, be ravished with a strange woman, and embrace the bosom of a stranger?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 21, E'For the ways of man are before the eyes of the LORD, and he pondereth all his goings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 22, E'His own iniquities shall take the wicked himself, and he shall be holden with the cords of his sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 5, 23, E'He shall die without instruction; and in the greatness of his folly he shall go astray.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 1, E'My son, if thou be surety for thy friend, if thou hast stricken thy hand with a stranger,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 2, E'Thou art snared with the words of thy mouth, thou art taken with the words of thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 3, E'Do this now, my son, and deliver thyself, when thou art come into the hand of thy friend; go, humble thyself, and make sure thy friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 4, E'Give not sleep to thine eyes, nor slumber to thine eyelids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 5, E'Deliver thyself as a roe from the hand of the hunter, and as a bird from the hand of the fowler.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 6, E'Go to the ant, thou sluggard; consider her ways, and be wise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 7, E'Which having no guide, overseer, or ruler,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 8, E'Provideth her meat in the summer, and gathereth her food in the harvest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 9, E'How long wilt thou sleep, O sluggard? when wilt thou arise out of thy sleep?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 10, E'Yet a little sleep, a little slumber, a little folding of the hands to sleep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 11, E'So shall thy poverty come as one that travelleth, and thy want as an armed man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 12, E'A naughty person, a wicked man, walketh with a froward mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 13, E'He winketh with his eyes, he speaketh with his feet, he teacheth with his fingers;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 14, E'Frowardness is in his heart, he deviseth mischief continually; he soweth discord.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 15, E'Therefore shall his calamity come suddenly; suddenly shall he be broken without remedy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 16, E'These six things doth the LORD hate: yea, seven are an abomination unto him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 17, E'A proud look, a lying tongue, and hands that shed innocent blood,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 18, E'An heart that deviseth wicked imaginations, feet that be swift in running to mischief,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 19, E'A false witness that speaketh lies, and he that soweth discord among brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 20, E'My son, keep thy fatherâ€™s commandment, and forsake not the law of thy mother:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 21, E'Bind them continually upon thine heart, and tie them about thy neck.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 22, E'When thou goest, it shall lead thee; when thou sleepest, it shall keep thee; and when thou awakest, it shall talk with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 23, E'For the commandment is a lamp; and the law is light; and reproofs of instruction are the way of life:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 24, E'To keep thee from the evil woman, from the flattery of the tongue of a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 25, E'Lust not after her beauty in thine heart; neither let her take thee with her eyelids.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 26, E'For by means of a whorish woman a man is brought to a piece of bread: and the adulteress will hunt for the precious life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 27, E'Can a man take fire in his bosom, and his clothes not be burned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 28, E'Can one go upon hot coals, and his feet not be burned?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 29, E'So he that goeth in to his neighbourâ€™s wife; whosoever toucheth her shall not be innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 30, E'Men do not despise a thief, if he steal to satisfy his soul when he is hungry;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 31, E'But if he be found, he shall restore sevenfold; he shall give all the substance of his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 32, E'But whoso committeth adultery with a woman lacketh understanding: he that doeth it destroyeth his own soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 33, E'A wound and dishonour shall he get; and his reproach shall not be wiped away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 34, E'For jealousy is the rage of a man: therefore he will not spare in the day of vengeance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 6, 35, E'He will not regard any ransom; neither will he rest content, though thou givest many gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 1, E'My son, keep my words, and lay up my commandments with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 2, E'Keep my commandments, and live; and my law as the apple of thine eye.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 3, E'Bind them upon thy fingers, write them upon the table of thine heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 4, E'Say unto wisdom, Thou art my sister; and call understanding thy kinswoman:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 5, E'That they may keep thee from the strange woman, from the stranger which flattereth with her words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 6, E'For at the window of my house I looked through my casement,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 7, E'And beheld among the simple ones, I discerned among the youths, a young man void of understanding,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 8, E'Passing through the street near her corner; and he went the way to her house,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 9, E'In the twilight, in the evening, in the black and dark night:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 10, E'And, behold, there met him a woman with the attire of an harlot, and subtil of heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 11, E'(She is loud and stubborn; her feet abide not in her house:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 12, E'Now is she without, now in the streets, and lieth in wait at every corner.)'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 13, E'So she caught him, and kissed him, and with an impudent face said unto him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 14, E'I have peace offerings with me; this day have I payed my vows.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 15, E'Therefore came I forth to meet thee, diligently to seek thy face, and I have found thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 16, E'I have decked my bed with coverings of tapestry, with carved works, with fine linen of Egypt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 17, E'I have perfumed my bed with myrrh, aloes, and cinnamon.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 18, E'Come, let us take our fill of love until the morning: let us solace ourselves with loves.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 19, E'For the goodman is not at home, he is gone a long journey:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 20, E'He hath taken a bag of money with him, and will come home at the day appointed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 21, E'With her much fair speech she caused him to yield, with the flattering of her lips she forced him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 22, E'He goeth after her straightway, as an ox goeth to the slaughter, or as a fool to the correction of the stocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 23, E'Till a dart strike through his liver; as a bird hasteth to the snare, and knoweth not that it is for his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 24, E'Hearken unto me now therefore, O ye children, and attend to the words of my mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 25, E'Let not thine heart decline to her ways, go not astray in her paths.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 26, E'For she hath cast down many wounded: yea, many strong men have been slain by her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 7, 27, E'Her house is the way to hell, going down to the chambers of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 1, E'Doth not wisdom cry? and understanding put forth her voice?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 2, E'She standeth in the top of high places, by the way in the places of the paths.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 3, E'She crieth at the gates, at the entry of the city, at the coming in at the doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 4, E'Unto you, O men, I call; and my voice is to the sons of man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 5, E'O ye simple, understand wisdom: and, ye fools, be ye of an understanding heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 6, E'Hear; for I will speak of excellent things; and the opening of my lips shall be right things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 7, E'For my mouth shall speak truth; and wickedness is an abomination to my lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 8, E'All the words of my mouth are in righteousness; there is nothing froward or perverse in them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 9, E'They are all plain to him that understandeth, and right to them that find knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 10, E'Receive my instruction, and not silver; and knowledge rather than choice gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 11, E'For wisdom is better than rubies; and all the things that may be desired are not to be compared to it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 12, E'I wisdom dwell with prudence, and find out knowledge of witty inventions.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 13, E'The fear of the LORD is to hate evil: pride, and arrogancy, and the evil way, and the froward mouth, do I hate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 14, E'Counsel is mine, and sound wisdom: I am understanding; I have strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 15, E'By me kings reign, and princes decree justice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 16, E'By me princes rule, and nobles, even all the judges of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 17, E'I love them that love me; and those that seek me early shall find me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 18, E'Riches and honour are with me; yea, durable riches and righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 19, E'My fruit is better than gold, yea, than fine gold; and my revenue than choice silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 20, E'I lead in the way of righteousness, in the midst of the paths of judgment:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 21, E'That I may cause those that love me to inherit substance; and I will fill their treasures.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 22, E'The LORD possessed me in the beginning of his way, before his works of old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 23, E'I was set up from everlasting, from the beginning, or ever the earth was.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 24, E'When there were no depths, I was brought forth; when there were no fountains abounding with water.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 25, E'Before the mountains were settled, before the hills was I brought forth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 26, E'While as yet he had not made the earth, nor the fields, nor the highest part of the dust of the world.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 27, E'When he prepared the heavens, I was there: when he set a compass upon the face of the depth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 28, E'When he established the clouds above: when he strengthened the fountains of the deep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 29, E'When he gave to the sea his decree, that the waters should not pass his commandment: when he appointed the foundations of the earth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 30, E'Then I was by him, as one brought up with him: and I was daily his delight, rejoicing always before him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 31, E'Rejoicing in the habitable part of his earth; and my delights were with the sons of men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 32, E'Now therefore hearken unto me, O ye children: for blessed are they that keep my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 33, E'Hear instruction, and be wise, and refuse it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 34, E'Blessed is the man that heareth me, watching daily at my gates, waiting at the posts of my doors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 35, E'For whoso findeth me findeth life, and shall obtain favour of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 8, 36, E'But he that sinneth against me wrongeth his own soul: all they that hate me love death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 1, E'Wisdom hath builded her house, she hath hewn out her seven pillars:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 2, E'She hath killed her beasts; she hath mingled her wine; she hath also furnished her table.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 3, E'She hath sent forth her maidens: she crieth upon the highest places of the city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 4, E'Whoso is simple, let him turn in hither: as for him that wanteth understanding, she saith to him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 5, E'Come, eat of my bread, and drink of the wine which I have mingled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 6, E'Forsake the foolish, and live; and go in the way of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 7, E'He that reproveth a scorner getteth to himself shame: and he that rebuketh a wicked man getteth himself a blot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 8, E'Reprove not a scorner, lest he hate thee: rebuke a wise man, and he will love thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 9, E'Give instruction to a wise man, and he will be yet wiser: teach a just man, and he will increase in learning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 10, E'The fear of the LORD is the beginning of wisdom: and the knowledge of the holy is understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 11, E'For by me thy days shall be multiplied, and the years of thy life shall be increased.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 12, E'If thou be wise, thou shalt be wise for thyself: but if thou scornest, thou alone shalt bear it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 13, E'A foolish woman is clamorous: she is simple, and knoweth nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 14, E'For she sitteth at the door of her house, on a seat in the high places of the city,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 15, E'To call passengers who go right on their ways:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 16, E'Whoso is simple, let him turn in hither: and as for him that wanteth understanding, she saith to him,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 17, E'Stolen waters are sweet, and bread eaten in secret is pleasant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 9, 18, E'But he knoweth not that the dead are there; and that her guests are in the depths of hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 1, E'The proverbs of Solomon. A wise son maketh a glad father: but a foolish son is the heaviness of his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 2, E'Treasures of wickedness profit nothing: but righteousness delivereth from death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 3, E'The LORD will not suffer the soul of the righteous to famish: but he casteth away the substance of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 4, E'He becometh poor that dealeth with a slack hand: but the hand of the diligent maketh rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 5, E'He that gathereth in summer is a wise son: but he that sleepeth in harvest is a son that causeth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 6, E'Blessings are upon the head of the just: but violence covereth the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 7, E'The memory of the just is blessed: but the name of the wicked shall rot.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 8, E'The wise in heart will receive commandments: but a prating fool shall fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 9, E'He that walketh uprightly walketh surely: but he that perverteth his ways shall be known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 10, E'He that winketh with the eye causeth sorrow: but a prating fool shall fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 11, E'The mouth of a righteous man is a well of life: but violence covereth the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 12, E'Hatred stirreth up strifes: but love covereth all sins.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 13, E'In the lips of him that hath understanding wisdom is found: but a rod is for the back of him that is void of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 14, E'Wise men lay up knowledge: but the mouth of the foolish is near destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 15, E'The rich manâ€™s wealth is his strong city: the destruction of the poor is their poverty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 16, E'The labour of the righteous tendeth to life: the fruit of the wicked to sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 17, E'He is in the way of life that keepeth instruction: but he that refuseth reproof erreth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 18, E'He that hideth hatred with lying lips, and he that uttereth a slander, is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 19, E'In the multitude of words there wanteth not sin: but he that refraineth his lips is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 20, E'The tongue of the just is as choice silver: the heart of the wicked is little worth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 21, E'The lips of the righteous feed many: but fools die for want of wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 22, E'The blessing of the LORD, it maketh rich, and he addeth no sorrow with it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 23, E'It is as sport to a fool to do mischief: but a man of understanding hath wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 24, E'The fear of the wicked, it shall come upon him: but the desire of the righteous shall be granted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 25, E'As the whirlwind passeth, so is the wicked no more: but the righteous is an everlasting foundation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 26, E'As vinegar to the teeth, and as smoke to the eyes, so is the sluggard to them that send him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 27, E'The fear of the LORD prolongeth days: but the years of the wicked shall be shortened.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 28, E'The hope of the righteous shall be gladness: but the expectation of the wicked shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 29, E'The way of the LORD is strength to the upright: but destruction shall be to the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 30, E'The righteous shall never be removed: but the wicked shall not inhabit the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 31, E'The mouth of the just bringeth forth wisdom: but the froward tongue shall be cut out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 10, 32, E'The lips of the righteous know what is acceptable: but the mouth of the wicked speaketh frowardness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 1, E'A false balance is abomination to the LORD: but a just weight is his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 2, E'When pride cometh, then cometh shame: but with the lowly is wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 3, E'The integrity of the upright shall guide them: but the perverseness of transgressors shall destroy them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 4, E'Riches profit not in the day of wrath: but righteousness delivereth from death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 5, E'The righteousness of the perfect shall direct his way: but the wicked shall fall by his own wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 6, E'The righteousness of the upright shall deliver them: but transgressors shall be taken in their own naughtiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 7, E'When a wicked man dieth, his expectation shall perish: and the hope of unjust men perisheth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 8, E'The righteous is delivered out of trouble, and the wicked cometh in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 9, E'An hypocrite with his mouth destroyeth his neighbour: but through knowledge shall the just be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 10, E'When it goeth well with the righteous, the city rejoiceth: and when the wicked perish, there is shouting.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 11, E'By the blessing of the upright the city is exalted: but it is overthrown by the mouth of the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 12, E'He that is void of wisdom despiseth his neighbour: but a man of understanding holdeth his peace.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 13, E'A talebearer revealeth secrets: but he that is of a faithful spirit concealeth the matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 14, E'Where no counsel is, the people fall: but in the multitude of counsellors there is safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 15, E'He that is surety for a stranger shall smart for it: and he that hateth suretiship is sure.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 16, E'A gracious woman retaineth honour: and strong men retain riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 17, E'The merciful man doeth good to his own soul: but he that is cruel troubleth his own flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 18, E'The wicked worketh a deceitful work: but to him that soweth righteousness shall be a sure reward.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 19, E'As righteousness tendeth to life: so he that pursueth evil pursueth it to his own death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 20, E'They that are of a froward heart are abomination to the LORD: but such as are upright in their way are his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 21, E'Though hand join in hand, the wicked shall not be unpunished: but the seed of the righteous shall be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 22, E'As a jewel of gold in a swineâ€™s snout, so is a fair woman which is without discretion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 23, E'The desire of the righteous is only good: but the expectation of the wicked is wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 24, E'There is that scattereth, and yet increaseth; and there is that withholdeth more than is meet, but it tendeth to poverty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 25, E'The liberal soul shall be made fat: and he that watereth shall be watered also himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 26, E'He that withholdeth corn, the people shall curse him: but blessing shall be upon the head of him that selleth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 27, E'He that diligently seeketh good procureth favour: but he that seeketh mischief, it shall come unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 28, E'He that trusteth in his riches shall fall; but the righteous shall flourish as a branch.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 29, E'He that troubleth his own house shall inherit the wind: and the fool shall be servant to the wise of heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 30, E'The fruit of the righteous is a tree of life; and he that winneth souls is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 11, 31, E'Behold, the righteous shall be recompensed in the earth: much more the wicked and the sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 1, E'Whoso loveth instruction loveth knowledge: but he that hateth reproof is brutish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 2, E'A good man obtaineth favour of the LORD: but a man of wicked devices will he condemn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 3, E'A man shall not be established by wickedness: but the root of the righteous shall not be moved.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 4, E'A virtuous woman is a crown to her husband: but she that maketh ashamed is as rottenness in his bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 5, E'The thoughts of the righteous are right: but the counsels of the wicked are deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 6, E'The words of the wicked are to lie in wait for blood: but the mouth of the upright shall deliver them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 7, E'The wicked are overthrown, and are not: but the house of the righteous shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 8, E'A man shall be commended according to his wisdom: but he that is of a perverse heart shall be despised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 9, E'He that is despised, and hath a servant, is better than he that honoureth himself, and lacketh bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 10, E'A righteous man regardeth the life of his beast: but the tender mercies of the wicked are cruel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 11, E'He that tilleth his land shall be satisfied with bread: but he that followeth vain persons is void of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 12, E'The wicked desireth the net of evil men: but the root of the righteous yieldeth fruit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 13, E'The wicked is snared by the transgression of his lips: but the just shall come out of trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 14, E'A man shall be satisfied with good by the fruit of his mouth: and the recompence of a manâ€™s hands shall be rendered unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 15, E'The way of a fool is right in his own eyes: but he that hearkeneth unto counsel is wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 16, E'A foolâ€™s wrath is presently known: but a prudent man covereth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 17, E'He that speaketh truth sheweth forth righteousness: but a false witness deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 18, E'There is that speaketh like the piercings of a sword: but the tongue of the wise is health.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 19, E'The lip of truth shall be established for ever: but a lying tongue is but for a moment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 20, E'Deceit is in the heart of them that imagine evil: but to the counsellors of peace is joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 21, E'There shall no evil happen to the just: but the wicked shall be filled with mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 22, E'Lying lips are abomination to the LORD: but they that deal truly are his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 23, E'A prudent man concealeth knowledge: but the heart of fools proclaimeth foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 24, E'The hand of the diligent shall bear rule: but the slothful shall be under tribute.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 25, E'Heaviness in the heart of man maketh it stoop: but a good word maketh it glad.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 26, E'The righteous is more excellent than his neighbour: but the way of the wicked seduceth them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 27, E'The slothful man roasteth not that which he took in hunting: but the substance of a diligent man is precious.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 12, 28, E'In the way of righteousness is life: and in the pathway thereof there is no death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 1, E'A wise son heareth his fatherâ€™s instruction: but a scorner heareth not rebuke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 2, E'A man shall eat good by the fruit of his mouth: but the soul of the transgressors shall eat violence.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 3, E'He that keepeth his mouth keepeth his life: but he that openeth wide his lips shall have destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 4, E'The soul of the sluggard desireth, and hath nothing: but the soul of the diligent shall be made fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 5, E'A righteous man hateth lying: but a wicked man is loathsome, and cometh to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 6, E'Righteousness keepeth him that is upright in the way: but wickedness overthroweth the sinner.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 7, E'There is that maketh himself rich, yet hath nothing: there is that maketh himself poor, yet hath great riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 8, E'The ransom of a manâ€™s life are his riches: but the poor heareth not rebuke.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 9, E'The light of the righteous rejoiceth: but the lamp of the wicked shall be put out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 10, E'Only by pride cometh contention: but with the well advised is wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 11, E'Wealth gotten by vanity shall be diminished: but he that gathereth by labour shall increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 12, E'Hope deferred maketh the heart sick: but when the desire cometh, it is a tree of life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 13, E'Whoso despiseth the word shall be destroyed: but he that feareth the commandment shall be rewarded.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 14, E'The law of the wise is a fountain of life, to depart from the snares of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 15, E'Good understanding giveth favour: but the way of transgressors is hard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 16, E'Every prudent man dealeth with knowledge: but a fool layeth open his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 17, E'A wicked messenger falleth into mischief: but a faithful ambassador is health.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 18, E'Poverty and shame shall be to him that refuseth instruction: but he that regardeth reproof shall be honoured.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 19, E'The desire accomplished is sweet to the soul: but it is abomination to fools to depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 20, E'He that walketh with wise men shall be wise: but a companion of fools shall be destroyed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 21, E'Evil pursueth sinners: but to the righteous good shall be repayed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 22, E'A good man leaveth an inheritance to his childrenâ€™s children: and the wealth of the sinner is laid up for the just.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 23, E'Much food is in the tillage of the poor: but there is that is destroyed for want of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 24, E'He that spareth his rod hateth his son: but he that loveth him chasteneth him betimes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 13, 25, E'The righteous eateth to the satisfying of his soul: but the belly of the wicked shall want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 1, E'Every wise woman buildeth her house: but the foolish plucketh it down with her hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 2, E'He that walketh in his uprightness feareth the LORD: but he that is perverse in his ways despiseth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 3, E'In the mouth of the foolish is a rod of pride: but the lips of the wise shall preserve them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 4, E'Where no oxen are, the crib is clean: but much increase is by the strength of the ox.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 5, E'A faithful witness will not lie: but a false witness will utter lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 6, E'A scorner seeketh wisdom, and findeth it not: but knowledge is easy unto him that understandeth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 7, E'Go from the presence of a foolish man, when thou perceivest not in him the lips of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 8, E'The wisdom of the prudent is to understand his way: but the folly of fools is deceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 9, E'Fools make a mock at sin: but among the righteous there is favour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 10, E'The heart knoweth his own bitterness; and a stranger doth not intermeddle with his joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 11, E'The house of the wicked shall be overthrown: but the tabernacle of the upright shall flourish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 12, E'There is a way which seemeth right unto a man, but the end thereof are the ways of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 13, E'Even in laughter the heart is sorrowful; and the end of that mirth is heaviness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 14, E'The backslider in heart shall be filled with his own ways: and a good man shall be satisfied from himself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 15, E'The simple believeth every word: but the prudent man looketh well to his going.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 16, E'A wise man feareth, and departeth from evil: but the fool rageth, and is confident.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 17, E'He that is soon angry dealeth foolishly: and a man of wicked devices is hated.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 18, E'The simple inherit folly: but the prudent are crowned with knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 19, E'The evil bow before the good; and the wicked at the gates of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 20, E'The poor is hated even of his own neighbour: but the rich hath many friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 21, E'He that despiseth his neighbour sinneth: but he that hath mercy on the poor, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 22, E'Do they not err that devise evil? but mercy and truth shall be to them that devise good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 23, E'In all labour there is profit: but the talk of the lips tendeth only to penury.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 24, E'The crown of the wise is their riches: but the foolishness of fools is folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 25, E'A true witness delivereth souls: but a deceitful witness speaketh lies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 26, E'In the fear of the LORD is strong confidence: and his children shall have a place of refuge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 27, E'The fear of the LORD is a fountain of life, to depart from the snares of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 28, E'In the multitude of people is the kingâ€™s honour: but in the want of people is the destruction of the prince.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 29, E'He that is slow to wrath is of great understanding: but he that is hasty of spirit exalteth folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 30, E'A sound heart is the life of the flesh: but envy the rottenness of the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 31, E'He that oppresseth the poor reproacheth his Maker: but he that honoureth him hath mercy on the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 32, E'The wicked is driven away in his wickedness: but the righteous hath hope in his death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 33, E'Wisdom resteth in the heart of him that hath understanding: but that which is in the midst of fools is made known.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 34, E'Righteousness exalteth a nation: but sin is a reproach to any people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 14, 35, E'The kingâ€™s favour is toward a wise servant: but his wrath is against him that causeth shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 1, E'A soft answer turneth away wrath: but grievous words stir up anger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 2, E'The tongue of the wise useth knowledge aright: but the mouth of fools poureth out foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 3, E'The eyes of the LORD are in every place, beholding the evil and the good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 4, E'A wholesome tongue is a tree of life: but perverseness therein is a breach in the spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 5, E'A fool despiseth his fatherâ€™s instruction: but he that regardeth reproof is prudent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 6, E'In the house of the righteous is much treasure: but in the revenues of the wicked is trouble.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 7, E'The lips of the wise disperse knowledge: but the heart of the foolish doeth not so.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 8, E'The sacrifice of the wicked is an abomination to the LORD: but the prayer of the upright is his delight.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 9, E'The way of the wicked is an abomination unto the LORD: but he loveth him that followeth after righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 10, E'Correction is grievous unto him that forsaketh the way: and he that hateth reproof shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 11, E'Hell and destruction are before the LORD: how much more then the hearts of the children of men?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 12, E'A scorner loveth not one that reproveth him: neither will he go unto the wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 13, E'A merry heart maketh a cheerful countenance: but by sorrow of the heart the spirit is broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 14, E'The heart of him that hath understanding seeketh knowledge: but the mouth of fools feedeth on foolishness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 15, E'All the days of the afflicted are evil: but he that is of a merry heart hath a continual feast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 16, E'Better is little with the fear of the LORD than great treasure and trouble therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 17, E'Better is a dinner of herbs where love is, than a stalled ox and hatred therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 18, E'A wrathful man stirreth up strife: but he that is slow to anger appeaseth strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 19, E'The way of the slothful man is as an hedge of thorns: but the way of the righteous is made plain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 20, E'A wise son maketh a glad father: but a foolish man despiseth his mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 21, E'Folly is joy to him that is destitute of wisdom: but a man of understanding walketh uprightly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 22, E'Without counsel purposes are disappointed: but in the multitude of counsellors they are established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 23, E'A man hath joy by the answer of his mouth: and a word spoken in due season, how good is it!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 24, E'The way of life is above to the wise, that he may depart from hell beneath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 25, E'The LORD will destroy the house of the proud: but he will establish the border of the widow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 26, E'The thoughts of the wicked are an abomination to the LORD: but the words of the pure are pleasant words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 27, E'He that is greedy of gain troubleth his own house; but he that hateth gifts shall live.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 28, E'The heart of the righteous studieth to answer: but the mouth of the wicked poureth out evil things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 29, E'The LORD is far from the wicked: but he heareth the prayer of the righteous.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 30, E'The light of the eyes rejoiceth the heart: and a good report maketh the bones fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 31, E'The ear that heareth the reproof of life abideth among the wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 32, E'He that refuseth instruction despiseth his own soul: but he that heareth reproof getteth understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 15, 33, E'The fear of the LORD is the instruction of wisdom; and before honour is humility.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 1, E'The preparations of the heart in man, and the answer of the tongue, is from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 2, E'All the ways of a man are clean in his own eyes; but the LORD weigheth the spirits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 3, E'Commit thy works unto the LORD, and thy thoughts shall be established.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 4, E'The LORD hath made all things for himself: yea, even the wicked for the day of evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 5, E'Every one that is proud in heart is an abomination to the LORD: though hand join in hand, he shall not be unpunished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 6, E'By mercy and truth iniquity is purged: and by the fear of the LORD men depart from evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 7, E'When a manâ€™s ways please the LORD, he maketh even his enemies to be at peace with him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 8, E'Better is a little with righteousness than great revenues without right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 9, E'A manâ€™s heart deviseth his way: but the LORD directeth his steps.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 10, E'A divine sentence is in the lips of the king: his mouth transgresseth not in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 11, E'A just weight and balance are the LORDâ€™s: all the weights of the bag are his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 12, E'It is an abomination to kings to commit wickedness: for the throne is established by righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 13, E'Righteous lips are the delight of kings; and they love him that speaketh right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 14, E'The wrath of a king is as messengers of death: but a wise man will pacify it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 15, E'In the light of the kingâ€™s countenance is life; and his favour is as a cloud of the latter rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 16, E'How much better is it to get wisdom than gold! and to get understanding rather to be chosen than silver!'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 17, E'The highway of the upright is to depart from evil: he that keepeth his way preserveth his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 18, E'Pride goeth before destruction, and an haughty spirit before a fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 19, E'Better it is to be of an humble spirit with the lowly, than to divide the spoil with the proud.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 20, E'He that handleth a matter wisely shall find good: and whoso trusteth in the LORD, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 21, E'The wise in heart shall be called prudent: and the sweetness of the lips increaseth learning.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 22, E'Understanding is a wellspring of life unto him that hath it: but the instruction of fools is folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 23, E'The heart of the wise teacheth his mouth, and addeth learning to his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 24, E'Pleasant words are as an honeycomb, sweet to the soul, and health to the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 25, E'There is a way that seemeth right unto a man, but the end thereof are the ways of death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 26, E'He that laboureth laboureth for himself; for his mouth craveth it of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 27, E'An ungodly man diggeth up evil: and in his lips there is as a burning fire.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 28, E'A froward man soweth strife: and a whisperer separateth chief friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 29, E'A violent man enticeth his neighbour, and leadeth him into the way that is not good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 30, E'He shutteth his eyes to devise froward things: moving his lips he bringeth evil to pass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 31, E'The hoary head is a crown of glory, if it be found in the way of righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 32, E'He that is slow to anger is better than the mighty; and he that ruleth his spirit than he that taketh a city.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 16, 33, E'The lot is cast into the lap; but the whole disposing thereof is of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 1, E'Better is a dry morsel, and quietness therewith, than an house full of sacrifices with strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 2, E'A wise servant shall have rule over a son that causeth shame, and shall have part of the inheritance among the brethren.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 3, E'The fining pot is for silver, and the furnace for gold: but the LORD trieth the hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 4, E'A wicked doer giveth heed to false lips; and a liar giveth ear to a naughty tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 5, E'Whoso mocketh the poor reproacheth his Maker: and he that is glad at calamities shall not be unpunished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 6, E'Childrenâ€™s children are the crown of old men; and the glory of children are their fathers.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 7, E'Excellent speech becometh not a fool: much less do lying lips a prince.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 8, E'A gift is as a precious stone in the eyes of him that hath it: whithersoever it turneth, it prospereth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 9, E'He that covereth a transgression seeketh love; but he that repeateth a matter separateth very friends.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 10, E'A reproof entereth more into a wise man than an hundred stripes into a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 11, E'An evil man seeketh only rebellion: therefore a cruel messenger shall be sent against him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 12, E'Let a bear robbed of her whelps meet a man, rather than a fool in his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 13, E'Whoso rewardeth evil for good, evil shall not depart from his house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 14, E'The beginning of strife is as when one letteth out water: therefore leave off contention, before it be meddled with.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 15, E'He that justifieth the wicked, and he that condemneth the just, even they both are abomination to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 16, E'Wherefore is there a price in the hand of a fool to get wisdom, seeing he hath no heart to it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 17, E'A friend loveth at all times, and a brother is born for adversity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 18, E'A man void of understanding striketh hands, and becometh surety in the presence of his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 19, E'He loveth transgression that loveth strife: and he that exalteth his gate seeketh destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 20, E'He that hath a froward heart findeth no good: and he that hath a perverse tongue falleth into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 21, E'He that begetteth a fool doeth it to his sorrow: and the father of a fool hath no joy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 22, E'A merry heart doeth good like a medicine: but a broken spirit drieth the bones.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 23, E'A wicked man taketh a gift out of the bosom to pervert the ways of judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 24, E'Wisdom is before him that hath understanding; but the eyes of a fool are in the ends of the earth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 25, E'A foolish son is a grief to his father, and bitterness to her that bare him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 26, E'Also to punish the just is not good, nor to strike princes for equity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 27, E'He that hath knowledge spareth his words: and a man of understanding is of an excellent spirit.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 17, 28, E'Even a fool, when he holdeth his peace, is counted wise: and he that shutteth his lips is esteemed a man of understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 1, E'Through desire a man, having separated himself, seeketh and intermeddleth with all wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 2, E'A fool hath no delight in understanding, but that his heart may discover itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 3, E'When the wicked cometh, then cometh also contempt, and with ignominy reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 4, E'The words of a manâ€™s mouth are as deep waters, and the wellspring of wisdom as a flowing brook.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 5, E'It is not good to accept the person of the wicked, to overthrow the righteous in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 6, E'A foolâ€™s lips enter into contention, and his mouth calleth for strokes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 7, E'A foolâ€™s mouth is his destruction, and his lips are the snare of his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 8, E'The words of a talebearer are as wounds, and they go down into the innermost parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 9, E'He also that is slothful in his work is brother to him that is a great waster.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 10, E'The name of the LORD is a strong tower: the righteous runneth into it, and is safe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 11, E'The rich manâ€™s wealth is his strong city, and as an high wall in his own conceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 12, E'Before destruction the heart of man is haughty, and before honour is humility.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 13, E'He that answereth a matter before he heareth it, it is folly and shame unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 14, E'The spirit of a man will sustain his infirmity; but a wounded spirit who can bear?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 15, E'The heart of the prudent getteth knowledge; and the ear of the wise seeketh knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 16, E'A manâ€™s gift maketh room for him, and bringeth him before great men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 17, E'He that is first in his own cause seemeth just; but his neighbour cometh and searcheth him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 18, E'The lot causeth contentions to cease, and parteth between the mighty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 19, E'A brother offended is harder to be won than a strong city: and their contentions are like the bars of a castle.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 20, E'A manâ€™s belly shall be satisfied with the fruit of his mouth; and with the increase of his lips shall he be filled.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 21, E'Death and life are in the power of the tongue: and they that love it shall eat the fruit thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 22, E'Whoso findeth a wife findeth a good thing, and obtaineth favour of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 23, E'The poor useth intreaties; but the rich answereth roughly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 18, 24, E'A man that hath friends must shew himself friendly: and there is a friend that sticketh closer than a brother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 1, E'Better is the poor that walketh in his integrity, than he that is perverse in his lips, and is a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 2, E'Also, that the soul be without knowledge, it is not good; and he that hasteth with his feet sinneth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 3, E'The foolishness of man perverteth his way: and his heart fretteth against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 4, E'Wealth maketh many friends; but the poor is separated from his neighbour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 5, E'A false witness shall not be unpunished, and he that speaketh lies shall not escape.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 6, E'Many will intreat the favour of the prince: and every man is a friend to him that giveth gifts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 7, E'All the brethren of the poor do hate him: how much more do his friends go far from him? he pursueth them with words, yet they are wanting to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 8, E'He that getteth wisdom loveth his own soul: he that keepeth understanding shall find good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 9, E'A false witness shall not be unpunished, and he that speaketh lies shall perish.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 10, E'Delight is not seemly for a fool; much less for a servant to have rule over princes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 11, E'The discretion of a man deferreth his anger; and it is his glory to pass over a transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 12, E'The kingâ€™s wrath is as the roaring of a lion; but his favour is as dew upon the grass.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 13, E'A foolish son is the calamity of his father: and the contentions of a wife are a continual dropping.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 14, E'House and riches are the inheritance of fathers: and a prudent wife is from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 15, E'Slothfulness casteth into a deep sleep; and an idle soul shall suffer hunger.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 16, E'He that keepeth the commandment keepeth his own soul; but he that despiseth his ways shall die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 17, E'He that hath pity upon the poor lendeth unto the LORD; and that which he hath given will he pay him again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 18, E'Chasten thy son while there is hope, and let not thy soul spare for his crying.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 19, E'A man of great wrath shall suffer punishment: for if thou deliver him, yet thou must do it again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 20, E'Hear counsel, and receive instruction, that thou mayest be wise in thy latter end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 21, E'There are many devices in a manâ€™s heart; nevertheless the counsel of the LORD, that shall stand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 22, E'The desire of a man is his kindness: and a poor man is better than a liar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 23, E'The fear of the LORD tendeth to life: and he that hath it shall abide satisfied; he shall not be visited with evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 24, E'A slothful man hideth his hand in his bosom, and will not so much as bring it to his mouth again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 25, E'Smite a scorner, and the simple will beware: and reprove one that hath understanding, and he will understand knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 26, E'He that wasteth his father, and chaseth away his mother, is a son that causeth shame, and bringeth reproach.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 27, E'Cease, my son, to hear the instruction that causeth to err from the words of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 28, E'An ungodly witness scorneth judgment: and the mouth of the wicked devoureth iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 19, 29, E'Judgments are prepared for scorners, and stripes for the back of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 1, E'Wine is a mocker, strong drink is raging: and whosoever is deceived thereby is not wise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 2, E'The fear of a king is as the roaring of a lion: whoso provoketh him to anger sinneth against his own soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 3, E'It is an honour for a man to cease from strife: but every fool will be meddling.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 4, E'The sluggard will not plow by reason of the cold; therefore shall he beg in harvest, and have nothing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 5, E'Counsel in the heart of man is like deep water; but a man of understanding will draw it out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 6, E'Most men will proclaim every one his own goodness: but a faithful man who can find?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 7, E'The just man walketh in his integrity: his children are blessed after him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 8, E'A king that sitteth in the throne of judgment scattereth away all evil with his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 9, E'Who can say, I have made my heart clean, I am pure from my sin?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 10, E'Divers weights, and divers measures, both of them are alike abomination to the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 11, E'Even a child is known by his doings, whether his work be pure, and whether it be right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 12, E'The hearing ear, and the seeing eye, the LORD hath made even both of them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 13, E'Love not sleep, lest thou come to poverty; open thine eyes, and thou shalt be satisfied with bread.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 14, E'It is naught, it is naught, saith the buyer: but when he is gone his way, then he boasteth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 15, E'There is gold, and a multitude of rubies: but the lips of knowledge are a precious jewel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 16, E'Take his garment that is surety for a stranger: and take a pledge of him for a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 17, E'Bread of deceit is sweet to a man; but afterwards his mouth shall be filled with gravel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 18, E'Every purpose is established by counsel: and with good advice make war.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 19, E'He that goeth about as a talebearer revealeth secrets: therefore meddle not with him that flattereth with his lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 20, E'Whoso curseth his father or his mother, his lamp shall be put out in obscure darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 21, E'An inheritance may be gotten hastily at the beginning; but the end thereof shall not be blessed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 22, E'Say not thou, I will recompense evil; but wait on the LORD, and he shall save thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 23, E'Divers weights are an abomination unto the LORD; and a false balance is not good.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 24, E'Manâ€™s goings are of the LORD; how can a man then understand his own way?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 25, E'It is a snare to the man who devoureth that which is holy, and after vows to make enquiry.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 26, E'A wise king scattereth the wicked, and bringeth the wheel over them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 27, E'The spirit of man is the candle of the LORD, searching all the inward parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 28, E'Mercy and truth preserve the king: and his throne is upholden by mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 29, E'The glory of young men is their strength: and the beauty of old men is the grey head.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 20, 30, E'The blueness of a wound cleanseth away evil: so do stripes the inward parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 1, E'The kingâ€™s heart is in the hand of the LORD, as the rivers of water: he turneth it whithersoever he will.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 2, E'Every way of a man is right in his own eyes: but the LORD pondereth the hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 3, E'To do justice and judgment is more acceptable to the LORD than sacrifice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 4, E'An high look, and a proud heart, and the plowing of the wicked, is sin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 5, E'The thoughts of the diligent tend only to plenteousness; but of every one that is hasty only to want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 6, E'The getting of treasures by a lying tongue is a vanity tossed to and fro of them that seek death.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 7, E'The robbery of the wicked shall destroy them; because they refuse to do judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 8, E'The way of man is froward and strange: but as for the pure, his work is right.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 9, E'It is better to dwell in a corner of the housetop, than with a brawling woman in a wide house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 10, E'The soul of the wicked desireth evil: his neighbour findeth no favour in his eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 11, E'When the scorner is punished, the simple is made wise: and when the wise is instructed, he receiveth knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 12, E'The righteous man wisely considereth the house of the wicked: but God overthroweth the wicked for their wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 13, E'Whoso stoppeth his ears at the cry of the poor, he also shall cry himself, but shall not be heard.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 14, E'A gift in secret pacifieth anger: and a reward in the bosom strong wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 15, E'It is joy to the just to do judgment: but destruction shall be to the workers of iniquity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 16, E'The man that wandereth out of the way of understanding shall remain in the congregation of the dead.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 17, E'He that loveth pleasure shall be a poor man: he that loveth wine and oil shall not be rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 18, E'The wicked shall be a ransom for the righteous, and the transgressor for the upright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 19, E'It is better to dwell in the wilderness, than with a contentious and an angry woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 20, E'There is treasure to be desired and oil in the dwelling of the wise; but a foolish man spendeth it up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 21, E'He that followeth after righteousness and mercy findeth life, righteousness, and honour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 22, E'A wise man scaleth the city of the mighty, and casteth down the strength of the confidence thereof.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 23, E'Whoso keepeth his mouth and his tongue keepeth his soul from troubles.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 24, E'Proud and haughty scorner is his name, who dealeth in proud wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 25, E'The desire of the slothful killeth him; for his hands refuse to labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 26, E'He coveteth greedily all the day long: but the righteous giveth and spareth not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 27, E'The sacrifice of the wicked is abomination: how much more, when he bringeth it with a wicked mind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 28, E'A false witness shall perish: but the man that heareth speaketh constantly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 29, E'A wicked man hardeneth his face: but as for the upright, he directeth his way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 30, E'There is no wisdom nor understanding nor counsel against the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 21, 31, E'The horse is prepared against the day of battle: but safety is of the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 1, E'A GOOD name is rather to be chosen than great riches, and loving favour rather than silver and gold.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 2, E'The rich and poor meet together: the LORD is the maker of them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 3, E'A prudent man foreseeth the evil, and hideth himself: but the simple pass on, and are punished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 4, E'By humility and the fear of the LORD are riches, and honour, and life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 5, E'Thorns and snares are in the way of the froward: he that doth keep his soul shall be far from them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 6, E'Train up a child in the way he should go: and when he is old, he will not depart from it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 7, E'The rich ruleth over the poor, and the borrower is servant to the lender.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 8, E'He that soweth iniquity shall reap vanity: and the rod of his anger shall fail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 9, E'He that hath a bountiful eye shall be blessed; for he giveth of his bread to the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 10, E'Cast out the scorner, and contention shall go out; yea, strife and reproach shall cease.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 11, E'He that loveth pureness of heart, for the grace of his lips the king shall be his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 12, E'The eyes of the LORD preserve knowledge, and he overthroweth the words of the transgressor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 13, E'The slothful man saith, There is a lion without, I shall be slain in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 14, E'The mouth of strange women is a deep pit: he that is abhorred of the LORD shall fall therein.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 15, E'Foolishness is bound in the heart of a child; but the rod of correction shall drive it far from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 16, E'He that oppresseth the poor to increase his riches, and he that giveth to the rich, shall surely come to want.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 17, E'Bow down thine ear, and hear the words of the wise, and apply thine heart unto my knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 18, E'For it is a pleasant thing if thou keep them within thee; they shall withal be fitted in thy lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 19, E'That thy trust may be in the LORD, I have made known to thee this day, even to thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 20, E'Have not I written to thee excellent things in counsels and knowledge,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 21, E'That I might make thee know the certainty of the words of truth; that thou mightest answer the words of truth to them that send unto thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 22, E'Rob not the poor, because he is poor: neither oppress the afflicted in the gate:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 23, E'For the LORD will plead their cause, and spoil the soul of those that spoiled them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 24, E'Make no friendship with an angry man; and with a furious man thou shalt not go:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 25, E'Lest thou learn his ways, and get a snare to thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 26, E'Be not thou one of them that strike hands, or of them that are sureties for debts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 27, E'If thou hast nothing to pay, why should he take away thy bed from under thee?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 28, E'Remove not the ancient landmark, which thy fathers have set.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 22, 29, E'Seest thou a man diligent in his business? he shall stand before kings; he shall not stand before mean men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 1, E'When thou sittest to eat with a ruler, consider diligently what is before thee:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 2, E'And put a knife to thy throat, if thou be a man given to appetite.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 3, E'Be not desirous of his dainties: for they are deceitful meat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 4, E'Labour not to be rich: cease from thine own wisdom.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 5, E'Wilt thou set thine eyes upon that which is not? for riches certainly make themselves wings; they fly away as an eagle toward heaven.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 6, E'Eat thou not the bread of him that hath an evil eye, neither desire thou his dainty meats:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 7, E'For as he thinketh in his heart, so is he: Eat and drink, saith he to thee; but his heart is not with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 8, E'The morsel which thou hast eaten shalt thou vomit up, and lose thy sweet words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 9, E'Speak not in the ears of a fool: for he will despise the wisdom of thy words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 10, E'Remove not the old landmark; and enter not into the fields of the fatherless:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 11, E'For their redeemer is mighty; he shall plead their cause with thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 12, E'Apply thine heart unto instruction, and thine ears to the words of knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 13, E'Withhold not correction from the child: for if thou beatest him with the rod, he shall not die.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 14, E'Thou shalt beat him with the rod, and shalt deliver his soul from hell.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 15, E'My son, if thine heart be wise, my heart shall rejoice, even mine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 16, E'Yea, my reins shall rejoice, when thy lips speak right things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 17, E'Let not thine heart envy sinners: but be thou in the fear of the LORD all the day long.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 18, E'For surely there is an end; and thine expectation shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 19, E'Hear thou, my son, and be wise, and guide thine heart in the way.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 20, E'Be not among winebibbers; among riotous eaters of flesh:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 21, E'For the drunkard and the glutton shall come to poverty: and drowsiness shall clothe a man with rags.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 22, E'Hearken unto thy father that begat thee, and despise not thy mother when she is old.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 23, E'Buy the truth, and sell it not; also wisdom, and instruction, and understanding.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 24, E'The father of the righteous shall greatly rejoice: and he that begetteth a wise child shall have joy of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 25, E'Thy father and thy mother shall be glad, and she that bare thee shall rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 26, E'My son, give me thine heart, and let thine eyes observe my ways.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 27, E'For a whore is a deep ditch; and a strange woman is a narrow pit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 28, E'She also lieth in wait as for a prey, and increaseth the transgressors among men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 29, E'Who hath woe? who hath sorrow? who hath contentions? who hath babbling? who hath wounds without cause? who hath redness of eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 30, E'They that tarry long at the wine; they that go to seek mixed wine.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 31, E'Look not thou upon the wine when it is red, when it giveth his colour in the cup, when it moveth itself aright.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 32, E'At the last it biteth like a serpent, and stingeth like an adder.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 33, E'Thine eyes shall behold strange women, and thine heart shall utter perverse things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 34, E'Yea, thou shalt be as he that lieth down in the midst of the sea, or as he that lieth upon the top of a mast.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 23, 35, E'They have stricken me, shalt thou say, and I was not sick; they have beaten me, and I felt it not: when shall I awake? I will seek it yet again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 1, E'Be not thou envious against evil men, neither desire to be with them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 2, E'For their heart studieth destruction, and their lips talk of mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 3, E'Through wisdom is an house builded; and by understanding it is established:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 4, E'And by knowledge shall the chambers be filled with all precious and pleasant riches.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 5, E'A wise man is strong; yea, a man of knowledge increaseth strength.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 6, E'For by wise counsel thou shalt make thy war: and in multitude of counsellors there is safety.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 7, E'Wisdom is too high for a fool: he openeth not his mouth in the gate.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 8, E'He that deviseth to do evil shall be called a mischievous person.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 9, E'The thought of foolishness is sin: and the scorner is an abomination to men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 10, E'If thou faint in the day of adversity, thy strength is small.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 11, E'If thou forbear to deliver them that are drawn unto death, and those that are ready to be slain;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 12, E'If thou sayest, Behold, we knew it not; doth not he that pondereth the heart consider it? and he that keepeth thy soul, doth not he know it? and shall not he render to every man according to his works?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 13, E'My son, eat thou honey, because it is good; and the honeycomb, which is sweet to thy taste:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 14, E'So shall the knowledge of wisdom be unto thy soul: when thou hast found it, then there shall be a reward, and thy expectation shall not be cut off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 15, E'Lay not wait, O wicked man, against the dwelling of the righteous; spoil not his resting place:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 16, E'For a just man falleth seven times, and riseth up again: but the wicked shall fall into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 17, E'Rejoice not when thine enemy falleth, and let not thine heart be glad when he stumbleth:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 18, E'Lest the LORD see it, and it displease him, and he turn away his wrath from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 19, E'Fret not thyself because of evil men, neither be thou envious at the wicked;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 20, E'For there shall be no reward to the evil man; the candle of the wicked shall be put out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 21, E'My son, fear thou the LORD and the king: and meddle not with them that are given to change:')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 22, E'For their calamity shall rise suddenly; and who knoweth the ruin of them both?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 23, E'These things also belong to the wise. It is not good to have respect of persons in judgment.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 24, E'He that saith unto the wicked, Thou art righteous; him shall the people curse, nations shall abhor him:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 25, E'But to them that rebuke him shall be delight, and a good blessing shall come upon them.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 26, E'Every man shall kiss his lips that giveth a right answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 27, E'Prepare thy work without, and make it fit for thyself in the field; and afterwards build thine house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 28, E'Be not a witness against thy neighbour without cause; and deceive not with thy lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 29, E'Say not, I will do so to him as he hath done to me: I will render to the man according to his work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 30, E'I went by the field of the slothful, and by the vineyard of the man void of understanding;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 31, E'And, lo, it was all grown over with thorns, and nettles had covered the face thereof, and the stone wall thereof was broken down.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 32, E'Then I saw, and considered it well: I looked upon it, and received instruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 33, E'Yet a little sleep, a little slumber, a little folding of the hands to sleep:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 24, 34, E'So shall thy poverty come as one that travelleth; and thy want as an armed man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 1, E'These are also proverbs of Solomon, which the men of Hezekiah king of Judah copied out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 2, E'It is the glory of God to conceal a thing: but the honour of kings is to search out a matter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 3, E'The heaven for height, and the earth for depth, and the heart of kings is unsearchable.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 4, E'Take away the dross from the silver, and there shall come forth a vessel for the finer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 5, E'Take away the wicked from before the king, and his throne shall be established in righteousness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 6, E'Put not forth thyself in the presence of the king, and stand not in the place of great men:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 7, E'For better it is that it be said unto thee, Come up hither; than that thou shouldest be put lower in the presence of the prince whom thine eyes have seen.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 8, E'Go not forth hastily to strive, lest thou know not what to do in the end thereof, when thy neighbour hath put thee to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 9, E'Debate thy cause with thy neighbour himself; and discover not a secret to another:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 10, E'Lest he that heareth it put thee to shame, and thine infamy turn not away.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 11, E'A word fitly spoken is like apples of gold in pictures of silver.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 12, E'As an earring of gold, and an ornament of fine gold, so is a wise reprover upon an obedient ear.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 13, E'As the cold of snow in the time of harvest, so is a faithful messenger to them that send him: for he refresheth the soul of his masters.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 14, E'Whoso boasteth himself of a false gift is like clouds and wind without rain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 15, E'By long forbearing is a prince persuaded, and a soft tongue breaketh the bone.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 16, E'Hast thou found honey? eat so much as is sufficient for thee, lest thou be filled therewith, and vomit it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 17, E'Withdraw thy foot from thy neighbourâ€™s house; lest he be weary of thee, and so hate thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 18, E'A man that beareth false witness against his neighbour is a maul, and a sword, and a sharp arrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 19, E'Confidence in an unfaithful man in time of trouble is like a broken tooth, and a foot out of joint.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 20, E'As he that taketh away a garment in cold weather, and as vinegar upon nitre, so is he that singeth songs to an heavy heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 21, E'If thine enemy be hungry, give him bread to eat; and if he be thirsty, give him water to drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 22, E'For thou shalt heap coals of fire upon his head, and the LORD shall reward thee.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 23, E'The north wind driveth away rain: so doth an angry countenance a backbiting tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 24, E'It is better to dwell in the corner of the housetop, than with a brawling woman and in a wide house.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 25, E'As cold waters to a thirsty soul, so is good news from a far country.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 26, E'A righteous man falling down before the wicked is as a troubled fountain, and a corrupt spring.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 27, E'It is not good to eat much honey: so for men to search their own glory is not glory.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 25, 28, E'He that hath no rule over his own spirit is like a city that is broken down, and without walls.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 1, E'As snow in summer, and as rain in harvest, so honour is not seemly for a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 2, E'As the bird by wandering, as the swallow by flying, so the curse causeless shall not come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 3, E'A whip for the horse, a bridle for the ass, and a rod for the foolâ€™s back.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 4, E'Answer not a fool according to his folly, lest thou also be like unto him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 5, E'Answer a fool according to his folly, lest he be wise in his own conceit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 6, E'He that sendeth a message by the hand of a fool cutteth off the feet, and drinketh damage.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 7, E'The legs of the lame are not equal: so is a parable in the mouth of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 8, E'As he that bindeth a stone in a sling, so is he that giveth honour to a fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 9, E'As a thorn goeth up into the hand of a drunkard, so is a parable in the mouth of fools.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 10, E'The great God that formed all things both rewardeth the fool, and rewardeth transgressors.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 11, E'As a dog returneth to his vomit, so a fool returneth to his folly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 12, E'Seest thou a man wise in his own conceit? there is more hope of a fool than of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 13, E'The slothful man saith, There is a lion in the way; a lion is in the streets.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 14, E'As the door turneth upon his hinges, so doth the slothful upon his bed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 15, E'The slothful hideth his hand in his bosom; it grieveth him to bring it again to his mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 16, E'The sluggard is wiser in his own conceit than seven men that can render a reason.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 17, E'He that passeth by, and meddleth with strife belonging not to him, is like one that taketh a dog by the ears.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 18, E'As a mad man who casteth firebrands, arrows, and death,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 19, E'So is the man that deceiveth his neighbour, and saith, Am not I in sport?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 20, E'Where no wood is, there the fire goeth out: so where there is no talebearer, the strife ceaseth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 21, E'As coals are to burning coals, and wood to fire; so is a contentious man to kindle strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 22, E'The words of a talebearer are as wounds, and they go down into the innermost parts of the belly.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 23, E'Burning lips and a wicked heart are like a potsherd covered with silver dross.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 24, E'He that hateth dissembleth with his lips, and layeth up deceit within him;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 25, E'When he speaketh fair, believe him not: for there are seven abominations in his heart.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 26, E'Whose hatred is covered by deceit, his wickedness shall be shewed before the whole congregation.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 27, E'Whoso diggeth a pit shall fall therein: and he that rolleth a stone, it will return upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 26, 28, E'A lying tongue hateth those that are afflicted by it; and a flattering mouth worketh ruin.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 1, E'Boast not thyself of to morrow; for thou knowest not what a day may bring forth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 2, E'Let another man praise thee, and not thine own mouth; a stranger, and not thine own lips.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 3, E'A stone is heavy, and the sand weighty; but a foolâ€™s wrath is heavier than them both.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 4, E'Wrath is cruel, and anger is outrageous; but who is able to stand before envy?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 5, E'Open rebuke is better than secret love.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 6, E'Faithful are the wounds of a friend; but the kisses of an enemy are deceitful.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 7, E'The full soul loatheth an honeycomb; but to the hungry soul every bitter thing is sweet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 8, E'As a bird that wandereth from her nest, so is a man that wandereth from his place.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 9, E'Ointment and perfume rejoice the heart: so doth the sweetness of a manâ€™s friend by hearty counsel.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 10, E'Thine own friend, and thy fatherâ€™s friend, forsake not; neither go into thy brotherâ€™s house in the day of thy calamity: for better is a neighbour that is near than a brother far off.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 11, E'My son, be wise, and make my heart glad, that I may answer him that reproacheth me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 12, E'A prudent man foreseeth the evil, and hideth himself; but the simple pass on, and are punished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 13, E'Take his garment that is surety for a stranger, and take a pledge of him for a strange woman.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 14, E'He that blesseth his friend with a loud voice, rising early in the morning, it shall be counted a curse to him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 15, E'A continual dropping in a very rainy day and a contentious woman are alike.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 16, E'Whosoever hideth her hideth the wind, and the ointment of his right hand, which bewrayeth itself.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 17, E'Iron sharpeneth iron; so a man sharpeneth the countenance of his friend.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 18, E'Whoso keepeth the fig tree shall eat the fruit thereof: so he that waiteth on his master shall be honoured.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 19, E'As in water face answereth to face, so the heart of man to man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 20, E'Hell and destruction are never full; so the eyes of man are never satisfied.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 21, E'As the fining pot for silver, and the furnace for gold; so is a man to his praise.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 22, E'Though thou shouldest bray a fool in a mortar among wheat with a pestle, yet will not his foolishness depart from him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 23, E'Be thou diligent to know the state of thy flocks, and look well to thy herds.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 24, E'For riches are not for ever: and doth the crown endure to every generation?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 25, E'The hay appeareth, and the tender grass sheweth itself, and herbs of the mountains are gathered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 26, E'The lambs are for thy clothing, and the goats are the price of the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 27, 27, E'And thou shalt have goatsâ€™ milk enough for thy food, for the food of thy household, and for the maintenance for thy maidens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 1, E'The wicked flee when no man pursueth: but the righteous are bold as a lion.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 2, E'For the transgression of a land many are the princes thereof: but by a man of understanding and knowledge the state thereof shall be prolonged.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 3, E'A poor man that oppresseth the poor is like a sweeping rain which leaveth no food.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 4, E'They that forsake the law praise the wicked: but such as keep the law contend with them.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 5, E'Evil men understand not judgment: but they that seek the LORD understand all things.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 6, E'Better is the poor that walketh in his uprightness, than he that is perverse in his ways, though he be rich.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 7, E'Whoso keepeth the law is a wise son: but he that is a companion of riotous men shameth his father.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 8, E'He that by usury and unjust gain increaseth his substance, he shall gather it for him that will pity the poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 9, E'He that turneth away his ear from hearing the law, even his prayer shall be abomination.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 10, E'Whoso causeth the righteous to go astray in an evil way, he shall fall himself into his own pit: but the upright shall have good things in possession.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 11, E'The rich man is wise in his own conceit; but the poor that hath understanding searcheth him out.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 12, E'When righteous men do rejoice, there is great glory: but when the wicked rise, a man is hidden.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 13, E'He that covereth his sins shall not prosper: but whoso confesseth and forsaketh them shall have mercy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 14, E'Happy is the man that feareth alway: but he that hardeneth his heart shall fall into mischief.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 15, E'As a roaring lion, and a ranging bear; so is a wicked ruler over the poor people.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 16, E'The prince that wanteth understanding is also a great oppressor: but he that hateth covetousness shall prolong his days.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 17, E'A man that doeth violence to the blood of any person shall flee to the pit; let no man stay him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 18, E'Whoso walketh uprightly shall be saved: but he that is perverse in his ways shall fall at once.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 19, E'He that tilleth his land shall have plenty of bread: but he that followeth after vain persons shall have poverty enough.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 20, E'A faithful man shall abound with blessings: but he that maketh haste to be rich shall not be innocent.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 21, E'To have respect of persons is not good: for for a piece of bread that man will transgress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 22, E'He that hasteth to be rich hath an evil eye, and considereth not that poverty shall come upon him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 23, E'He that rebuketh a man afterwards shall find more favour than he that flattereth with the tongue.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 24, E'Whoso robbeth his father or his mother, and saith, It is no transgression; the same is the companion of a destroyer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 25, E'He that is of a proud heart stirreth up strife: but he that putteth his trust in the LORD shall be made fat.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 26, E'He that trusteth in his own heart is a fool: but whoso walketh wisely, he shall be delivered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 27, E'He that giveth unto the poor shall not lack: but he that hideth his eyes shall have many a curse.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 28, 28, E'When the wicked rise, men hide themselves: but when they perish, the righteous increase.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 1, E'He, that being often reproved hardeneth his neck, shall suddenly be destroyed, and that without remedy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 2, E'When the righteous are in authority, the people rejoice: but when the wicked beareth rule, the people mourn.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 3, E'Whoso loveth wisdom rejoiceth his father: but he that keepeth company with harlots spendeth his substance.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 4, E'The king by judgment establisheth the land: but he that receiveth gifts overthroweth it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 5, E'A man that flattereth his neighbour spreadeth a net for his feet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 6, E'In the transgression of an evil man there is a snare: but the righteous doth sing and rejoice.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 7, E'The righteous considereth the cause of the poor: but the wicked regardeth not to know it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 8, E'Scornful men bring a city into a snare: but wise men turn away wrath.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 9, E'If a wise man contendeth with a foolish man, whether he rage or laugh, there is no rest.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 10, E'The bloodthirsty hate the upright: but the just seek his soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 11, E'A fool uttereth all his mind: but a wise man keepeth it in till afterwards.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 12, E'If a ruler hearken to lies, all his servants are wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 13, E'The poor and the deceitful man meet together: the LORD lighteneth both their eyes.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 14, E'The king that faithfully judgeth the poor, his throne shall be established for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 15, E'The rod and reproof give wisdom: but a child left to himself bringeth his mother to shame.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 16, E'When the wicked are multiplied, transgression increaseth: but the righteous shall see their fall.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 17, E'Correct thy son, and he shall give thee rest; yea, he shall give delight unto thy soul.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 18, E'Where there is no vision, the people perish: but he that keepeth the law, happy is he.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 19, E'A servant will not be corrected by words: for though he understand he will not answer.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 20, E'Seest thou a man that is hasty in his words? there is more hope of a fool than of him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 21, E'He that delicately bringeth up his servant from a child shall have him become his son at the length.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 22, E'An angry man stirreth up strife, and a furious man aboundeth in transgression.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 23, E'A manâ€™s pride shall bring him low: but honour shall uphold the humble in spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 24, E'Whoso is partner with a thief hateth his own soul: he heareth cursing, and bewrayeth it not.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 25, E'The fear of man bringeth a snare: but whoso putteth his trust in the LORD shall be safe.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 26, E'Many seek the rulerâ€™s favour; but every manâ€™s judgment cometh from the LORD.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 29, 27, E'An unjust man is an abomination to the just: and he that is upright in the way is abomination to the wicked.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 1, E'The words of Agur the son of Jakeh, even the prophecy: the man spake unto Ithiel, even unto Ithiel and Ucal,'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 2, E'Surely I am more brutish than any man, and have not the understanding of a man.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 3, E'I neither learned wisdom, nor have the knowledge of the holy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 4, E'Who hath ascended up into heaven, or descended? who hath gathered the wind in his fists? who hath bound the waters in a garment? who hath established all the ends of the earth? what is his name, and what is his sonâ€™s name, if thou canst tell?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 5, E'Every word of God is pure: he is a shield unto them that put their trust in him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 6, E'Add thou not unto his words, lest he reprove thee, and thou be found a liar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 7, E'Two things have I required of thee; deny me them not before I die:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 8, E'Remove far from me vanity and lies: give me neither poverty nor riches; feed me with food convenient for me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 9, E'Lest I be full, and deny thee, and say, Who is the LORD? or lest I be poor, and steal, and take the name of my God in vain.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 10, E'Accuse not a servant unto his master, lest he curse thee, and thou be found guilty.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 11, E'There is a generation that curseth their father, and doth not bless their mother.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 12, E'There is a generation that are pure in their own eyes, and yet is not washed from their filthiness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 13, E'There is a generation, O how lofty are their eyes! and their eyelids are lifted up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 14, E'There is a generation, whose teeth are as swords, and their jaw teeth as knives, to devour the poor from off the earth, and the needy from among men.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 15, E'The horseleach hath two daughters, crying, Give, give. There are three things that are never satisfied, yea, four things say not, It is enough:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 16, E'The grave; and the barren womb; the earth that is not filled with water; and the fire that saith not, It is enough.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 17, E'The eye that mocketh at his father, and despiseth to obey his mother, the ravens of the valley shall pick it out, and the young eagles shall eat it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 18, E'There be three things which are too wonderful for me, yea, four which I know not:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 19, E'The way of an eagle in the air; the way of a serpent upon a rock; the way of a ship in the midst of the sea; and the way of a man with a maid.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 20, E'Such is the way of an adulterous woman; she eateth, and wipeth her mouth, and saith, I have done no wickedness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 21, E'For three things the earth is disquieted, and for four which it cannot bear:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 22, E'For a servant when he reigneth; and a fool when he is filled with meat;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 23, E'For an odious woman when she is married; and an handmaid that is heir to her mistress.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 24, E'There be four things which are little upon the earth, but they are exceeding wise:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 25, E'The ants are a people not strong, yet they prepare their meat in the summer;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 26, E'The conies are but a feeble folk, yet make they their houses in the rocks;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 27, E'The locusts have no king, yet go they forth all of them by bands;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 28, E'The spider taketh hold with her hands, and is in kingsâ€™ palaces.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 29, E'There be three things which go well, yea, four are comely in going:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 30, E'A lion which is strongest among beasts, and turneth not away for any;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 31, E'A greyhound; an he goat also; and a king, against whom there is no rising up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 32, E'If thou hast done foolishly in lifting up thyself, or if thou hast thought evil, lay thine hand upon thy mouth.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 30, 33, E'Surely the churning of milk bringeth forth butter, and the wringing of the nose bringeth forth blood: so the forcing of wrath bringeth forth strife.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 1, E'The words of king Lemuel, the prophecy that his mother taught him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 2, E'What, my son? and what, the son of my womb? and what, the son of my vows?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 3, E'Give not thy strength unto women, nor thy ways to that which destroyeth kings.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 4, E'It is not for kings, O Lemuel, it is not for kings to drink wine; nor for princes strong drink:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 5, E'Lest they drink, and forget the law, and pervert the judgment of any of the afflicted.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 6, E'Give strong drink unto him that is ready to perish, and wine unto those that be of heavy hearts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 7, E'Let him drink, and forget his poverty, and remember his misery no more.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 8, E'Open thy mouth for the dumb in the cause of all such as are appointed to destruction.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 9, E'Open thy mouth, judge righteously, and plead the cause of the poor and needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 10, E'Who can find a virtuous woman? for her price is far above rubies.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 11, E'The heart of her husband doth safely trust in her, so that he shall have no need of spoil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 12, E'She will do him good and not evil all the days of her life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 13, E'She seeketh wool, and flax, and worketh willingly with her hands.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 14, E'She is like the merchantsâ€™ ships; she bringeth her food from afar.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 15, E'She riseth also while it is yet night, and giveth meat to her household, and a portion to her maidens.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 16, E'She considereth a field, and buyeth it: with the fruit of her hands she planteth a vineyard.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 17, E'She girdeth her loins with strength, and strengtheneth her arms.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 18, E'She perceiveth that her merchandise is good: her candle goeth not out by night.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 19, E'She layeth her hands to the spindle, and her hands hold the distaff.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 20, E'She stretcheth out her hand to the poor; yea, she reacheth forth her hands to the needy.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 21, E'She is not afraid of the snow for her household: for all her household are clothed with scarlet.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 22, E'She maketh herself coverings of tapestry; her clothing is silk and purple.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 23, E'Her husband is known in the gates, when he sitteth among the elders of the land.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 24, E'She maketh fine linen, and selleth it; and delivereth girdles unto the merchant.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 25, E'Strength and honour are her clothing; and she shall rejoice in time to come.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 26, E'She openeth her mouth with wisdom; and in her tongue is the law of kindness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 27, E'She looketh well to the ways of her household, and eateth not the bread of idleness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 28, E'Her children arise up, and call her blessed; her husband also, and he praiseth her.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 29, E'Many daughters have done virtuously, but thou excellest them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 30, E'Favour is deceitful, and beauty is vain: but a woman that feareth the LORD, she shall be praised.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', 'e1648d4d-66cd-4eb8-8d86-7a2cbfbb9fc2', 31, 31, E'Give her of the fruit of her hands; and let her own works praise her in the gates.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Proverbs') b
ON CONFLICT DO NOTHING;

INSERT INTO bible_verses (translation_id, book_id, chapter, verse, text)
SELECT t.id, b.id, v.chapter, v.verse, v.text
FROM (VALUES
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 1, E'The words of the Preacher, the son of David, king in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 2, E'Vanity of vanities, saith the Preacher, vanity of vanities; all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 3, E'What profit hath a man of all his labour which he taketh under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 4, E'One generation passeth away, and another generation cometh: but the earth abideth for ever.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 5, E'The sun also ariseth, and the sun goeth down, and hasteth to his place where he arose.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 6, E'The wind goeth toward the south, and turneth about unto the north; it whirleth about continually, and the wind returneth again according to his circuits.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 7, E'All the rivers run into the sea; yet the sea is not full; unto the place from whence the rivers come, thither they return again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 8, E'All things are full of labour; man cannot utter it: the eye is not satisfied with seeing, nor the ear filled with hearing.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 9, E'The thing that hath been, it is that which shall be; and that which is done is that which shall be done: and there is no new thing under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 10, E'Is there any thing whereof it may be said, See, this is new? it hath been already of old time, which was before us.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 11, E'There is no remembrance of former things; neither shall there be any remembrance of things that are to come with those that shall come after.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 12, E'I the Preacher was king over Israel in Jerusalem.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 13, E'And I gave my heart to seek and search out by wisdom concerning all things that are done under heaven: this sore travail hath God given to the sons of man to be exercised therewith.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 14, E'I have seen all the works that are done under the sun; and, behold, all is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 15, E'That which is crooked cannot be made straight: and that which is wanting cannot be numbered.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 16, E'I communed with mine own heart, saying, Lo, I am come to great estate, and have gotten more wisdom than all they that have been before me in Jerusalem: yea, my heart had great experience of wisdom and knowledge.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 17, E'And I gave my heart to know wisdom, and to know madness and folly: I perceived that this also is vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 1, 18, E'For in much wisdom is much grief: and he that increaseth knowledge increaseth sorrow.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 1, E'I said in mine heart, Go to now, I will prove thee with mirth, therefore enjoy pleasure: and, behold, this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 2, E'I said of laughter, It is mad: and of mirth, What doeth it?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 3, E'I sought in mine heart to give myself unto wine, yet acquainting mine heart with wisdom; and to lay hold on folly, till I might see what was that good for the sons of men, which they should do under the heaven all the days of their life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 4, E'I made me great works; I builded me houses; I planted me vineyards:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 5, E'I made me gardens and orchards, and I planted trees in them of all kind of fruits:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 6, E'I made me pools of water, to water therewith the wood that bringeth forth trees:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 7, E'I got me servants and maidens, and had servants born in my house; also I had great possessions of great and small cattle above all that were in Jerusalem before me:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 8, E'I gathered me also silver and gold, and the peculiar treasure of kings and of the provinces: I gat me men singers and women singers, and the delights of the sons of men, as musical instruments, and that of all sorts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 9, E'So I was great, and increased more than all that were before me in Jerusalem: also my wisdom remained with me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 10, E'And whatsoever mine eyes desired I kept not from them, I withheld not my heart from any joy; for my heart rejoiced in all my labour: and this was my portion of all my labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 11, E'Then I looked on all the works that my hands had wrought, and on the labour that I had laboured to do: and, behold, all was vanity and vexation of spirit, and there was no profit under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 12, E'And I turned myself to behold wisdom, and madness, and folly: for what can the man do that cometh after the king? even that which hath been already done.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 13, E'Then I saw that wisdom excelleth folly, as far as light excelleth darkness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 14, E'The wise manâ€™s eyes are in his head; but the fool walketh in darkness: and I myself perceived also that one event happeneth to them all.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 15, E'Then said I in my heart, As it happeneth to the fool, so it happeneth even to me; and why was I then more wise? Then I said in my heart, that this also is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 16, E'For there is no remembrance of the wise more than of the fool for ever; seeing that which now is in the days to come shall all be forgotten. And how dieth the wise man? as the fool.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 17, E'Therefore I hated life; because the work that is wrought under the sun is grievous unto me: for all is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 18, E'Yea, I hated all my labour which I had taken under the sun: because I should leave it unto the man that shall be after me.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 19, E'And who knoweth whether he shall be a wise man or a fool? yet shall he have rule over all my labour wherein I have laboured, and wherein I have shewed myself wise under the sun. This is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 20, E'Therefore I went about to cause my heart to despair of all the labour which I took under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 21, E'For there is a man whose labour is in wisdom, and in knowledge, and in equity; yet to a man that hath not laboured therein shall he leave it for his portion. This also is vanity and a great evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 22, E'For what hath man of all his labour, and of the vexation of his heart, wherein he hath laboured under the sun?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 23, E'For all his days are sorrows, and his travail grief; yea, his heart taketh not rest in the night. This is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 24, E'There is nothing better for a man, than that he should eat and drink, and that he should make his soul enjoy good in his labour. This also I saw, that it was from the hand of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 25, E'For who can eat, or who else can hasten hereunto, more than I?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 2, 26, E'For God giveth to a man that is good in his sight wisdom, and knowledge, and joy: but to the sinner he giveth travail, to gather and to heap up, that he may give to him that is good before God. This also is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 1, E'To every thing there is a season, and a time to every purpose under the heaven:'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 2, E'A time to be born, and a time to die; a time to plant, and a time to pluck up that which is planted;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 3, E'A time to kill, and a time to heal; a time to break down, and a time to build up;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 4, E'A time to weep, and a time to laugh; a time to mourn, and a time to dance;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 5, E'A time to cast away stones, and a time to gather stones together; a time to embrace, and a time to refrain from embracing;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 6, E'A time to get, and a time to lose; a time to keep, and a time to cast away;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 7, E'A time to rend, and a time to sew; a time to keep silence, and a time to speak;'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 8, E'A time to love, and a time to hate; a time of war, and a time of peace.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 9, E'What profit hath he that worketh in that wherein he laboureth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 10, E'I have seen the travail, which God hath given to the sons of men to be exercised in it.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 11, E'He hath made every thing beautiful in his time: also he hath set the world in their heart, so that no man can find out the work that God maketh from the beginning to the end.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 12, E'I know that there is no good in them, but for a man to rejoice, and to do good in his life.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 13, E'And also that every man should eat and drink, and enjoy the good of all his labour, it is the gift of God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 14, E'I know that, whatsoever God doeth, it shall be for ever: nothing can be put to it, nor any thing taken from it: and God doeth it, that men should fear before him.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 15, E'That which hath been is now; and that which is to be hath already been; and God requireth that which is past.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 16, E'And moreover I saw under the sun the place of judgment, that wickedness was there; and the place of righteousness, that iniquity was there.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 17, E'I said in mine heart, God shall judge the righteous and the wicked: for there is a time there for every purpose and for every work.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 18, E'I said in mine heart concerning the estate of the sons of men, that God might manifest them, and that they might see that they themselves are beasts.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 19, E'For that which befalleth the sons of men befalleth beasts; even one thing befalleth them: as the one dieth, so dieth the other; yea, they have all one breath; so that a man hath no preeminence above a beast: for all is vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 20, E'All go unto one place; all are of the dust, and all turn to dust again.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 21, E'Who knoweth the spirit of man that goeth upward, and the spirit of the beast that goeth downward to the earth?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 3, 22, E'Wherefore I perceive that there is nothing better, than that a man should rejoice in his own works; for that is his portion: for who shall bring him to see what shall be after him?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 1, E'So I returned, and considered all the oppressions that are done under the sun: and behold the tears of such as were oppressed, and they had no comforter; and on the side of their oppressors there was power; but they had no comforter.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 2, E'Wherefore I praised the dead which are already dead more than the living which are yet alive.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 3, E'Yea, better is he than both they, which hath not yet been, who hath not seen the evil work that is done under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 4, E'Again, I considered all travail, and every right work, that for this a man is envied of his neighbour. This is also vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 5, E'The fool foldeth his hands together, and eateth his own flesh.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 6, E'Better is an handful with quietness, than both the hands full with travail and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 7, E'Then I returned, and I saw vanity under the sun.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 8, E'There is one alone, and there is not a second; yea, he hath neither child nor brother: yet is there no end of all his labour; neither is his eye satisfied with riches; neither saith he, For whom do I labour, and bereave my soul of good? This is also vanity, yea, it is a sore travail.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 9, E'Two are better than one; because they have a good reward for their labour.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 10, E'For if they fall, the one will lift up his fellow: but woe to him that is alone when he falleth; for he hath not another to help him up.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 11, E'Again, if two lie together, then they have heat: but how can one be warm alone?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 12, E'And if one prevail against him, two shall withstand him; and a threefold cord is not quickly broken.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 13, E'Better is a poor and a wise child than an old and foolish king, who will no more be admonished.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 14, E'For out of prison he cometh to reign; whereas also he that is born in his kingdom becometh poor.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 15, E'I considered all the living which walk under the sun, with the second child that shall stand up in his stead.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 4, 16, E'There is no end of all the people, even of all that have been before them: they also that come after shall not rejoice in him. Surely this also is vanity and vexation of spirit.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 1, E'Keep thy foot when thou goest to the house of God, and be more ready to hear, than to give the sacrifice of fools: for they consider not that they do evil.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 2, E'Be not rash with thy mouth, and let not thine heart be hasty to utter any thing before God: for God is in heaven, and thou upon earth: therefore let thy words be few.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 3, E'For a dream cometh through the multitude of business; and a foolâ€™s voice is known by multitude of words.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 4, E'When thou vowest a vow unto God, defer not to pay it; for he hath no pleasure in fools: pay that which thou hast vowed.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 5, E'Better is it that thou shouldest not vow, than that thou shouldest vow and not pay.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 6, E'Suffer not thy mouth to cause thy flesh to sin; neither say thou before the angel, that it was an error: wherefore should God be angry at thy voice, and destroy the work of thine hands?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 7, E'For in the multitude of dreams and many words there are also divers vanities: but fear thou God.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 8, E'If thou seest the oppression of the poor, and violent perverting of judgment and justice in a province, marvel not at the matter: for he that is higher than the highest regardeth; and there be higher than they.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 9, E'Moreover the profit of the earth is for all: the king himself is served by the field.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 10, E'He that loveth silver shall not be satisfied with silver; nor he that loveth abundance with increase: this is also vanity.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 11, E'When goods increase, they are increased that eat them: and what good is there to the owners thereof, saving the beholding of them with their eyes?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 12, E'The sleep of a labouring man is sweet, whether he eat little or much: but the abundance of the rich will not suffer him to sleep.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 13, E'There is a sore evil which I have seen under the sun, namely, riches kept for the owners thereof to their hurt.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 14, E'But those riches perish by evil travail: and he begetteth a son, and there is nothing in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 15, E'As he came forth of his motherâ€™s womb, naked shall he return to go as he came, and shall take nothing of his labour, which he may carry away in his hand.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 16, E'And this also is a sore evil, that in all points as he came, so shall he go: and what profit hath he that hath laboured for the wind?'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 17, E'All his days also he eateth in darkness, and he hath much sorrow and wrath with his sickness.'),
    ('0fc0555e-d55e-4715-b1e1-d2c26c1c7be3', '87aac142-88d2-4329-a960-b6fdba60d816', 5, 18, E'Behold that which I have seen: it is good and comely for one to eat and to drink, and to enjoy the good of all his labour that he taketh under the sun all the days of his life, which God giveth him: for it is his portion.')
) AS v(translation_id, book_id, chapter, verse, text)
CROSS JOIN (SELECT id FROM bible_translations WHERE code = 'kjv') t
CROSS JOIN (SELECT id FROM bible_books WHERE name = 'Ecclesiastes') b
ON CONFLICT DO NOTHING;

